 const texto = String(
  $json.text ||
  $json.body?.texto_pdf ||
  $json.texto_pdf ||
  ""
);

/* ============================================================
   FUNÇÕES BÁSICAS
============================================================ */

function parseNumeroBR(valor) {
  return (
    Number(
      String(valor || "")
        .replace("R$", "")
        .replace(/\s/g, "")
        .replace(/\./g, "")
        .replace(",", ".")
        .replace(/[^\d.-]/g, "")
    ) || 0
  );
}

function limpar(txt) {
  return String(txt || "")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizarTexto(txt) {
  return limpar(txt)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

function dataISO(dia, mes, ano) {
  let a = String(
    ano || new Date().getFullYear()
  );

  if (a.length === 2) {
    a = `20${a}`;
  }

  return `${a}-${String(mes).padStart(
    2,
    "0"
  )}-${String(dia).padStart(2, "0")}`;
}

/* ============================================================
   EXTRAÇÃO DOS DADOS GERAIS DA FATURA
============================================================ */

function extrairTotal(textoCompleto) {
  const m =
    textoCompleto.match(
      /Saldo\s+Desta\s+Fatura\s+R?\$?\s*([\d.]+,\d{2})/i
    ) ||
    textoCompleto.match(
      /Valor\s+total\s+devido\s+R?\$?\s*([\d.]+,\d{2})/i
    ) ||
    textoCompleto.match(
      /Despesas\s+até\s+a\s+emissão\s+desta\s+fatura\s+R?\$?\s*([\d.]+,\d{2})/i
    ) ||
    textoCompleto.match(
      /Pagamento\s+total\s+R?\$?\s*([\d.]+,\d{2})/i
    ) ||
    textoCompleto.match(
      /Total\s+da\s+fatura\s+R?\$?\s*([\d.]+,\d{2})/i
    );

  return m
    ? parseNumeroBR(m[1])
    : null;
}

function extrairVencimentoPDF(textoCompleto) {
  const m = String(
    textoCompleto || ""
  ).match(
    /Vencimento\s+(\d{2})\/(\d{2})\/(\d{4})/i
  );

  if (!m) {
    return null;
  }

  return {
    data: `${m[3]}-${m[2]}-${m[1]}`,
    dia: Number(m[1]),
  };
}

function extrairFechamentoPDF(textoCompleto) {
  /*
    Usa o próximo fechamento, pois é o dia
    configurado atualmente para o cartão.
  */
  const m = String(
    textoCompleto || ""
  ).match(
    /Pr[oó]ximo\s+fechamento\s+(\d{2})\/(\d{2})\/(\d{4})/i
  );

  if (!m) {
    return null;
  }

  return {
    data: `${m[3]}-${m[2]}-${m[1]}`,
    dia: Number(m[1]),
  };
}

function extrairFaturaFechadaEm(
  textoCompleto
) {
  const m = String(
    textoCompleto || ""
  ).match(
    /Fatura\s+fechada\s+em\s+(\d{2})\/(\d{2})\/(\d{4})/i
  );

  if (!m) {
    return null;
  }

  return {
    data: `${m[3]}-${m[2]}-${m[1]}`,
    dia: Number(m[1]),
  };
}

function extrairFinaisCartoes(
  textoCompleto
) {
  const txt = String(
    textoCompleto || ""
  );

  const encontrados = [
    ...txt.matchAll(
      /\b\d{4}\*{4,}(\d{4})\b/g
    ),
  ];

  return [
    ...new Set(
      encontrados
        .map((item) => item[1])
        .filter(Boolean)
    ),
  ];
}

function extrairNomeCartaoPDF(
  textoCompleto
) {
  const txt = String(
    textoCompleto || ""
  );

  const m = txt.match(
    /Resumo\s+da\s+sua\s+fatura\s+(Cart[aã]o\s+.+?)\s+R\$/i
  );

  if (!m) {
    return null;
  }

  return limpar(m[1])
    .replace(
      /\bIn\s+fi\s+nite\b/gi,
      "Infinite"
    )
    .replace(
      /\bInfi\s+nite\b/gi,
      "Infinite"
    )
    .replace(/\s+/g, " ")
    .trim();
}

function extrairBandeiraPDF(
  textoCompleto
) {
  const txt = normalizarTexto(
    textoCompleto
  );

  if (txt.includes("visa")) {
    return "VISA";
  }

  if (
    txt.includes("mastercard") ||
    txt.includes("master card")
  ) {
    return "MASTERCARD";
  }

  if (txt.includes("elo")) {
    return "ELO";
  }

  if (
    txt.includes("american express") ||
    txt.includes("amex")
  ) {
    return "AMEX";
  }

  return null;
}

function extrairTitularPDF(
  textoCompleto
) {
  const m = String(
    textoCompleto || ""
  ).match(
    /Titular\s+(.+?)\s+Endere[cç]o/i
  );

  return m
    ? limpar(m[1])
    : null;
}

/* ============================================================
   REGRAS DE PAGAMENTO E LINHAS ADMINISTRATIVAS
============================================================ */

function ehPagamentoFatura(
  descricao,
  valor
) {
  if (Number(valor || 0) >= 0) {
    return false;
  }

  const txt =
    normalizarTexto(descricao);

  return (
    txt.includes("pagamento") ||
    txt.includes(
      "pagamentos validos"
    ) ||
    txt.includes(
      "pagamento recebido"
    ) ||
    txt.includes(
      "pagamento de fatura"
    )
  );
}

function ehLinhaAdministrativa(
  descricao
) {
  const txt =
    normalizarTexto(descricao);

  return (
    txt.includes("limite") ||
    txt.includes("boleto") ||
    txt.includes("nosso numero") ||
    txt.includes(
      "valor do documento"
    ) ||
    txt.includes("encargos") ||
    txt.includes(
      "resumo da fatura"
    ) ||
    txt.includes("total da fatura")
  );
}

/* ============================================================
   IDENTIFICAÇÃO DO BANCO
============================================================ */

const banco = /santander/i.test(texto)
  ? "Santander"
  : /XP|Banco XP/i.test(texto)
    ? "XP"
    : /bradesco/i.test(texto)
      ? "Bradesco"
      : /itau|itaú/i.test(texto)
        ? "Itaú"
        : /nubank/i.test(texto)
          ? "Nubank"
          : null;

/* ============================================================
   ANO PADRÃO
============================================================ */

const anoPadrao =
  (
    texto.match(/\b(20\d{2})\b/) || [
      null,
      String(
        new Date().getFullYear()
      ),
    ]
  )[1];

/* ============================================================
   PREPARAÇÃO DO TEXTO PARA EXTRAÇÃO DAS LINHAS
============================================================ */

let textoParse = texto
  .replace(/\r/g, "\n")
  .replace(/\u00a0/g, " ")
  .replace(
    /Data\s+Descrição\s+R\$\s+US\$/gi,
    "\nData Descrição R$ US$\n"
  )
  .replace(
    /Compra\s+Data\s+Descrição\s+Parcela\s+R\$\s+US\$/gi,
    "\nCompra Data Descrição Parcela R$ US$\n"
  )
  .replace(
    /Subtotal/gi,
    "\nSubtotal"
  )
  .replace(
    /VALOR\s+TOTAL/gi,
    "\nVALOR TOTAL"
  )
  .replace(
    /(\d{2}\/\d{2}\/\d{2,4})\s+/g,
    "\n$1 "
  )
  .replace(
    /(?:^|\s)(\d+)\s+(\d{2}\/\d{2})(?!\/)/g,
    "\n$1 $2"
  )
  .replace(/\n\s+/g, "\n");

/* ============================================================
   EXTRAÇÃO DAS TRANSAÇÕES
============================================================ */

const linhas = [];
let secao = "";

for (
  const raw of textoParse.split(/\n+/)
) {
  const linha = limpar(raw);

  if (!linha) {
    continue;
  }

  if (
    /Pagamento e Demais Créditos/i.test(
      linha
    )
  ) {
    secao = "creditos";
    continue;
  }

  if (/Parcelamentos/i.test(linha)) {
    secao = "parcelamentos";
    continue;
  }

  if (/Despesas/i.test(linha)) {
    secao = "despesas";
    continue;
  }

  if (
    /Resumo da Fatura/i.test(linha)
  ) {
    secao = "resumo";
    continue;
  }

  if (
    /Compra Data Descrição/i.test(
      linha
    )
  ) {
    continue;
  }

  if (/^Subtotal/i.test(linha)) {
    continue;
  }

  if (/^VALOR TOTAL/i.test(linha)) {
    continue;
  }

  if (secao === "resumo") {
    continue;
  }

  const m = linha.match(
    /^(?:\d+\s+)?(\d{2})\/(\d{2})(?:\/(\d{2,4}))?\s+(.+?)\s+(?:(?:-|–)?\s*Parcela\s+)?(?:(\d{1,2})\/(\d{1,2})\s+)?(-?[\d.]+,\d{2})(?:\s+[\d.]+,\d{2})?$/i
  );

  if (!m) {
    continue;
  }

  const valor =
    parseNumeroBR(m[7]);

  let descricao = limpar(m[4])
    .replace(/\s*-\s*$/g, "")
    .replace(
      /\s*Parcela\s*$/i,
      ""
    );

  if (
    ehLinhaAdministrativa(
      descricao
    )
  ) {
    continue;
  }

  /*
    Pagamento da fatura anterior:
    não entra na lista da fatura atual.
  */
  if (
    ehPagamentoFatura(
      descricao,
      valor
    )
  ) {
    continue;
  }

  const temParcela =
    Boolean(m[5]) &&
    Boolean(m[6]);

  const tipoLinha =
    valor < 0
      ? "credito"
      : temParcela
        ? "parcela"
        : "compra";

  linhas.push({
    linha: linhas.length + 1,

    data: dataISO(
      m[1],
      m[2],
      m[3] || anoPadrao
    ),

    estabelecimento:
      descricao,

    portador: null,

    /*
      Compra positiva.
      Crédito/estorno negativo.
    */
    valor,

    parcela: temParcela
      ? `${Number(m[5])}/${Number(
          m[6]
        )}`
      : null,

    parcela_atual: m[5]
      ? Number(m[5])
      : null,

    parcela_total: m[6]
      ? Number(m[6])
      : null,

    tipo_linha: tipoLinha,

    dados_originais: {
      origem: "PDF_N8N",
      secao,
      linha_original: linha,
    },
  });
}

/* ============================================================
   TOTAIS E VALIDAÇÃO
============================================================ */

const total_fatura =
  extrairTotal(texto);

const compras = Number(
  linhas
    .filter(
      (l) =>
        Number(l.valor || 0) > 0
    )
    .reduce(
      (soma, l) =>
        soma +
        Number(l.valor || 0),
      0
    )
    .toFixed(2)
);

const creditos_estornos =
  Number(
    linhas
      .filter(
        (l) =>
          Number(l.valor || 0) < 0
      )
      .reduce(
        (soma, l) =>
          soma +
          Math.abs(
            Number(l.valor || 0)
          ),
        0
      )
      .toFixed(2)
  );

const total_importado = Number(
  linhas
    .reduce(
      (soma, l) =>
        soma +
        Number(l.valor || 0),
      0
    )
    .toFixed(2)
);

const diferenca =
  total_fatura == null
    ? null
    : Number(
        (
          total_importado -
          Number(total_fatura)
        ).toFixed(2)
      );

const validacaoOk =
  total_fatura != null &&
  Math.abs(diferenca || 0) <=
    0.05;

/* ============================================================
   DADOS DO CARTÃO ENCONTRADOS NO PDF
============================================================ */

const finais_cartoes =
  extrairFinaisCartoes(texto);

const vencimento_pdf =
  extrairVencimentoPDF(texto);

const fechamento_pdf =
  extrairFechamentoPDF(texto);

const fatura_fechada_em =
  extrairFaturaFechadaEm(
    texto
  );

const nome_cartao_pdf =
  extrairNomeCartaoPDF(texto);

const bandeira_pdf =
  extrairBandeiraPDF(texto);

const titular_pdf =
  extrairTitularPDF(texto);

/* ============================================================
   RETORNO FINAL
============================================================ */

return [
  {
    json: {
      ok: linhas.length > 0,

      origem: "PDF_N8N",

      banco,

      /*
        Mantém um final principal
        para compatibilidade.
      */
      cartao_final:
        finais_cartoes[0] || null,

      /*
        Todos os finais encontrados.
        Exemplo: 9908 e 1223.
      */
      cartoes_finais:
        finais_cartoes,

      vencimento:
        vencimento_pdf?.data ||
        null,

      vencimento_dia:
        vencimento_pdf?.dia ||
        null,

      fechamento:
        fechamento_pdf?.data ||
        null,

      fechamento_dia:
        fechamento_pdf?.dia ||
        null,

      fatura_fechada_em:
        fatura_fechada_em?.data ||
        null,

      nome_cartao:
        nome_cartao_pdf,

      bandeira:
        bandeira_pdf,

      titular:
        titular_pdf,

      /*
        Objeto específico para a UI
        conferir o cartão selecionado.
      */
      dados_cartao_pdf: {
        banco,

        finais:
          finais_cartoes,

        vencimento:
          vencimento_pdf?.data ||
          null,

        vencimento_dia:
          vencimento_pdf?.dia ||
          null,

        fechamento:
          fechamento_pdf?.data ||
          null,

        fechamento_dia:
          fechamento_pdf?.dia ||
          null,

        nome:
          nome_cartao_pdf,

        bandeira:
          bandeira_pdf,

        titular:
          titular_pdf,
      },

      total_fatura,
      total_importado,
      compras,
      creditos_estornos,
      diferenca,

      validacao: {
        origem: "PDF_N8N",

        ok: validacaoOk,

        bloqueiaSalvar:
          total_fatura != null &&
          !validacaoOk,

        mensagem:
          total_fatura == null
            ? `Não localizei o total da fatura. Total líquido importado: ${total_importado}.`
            : validacaoOk
              ? `PDF validado: compras ${compras}, créditos/estornos -${creditos_estornos}, total líquido ${total_importado}.`
              : `Divergência no PDF: compras ${compras}, créditos/estornos -${creditos_estornos}, total líquido importado ${total_importado} x total da fatura ${total_fatura}. Diferença ${diferenca}.`,

        totalPDF:
          total_fatura,

        totalImportado:
          total_importado,

        compras,

        creditosEstornos:
          creditos_estornos,

        diferenca,
      },

      linhas,
    },
  },
];

 const texto = String(
  $json.texto_pdf ||
  $json.body?.texto_pdf ||
  $json.text ||
  ""
);

const normalizado = texto
  .toUpperCase()
  .normalize("NFD")
  .replace(/[\u0300-\u036f]/g, "");

let tipo_cartao = "DESCONHECIDO";

if (
  normalizado.includes("LUIZACRED") ||
  normalizado.includes("MAGAZINE LUIZA")
) {
  tipo_cartao = "MAGAZINE";
} else if (
  normalizado.includes("BANCO XP") ||
  normalizado.includes("XP INVESTIMENTOS") ||
  normalizado.includes("XP VISA")
) {
  tipo_cartao = "XP";
} else if (
  normalizado.includes("NUBANK")
) {
  tipo_cartao = "NUBANK";
} else if (
  normalizado.includes("BRADESCO")
) {
  tipo_cartao = "BRADESCO";
} else if (
  normalizado.includes("SANTANDER")
) {
  tipo_cartao = "SANTANDER";
}

return [
  {
    json: {
      ...$json,
      texto_pdf: texto,
      tipo_cartao,
    },
  },
];

 const texto = $json.text || "";

function parseNumeroBR(valor) {
  return (
    Number(
      String(valor || "")
        .replace("R$", "")
        .replace(/\s/g, "")
        .replace(/\./g, "")
        .replace(",", ".")
        .replace(/[^\d.-]/g, "")
    ) || 0
  );
}

function limparDescricao(txt) {
  return String(txt || "")
    .replace(/\s+/g, " ")
    .trim();
}

function extrairTotal(textoCompleto) {
  const m = textoCompleto.match(
    /Total Despesas\/D[eé]bitos no Brasil\s+([\d.]+,\d{2})/i
  );

  return m ? parseNumeroBR(m[1]) : null;
}

function extrairVencimento(textoCompleto) {
  const m = textoCompleto.match(
    /Vencimento\s+(\d{2})\/(\d{2})\/(\d{4})/i
  );

  if (!m) return null;

  return `${m[3]}-${m[2]}-${m[1]}`;
}

function extrairCartaoFinal(textoCompleto) {
  const m = textoCompleto.match(
    /XXXX\s+XXXX\s+(\d{4})/i
  );

  return m ? m[1] : null;
}

const ano =
  (
    texto.match(/\b(20\d{2})\b/) || [
      null,
      String(new Date().getFullYear()),
    ]
  )[1];

const linhas = [];
let secao = "";

for (const raw of texto.split(/\n+/)) {
  const linha = raw.trim();

  if (!linha) continue;

  if (/Pagamento e Demais Créditos/i.test(linha)) {
    secao = "creditos";
    continue;
  }

  if (/Parcelamentos/i.test(linha)) {
    secao = "parcelamentos";
    continue;
  }

  if (/Despesas/i.test(linha)) {
    secao = "despesas";
    continue;
  }

  if (/Resumo da Fatura/i.test(linha)) {
    secao = "resumo";
    continue;
  }

  if (secao === "resumo") continue;
  if (/Compra Data Descrição Parcela/i.test(linha)) continue;
  if (/VALOR TOTAL/i.test(linha)) continue;

  const m = linha.match(
    /^(?:\d+\s+)?(\d{2})\/(\d{2})\s+(.+?)\s+(?:(\d{1,2})\/(\d{1,2})\s+)?(-?[\d.]+,\d{2})$/i
  );

  if (!m) continue;

  const valor = parseNumeroBR(m[6]);

  if (secao === "creditos" || valor < 0) {
    continue;
  }

  const descricao = limparDescricao(m[3]);

  const parcelaAtual = m[4]
    ? Number(m[4])
    : null;

  const parcelaTotal = m[5]
    ? Number(m[5])
    : null;

  const temParcelamento =
    parcelaAtual !== null &&
    parcelaTotal !== null;

  /*
    Regra correta:

    Sem parcelamento = compra
    1/12, 1/4 etc.  = compra original
    2/12 em diante  = parcela
  */
  const tipoLinha =
    !temParcelamento || parcelaAtual === 1
      ? "compra"
      : "parcela";

  linhas.push({
    linha: linhas.length + 1,
    data: `${ano}-${m[2]}-${m[1]}`,
    estabelecimento: descricao,
    portador: null,
    valor: Math.abs(valor),

    parcela: temParcelamento
      ? `${parcelaAtual}/${parcelaTotal}`
      : null,

    parcela_atual: parcelaAtual,
    parcela_total: parcelaTotal,
    tipo_linha: tipoLinha,

    dados_originais: {
      origem: "PDF_N8N",
      secao,
      linha_original: linha,
    },
  });
}

const total_fatura = extrairTotal(texto);

const total_importado = Number(
  linhas
    .reduce(
      (soma, linha) =>
        soma + Number(linha.valor || 0),
      0
    )
    .toFixed(2)
);

const diferenca =
  total_fatura == null
    ? null
    : Number(
        (total_importado - total_fatura).toFixed(2)
      );

return [
  {
    json: {
      ok: linhas.length > 0,
      origem: "PDF_N8N",

      banco: texto
        .toLowerCase()
        .includes("santander")
        ? "Santander"
        : null,

      cartao_final: extrairCartaoFinal(texto),
      vencimento: extrairVencimento(texto),

      total_fatura,
      total_importado,
      diferenca,

      validacao: {
        origem: "PDF_N8N",
        ok: diferenca === 0,
        bloqueiaSalvar: diferenca !== 0,

        mensagem:
          diferenca === 0
            ? "PDF validado: total importado bate com o total da fatura."
            : `Divergência no PDF: total importado ${total_importado} x total da fatura ${total_fatura}. Diferença ${diferenca}.`,

        totalPDF: total_fatura,
        totalImportado: total_importado,
        diferenca,
      },

      linhas,
    },
  },
];

 const texto = String(
  $json.text ||
  $json.body?.texto_pdf ||
  $json.texto_pdf ||
  ""
);

/* ============================================================
   FUNÇÕES BÁSICAS
============================================================ */

function parseNumeroBR(valor) {
  return (
    Number(
      String(valor || "")
        .replace("R$", "")
        .replace(/\s/g, "")
        .replace(/\./g, "")
        .replace(",", ".")
        .replace(/[^\d.-]/g, "")
    ) || 0
  );
}

function limpar(txt) {
  return String(txt || "")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizarTexto(txt) {
  return limpar(txt)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

function dataISO(dia, mes, ano) {
  let a = String(
    ano || new Date().getFullYear()
  );

  if (a.length === 2) {
    a = `20${a}`;
  }

  return `${a}-${String(mes).padStart(
    2,
    "0"
  )}-${String(dia).padStart(2, "0")}`;
}

/* ============================================================
   EXTRAÇÃO DOS DADOS GERAIS DA FATURA
============================================================ */

function extrairTotal(textoCompleto) {
  const m =
    textoCompleto.match(
      /Saldo\s+Desta\s+Fatura\s+R?\$?\s*([\d.]+,\d{2})/i
    ) ||
    textoCompleto.match(
      /Valor\s+total\s+devido\s+R?\$?\s*([\d.]+,\d{2})/i
    ) ||
    textoCompleto.match(
      /Despesas\s+até\s+a\s+emissão\s+desta\s+fatura\s+R?\$?\s*([\d.]+,\d{2})/i
    ) ||
    textoCompleto.match(
      /Pagamento\s+total\s+R?\$?\s*([\d.]+,\d{2})/i
    ) ||
    textoCompleto.match(
      /Total\s+da\s+fatura\s+R?\$?\s*([\d.]+,\d{2})/i
    );

  return m
    ? parseNumeroBR(m[1])
    : null;
}

function extrairVencimentoPDF(textoCompleto) {
  const m = String(
    textoCompleto || ""
  ).match(
    /Vencimento\s+(\d{2})\/(\d{2})\/(\d{4})/i
  );

  if (!m) {
    return null;
  }

  return {
    data: `${m[3]}-${m[2]}-${m[1]}`,
    dia: Number(m[1]),
  };
}

function extrairFechamentoPDF(textoCompleto) {
  /*
    Usa o próximo fechamento, pois é o dia
    configurado atualmente para o cartão.
  */
  const m = String(
    textoCompleto || ""
  ).match(
    /Pr[oó]ximo\s+fechamento\s+(\d{2})\/(\d{2})\/(\d{4})/i
  );

  if (!m) {
    return null;
  }

  return {
    data: `${m[3]}-${m[2]}-${m[1]}`,
    dia: Number(m[1]),
  };
}

function extrairFaturaFechadaEm(
  textoCompleto
) {
  const m = String(
    textoCompleto || ""
  ).match(
    /Fatura\s+fechada\s+em\s+(\d{2})\/(\d{2})\/(\d{4})/i
  );

  if (!m) {
    return null;
  }

  return {
    data: `${m[3]}-${m[2]}-${m[1]}`,
    dia: Number(m[1]),
  };
}

function extrairFinaisCartoes(
  textoCompleto
) {
  const txt = String(
    textoCompleto || ""
  );

  const encontrados = [
    ...txt.matchAll(
      /\b\d{4}\*{4,}(\d{4})\b/g
    ),
  ];

  return [
    ...new Set(
      encontrados
        .map((item) => item[1])
        .filter(Boolean)
    ),
  ];
}

function extrairNomeCartaoPDF(
  textoCompleto
) {
  const txt = String(
    textoCompleto || ""
  );

  const m = txt.match(
    /Resumo\s+da\s+sua\s+fatura\s+(Cart[aã]o\s+.+?)\s+R\$/i
  );

  if (!m) {
    return null;
  }

  return limpar(m[1])
    .replace(
      /\bIn\s+fi\s+nite\b/gi,
      "Infinite"
    )
    .replace(
      /\bInfi\s+nite\b/gi,
      "Infinite"
    )
    .replace(/\s+/g, " ")
    .trim();
}

function extrairBandeiraPDF(
  textoCompleto
) {
  const txt = normalizarTexto(
    textoCompleto
  );

  if (txt.includes("visa")) {
    return "VISA";
  }

  if (
    txt.includes("mastercard") ||
    txt.includes("master card")
  ) {
    return "MASTERCARD";
  }

  if (txt.includes("elo")) {
    return "ELO";
  }

  if (
    txt.includes("american express") ||
    txt.includes("amex")
  ) {
    return "AMEX";
  }

  return null;
}

function extrairTitularPDF(
  textoCompleto
) {
  const m = String(
    textoCompleto || ""
  ).match(
    /Titular\s+(.+?)\s+Endere[cç]o/i
  );

  return m
    ? limpar(m[1])
    : null;
}

/* ============================================================
   REGRAS DE PAGAMENTO E LINHAS ADMINISTRATIVAS
============================================================ */

function ehPagamentoFatura(
  descricao,
  valor
) {
  if (Number(valor || 0) >= 0) {
    return false;
  }

  const txt =
    normalizarTexto(descricao);

  return (
    txt.includes("pagamento") ||
    txt.includes(
      "pagamentos validos"
    ) ||
    txt.includes(
      "pagamento recebido"
    ) ||
    txt.includes(
      "pagamento de fatura"
    )
  );
}

function ehLinhaAdministrativa(
  descricao
) {
  const txt =
    normalizarTexto(descricao);

  return (
    txt.includes("limite") ||
    txt.includes("boleto") ||
    txt.includes("nosso numero") ||
    txt.includes(
      "valor do documento"
    ) ||
    txt.includes("encargos") ||
    txt.includes(
      "resumo da fatura"
    ) ||
    txt.includes("total da fatura")
  );
}

/* ============================================================
   IDENTIFICAÇÃO DO BANCO
============================================================ */

const banco = /santander/i.test(texto)
  ? "Santander"
  : /XP|Banco XP/i.test(texto)
    ? "XP"
    : /bradesco/i.test(texto)
      ? "Bradesco"
      : /itau|itaú/i.test(texto)
        ? "Itaú"
        : /nubank/i.test(texto)
          ? "Nubank"
          : null;

/* ============================================================
   ANO PADRÃO
============================================================ */

const anoPadrao =
  (
    texto.match(/\b(20\d{2})\b/) || [
      null,
      String(
        new Date().getFullYear()
      ),
    ]
  )[1];

/* ============================================================
   PREPARAÇÃO DO TEXTO PARA EXTRAÇÃO DAS LINHAS
============================================================ */

let textoParse = texto
  .replace(/\r/g, "\n")
  .replace(/\u00a0/g, " ")
  .replace(
    /Data\s+Descrição\s+R\$\s+US\$/gi,
    "\nData Descrição R$ US$\n"
  )
  .replace(
    /Compra\s+Data\s+Descrição\s+Parcela\s+R\$\s+US\$/gi,
    "\nCompra Data Descrição Parcela R$ US$\n"
  )
  .replace(
    /Subtotal/gi,
    "\nSubtotal"
  )
  .replace(
    /VALOR\s+TOTAL/gi,
    "\nVALOR TOTAL"
  )
  .replace(
    /(\d{2}\/\d{2}\/\d{2,4})\s+/g,
    "\n$1 "
  )
  .replace(
    /(?:^|\s)(\d+)\s+(\d{2}\/\d{2})(?!\/)/g,
    "\n$1 $2"
  )
  .replace(/\n\s+/g, "\n");

/* ============================================================
   EXTRAÇÃO DAS TRANSAÇÕES
============================================================ */

const linhas = [];
let secao = "";

for (
  const raw of textoParse.split(/\n+/)
) {
  const linha = limpar(raw);

  if (!linha) {
    continue;
  }

  if (
    /Pagamento e Demais Créditos/i.test(
      linha
    )
  ) {
    secao = "creditos";
    continue;
  }

  if (/Parcelamentos/i.test(linha)) {
    secao = "parcelamentos";
    continue;
  }

  if (/Despesas/i.test(linha)) {
    secao = "despesas";
    continue;
  }

  if (
    /Resumo da Fatura/i.test(linha)
  ) {
    secao = "resumo";
    continue;
  }

  if (
    /Compra Data Descrição/i.test(
      linha
    )
  ) {
    continue;
  }

  if (/^Subtotal/i.test(linha)) {
    continue;
  }

  if (/^VALOR TOTAL/i.test(linha)) {
    continue;
  }

  if (secao === "resumo") {
    continue;
  }

  const m = linha.match(
    /^(?:\d+\s+)?(\d{2})\/(\d{2})(?:\/(\d{2,4}))?\s+(.+?)\s+(?:(?:-|–)?\s*Parcela\s+)?(?:(\d{1,2})\/(\d{1,2})\s+)?(-?[\d.]+,\d{2})(?:\s+[\d.]+,\d{2})?$/i
  );

  if (!m) {
    continue;
  }

  const valor =
    parseNumeroBR(m[7]);

  let descricao = limpar(m[4])
    .replace(/\s*-\s*$/g, "")
    .replace(
      /\s*Parcela\s*$/i,
      ""
    );

  if (
    ehLinhaAdministrativa(
      descricao
    )
  ) {
    continue;
  }

  /*
    Pagamento da fatura anterior:
    não entra na lista da fatura atual.
  */
  if (
    ehPagamentoFatura(
      descricao,
      valor
    )
  ) {
    continue;
  }

  const temParcela =
    Boolean(m[5]) &&
    Boolean(m[6]);

  const tipoLinha =
    valor < 0
      ? "credito"
      : temParcela
        ? "parcela"
        : "compra";

  linhas.push({
    linha: linhas.length + 1,

    data: dataISO(
      m[1],
      m[2],
      m[3] || anoPadrao
    ),

    estabelecimento:
      descricao,

    portador: null,

    /*
      Compra positiva.
      Crédito/estorno negativo.
    */
    valor,

    parcela: temParcela
      ? `${Number(m[5])}/${Number(
          m[6]
        )}`
      : null,

    parcela_atual: m[5]
      ? Number(m[5])
      : null,

    parcela_total: m[6]
      ? Number(m[6])
      : null,

    tipo_linha: tipoLinha,

    dados_originais: {
      origem: "PDF_N8N",
      secao,
      linha_original: linha,
    },
  });
}

/* ============================================================
   TOTAIS E VALIDAÇÃO
============================================================ */

const total_fatura =
  extrairTotal(texto);

const compras = Number(
  linhas
    .filter(
      (l) =>
        Number(l.valor || 0) > 0
    )
    .reduce(
      (soma, l) =>
        soma +
        Number(l.valor || 0),
      0
    )
    .toFixed(2)
);

const creditos_estornos =
  Number(
    linhas
      .filter(
        (l) =>
          Number(l.valor || 0) < 0
      )
      .reduce(
        (soma, l) =>
          soma +
          Math.abs(
            Number(l.valor || 0)
          ),
        0
      )
      .toFixed(2)
  );

const total_importado = Number(
  linhas
    .reduce(
      (soma, l) =>
        soma +
        Number(l.valor || 0),
      0
    )
    .toFixed(2)
);

const diferenca =
  total_fatura == null
    ? null
    : Number(
        (
          total_importado -
          Number(total_fatura)
        ).toFixed(2)
      );

const validacaoOk =
  total_fatura != null &&
  Math.abs(diferenca || 0) <=
    0.05;

/* ============================================================
   DADOS DO CARTÃO ENCONTRADOS NO PDF
============================================================ */

const finais_cartoes =
  extrairFinaisCartoes(texto);

const vencimento_pdf =
  extrairVencimentoPDF(texto);

const fechamento_pdf =
  extrairFechamentoPDF(texto);

const fatura_fechada_em =
  extrairFaturaFechadaEm(
    texto
  );

const nome_cartao_pdf =
  extrairNomeCartaoPDF(texto);

const bandeira_pdf =
  extrairBandeiraPDF(texto);

const titular_pdf =
  extrairTitularPDF(texto);

/* ============================================================
   RETORNO FINAL
============================================================ */

return [
  {
    json: {
      ok: linhas.length > 0,

      origem: "PDF_N8N",

      banco,

      /*
        Mantém um final principal
        para compatibilidade.
      */
      cartao_final:
        finais_cartoes[0] || null,

      /*
        Todos os finais encontrados.
        Exemplo: 9908 e 1223.
      */
      cartoes_finais:
        finais_cartoes,

      vencimento:
        vencimento_pdf?.data ||
        null,

      vencimento_dia:
        vencimento_pdf?.dia ||
        null,

      fechamento:
        fechamento_pdf?.data ||
        null,

      fechamento_dia:
        fechamento_pdf?.dia ||
        null,

      fatura_fechada_em:
        fatura_fechada_em?.data ||
        null,

      nome_cartao:
        nome_cartao_pdf,

      bandeira:
        bandeira_pdf,

      titular:
        titular_pdf,

      /*
        Objeto específico para a UI
        conferir o cartão selecionado.
      */
      dados_cartao_pdf: {
        banco,

        finais:
          finais_cartoes,

        vencimento:
          vencimento_pdf?.data ||
          null,

        vencimento_dia:
          vencimento_pdf?.dia ||
          null,

        fechamento:
          fechamento_pdf?.data ||
          null,

        fechamento_dia:
          fechamento_pdf?.dia ||
          null,

        nome:
          nome_cartao_pdf,

        bandeira:
          bandeira_pdf,

        titular:
          titular_pdf,
      },

      total_fatura,
      total_importado,
      compras,
      creditos_estornos,
      diferenca,

      validacao: {
        origem: "PDF_N8N",

        ok: validacaoOk,

        bloqueiaSalvar:
          total_fatura != null &&
          !validacaoOk,

        mensagem:
          total_fatura == null
            ? `Não localizei o total da fatura. Total líquido importado: ${total_importado}.`
            : validacaoOk
              ? `PDF validado: compras ${compras}, créditos/estornos -${creditos_estornos}, total líquido ${total_importado}.`
              : `Divergência no PDF: compras ${compras}, créditos/estornos -${creditos_estornos}, total líquido importado ${total_importado} x total da fatura ${total_fatura}. Diferença ${diferenca}.`,

        totalPDF:
          total_fatura,

        totalImportado:
          total_importado,

        compras,

        creditosEstornos:
          creditos_estornos,

        diferenca,
      },

      linhas,
    },
  },
];

 /*
|--------------------------------------------------------------------------
| ENTRADAS
|--------------------------------------------------------------------------
*/

// PostgreSQL imediatamente anterior ao Code.
// Contém os dados da conta selecionada na tela.
const contaBanco = $input.first().json;

// Node Edit Fields/EditHistorico.
// Contém texto_pdf, empresa_id, conta_id, período etc.
const entrada = $('EditHistorico').first().json;

const texto = String(
  entrada.texto_pdf ||
  entrada.text ||
  ""
);

if (!texto.trim()) {
  throw new Error("O PDF não retornou texto para processamento.");
}

/*
|--------------------------------------------------------------------------
| FUNÇÕES AUXILIARES
|--------------------------------------------------------------------------
*/

function normalizarTexto(valor) {
  return String(valor || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toUpperCase()
    .replace(/\s+/g, " ")
    .trim();
}

function somenteNumeros(valor) {
  return String(valor || "")
    .replace(/\D/g, "")
    .replace(/^0+/, "");
}

function normalizarBanco(valor) {
  const textoBanco = normalizarTexto(valor);
  const codigoBanco = somenteNumeros(valor);

  if (
    textoBanco.includes("SICOOB") ||
    textoBanco.includes("BANCO COOPERATIVO DO BRASIL") ||
    codigoBanco === "756"
  ) {
    return "SICOOB";
  }

  if (
    textoBanco.includes("SANTANDER") ||
    codigoBanco === "33"
  ) {
    return "SANTANDER";
  }

  return textoBanco;
}

function converterValorBR(valor) {
  const textoValor = String(valor || "")
    .replace(/\s/g, "")
    .trim();

  const numero = Number(
    textoValor
      .replace(/\./g, "")
      .replace(",", ".")
  );

  return Number.isFinite(numero)
    ? numero
    : 0;
}

/*
|--------------------------------------------------------------------------
| DADOS DA CONTA SELECIONADA
|--------------------------------------------------------------------------
*/

const contaSelecionada = {
  id:
    contaBanco.id ||
    contaBanco.conta_id ||
    entrada.conta_id ||
    null,

  empresa_id:
    contaBanco.empresa_id ||
    entrada.empresa_id ||
    entrada.body?.empresa_id ||
    null,

  nome:
    contaBanco.nome ||
    contaBanco.conta_nome ||
    "",

  banco:
    contaBanco.banco ||
    contaBanco.banco_nome ||
    "",

  agencia:
    contaBanco.agencia ||
    contaBanco.cooperativa ||
    "",

  conta:
    contaBanco.conta ||
    contaBanco.numero_conta ||
    ""
};

if (!contaSelecionada.id) {
  throw new Error(
    "A conta financeira selecionada não foi encontrada."
  );
}

if (!contaSelecionada.banco) {
  throw new Error(
    "A conta selecionada não possui banco cadastrado."
  );
}

/*
|--------------------------------------------------------------------------
| IDENTIFICA O BANCO DO ARQUIVO
|--------------------------------------------------------------------------
*/

const textoNormalizado =
  normalizarTexto(texto);

const ehSicoob =
  textoNormalizado.includes("SICOOB") ||
  textoNormalizado.includes("SISBR") ||
  textoNormalizado.includes(
    "SISTEMA DE COOPERATIVAS DE CREDITO DO BRASIL"
  );

const ehSantander =
  textoNormalizado.includes("SANTANDER") ||
  textoNormalizado.includes(
    "APLICATIVO SANTANDER EMPRESAS"
  ) ||
  textoNormalizado.includes(
    "SANTANDER EMPRESARIAL"
  );

let bancoArquivo = "";

if (ehSicoob) {
  bancoArquivo = "SICOOB";
} else if (ehSantander) {
  bancoArquivo = "SANTANDER";
}

/*
|--------------------------------------------------------------------------
| BANCO DO ARQUIVO NÃO IDENTIFICADO
|--------------------------------------------------------------------------
*/

if (!bancoArquivo) {
  return [
    {
      json: {
        ok: false,
        conta_validada: false,
        tipo_erro:
          "BANCO_DO_ARQUIVO_NAO_IDENTIFICADO",

        mensagem:
          "Não foi possível identificar o banco do arquivo.",

        detalhes: [
          `Banco selecionado: ${
            contaSelecionada.banco ||
            "não informado"
          }`,
          "Banco do arquivo: não identificado"
        ],

        conta_selecionada: {
          id: contaSelecionada.id,
          nome: contaSelecionada.nome,
          banco: contaSelecionada.banco,
          agencia: contaSelecionada.agencia,
          conta: contaSelecionada.conta
        },

        conta_arquivo: {
          banco: "NÃO IDENTIFICADO"
        },

        movimentos: [],
        quantidade: 0
      }
    }
  ];
}

/*
|--------------------------------------------------------------------------
| VALIDA BANCO SELECIONADO X BANCO DO ARQUIVO
|--------------------------------------------------------------------------
*/

const bancoSelecionado =
  normalizarBanco(
    contaSelecionada.banco
  );

if (
  bancoSelecionado &&
  bancoSelecionado !== bancoArquivo
) {
  return [
    {
      json: {
        ok: false,
        conta_validada: false,
        tipo_erro:
          "BANCO_DO_ARQUIVO_INCORRETO",

        mensagem:
          "O arquivo enviado não pertence ao banco da conta selecionada. Selecione a conta correta e importe novamente.",

        detalhes: [
          `Banco selecionado: ${
            contaSelecionada.banco ||
            "não informado"
          }`,
          `Banco identificado no arquivo: ${bancoArquivo}`
        ],

        conta_selecionada: {
          id: contaSelecionada.id,
          nome: contaSelecionada.nome,
          banco: contaSelecionada.banco,
          agencia: contaSelecionada.agencia,
          conta: contaSelecionada.conta
        },

        conta_arquivo: {
          banco: bancoArquivo
        },

        movimentos: [],
        quantidade: 0
      }
    }
  ];
}

/*
|--------------------------------------------------------------------------
| SICOOB
|--------------------------------------------------------------------------
*/

if (bancoArquivo === "SICOOB") {
  const movimentos = [];

  const partes = texto
    .replace(/\r/g, " ")
    .split(/(?=\d{2}\/\d{2})/)
    .map((item) =>
      String(item || "").trim()
    )
    .filter(Boolean);

  for (const linha of partes) {
    const match = linha.match(
      /^(\d{2}\/\d{2})\s+(.+?)\s+([\d.,]+)([DC])(?:\s|$)/
    );

    if (!match) {
      continue;
    }

    const historico = String(
      match[2] || ""
    )
      .replace(/\s+/g, " ")
      .trim();

    const valor =
      converterValorBR(match[3]);

    const tipo = String(
      match[4] || ""
    )
      .trim()
      .toUpperCase();

    if (
      !historico ||
      valor === 0 ||
      !["C", "D"].includes(tipo)
    ) {
      continue;
    }

    movimentos.push({
      data: match[1],
      historico,
      valor,
      tipo
    });
  }

  return [
    {
      json: {
        ok: true,
        conta_validada: true,

        empresa_id:
          contaSelecionada.empresa_id,

        conta_id:
          contaSelecionada.id,

        data_inicio:
          entrada.data_inicio ||
          entrada.body?.data_inicio ||
          contaBanco.data_inicio ||
          null,

        data_fim:
          entrada.data_fim ||
          entrada.body?.data_fim ||
          contaBanco.data_fim ||
          null,

        banco: "SICOOB",

        conta_selecionada: {
          id: contaSelecionada.id,
          nome: contaSelecionada.nome,
          banco: contaSelecionada.banco,
          agencia: contaSelecionada.agencia,
          conta: contaSelecionada.conta
        },

        movimentos,

        quantidade:
          movimentos.length,

        teste_primeira_linha:
          partes[0] || null,

        teste_quantidade_partes:
          partes.length
      }
    }
  ];
}

/*
|--------------------------------------------------------------------------
| SANTANDER
|--------------------------------------------------------------------------
|
| Formato:
|
| Data completa
| Histórico
| Documento opcional
| Valor do movimento
| Saldo após o movimento
|--------------------------------------------------------------------------
*/

if (bancoArquivo === "SANTANDER") {
  const movimentos = [];
  const partesIgnoradas = [];

  const partes = texto
    .replace(/\r/g, " ")
    .replace(/\n/g, " ")
    .replace(/\s+/g, " ")
    .split(
      /(?=\d{2}\/\d{2}\/\d{4}\s+)/
    )
    .map((item) =>
      String(item || "").trim()
    )
    .filter(Boolean);

  const regexSantander =
    /^(\d{2}\/\d{2}\/\d{4})\s+(.+?)\s+(-?\d{1,3}(?:\.\d{3})*,-?\d{2}|-?\d+,\d{2})\s+(-?\d{1,3}(?:\.\d{3})*,-?\d{2}|-?\d+,\d{2})(?:\s|$)/;

  for (const parte of partes) {
    const match =
      parte.match(regexSantander);

    if (!match) {
      partesIgnoradas.push({
        linha: parte,
        motivo:
          "FORMATO_NAO_RECONHECIDO"
      });

      continue;
    }

    const data = match[1];

    let historico = String(
      match[2] || ""
    )
      .replace(/\s+/g, " ")
      .trim();

    const valorAssinado =
      converterValorBR(match[3]);

    const saldo =
      converterValorBR(match[4]);

    const historicoNormalizado =
      normalizarTexto(historico);

    /*
     * Ignora cabeçalhos e resumos.
     */
    if (
      historicoNormalizado.includes(
        "DATA HISTORICO DOCUMENTO"
      ) ||
      historicoNormalizado.includes(
        "SALDO DE CONTAMAX"
      ) ||
      historicoNormalizado.includes(
        "SALDO DISPONIVEL"
      ) ||
      historicoNormalizado.includes(
        "POSICAO EM:"
      ) ||
      historicoNormalizado.includes(
        "CENTRAL DE ATENDIMENTO"
      )
    ) {
      partesIgnoradas.push({
        linha: parte,
        motivo:
          "CABECALHO_OU_RESUMO"
      });

      continue;
    }

    /*
     * Quando houver:
     *
     * Pix Recebido 69123730625 14315321
     *
     * mantém:
     *
     * Pix Recebido 69123730625
     *
     * O segundo número é o documento interno.
     */
    const cpfCnpjComDocumento =
      historico.match(
        /^(.*?\s+\d{11,14})\s+\d{6,10}$/
      );

    if (cpfCnpjComDocumento) {
      historico =
        cpfCnpjComDocumento[1]
          .replace(/\s+/g, " ")
          .trim();
    }

    if (
      !data ||
      !historico ||
      valorAssinado === 0
    ) {
      partesIgnoradas.push({
        linha: parte,
        motivo:
          "MOVIMENTO_INVALIDO"
      });

      continue;
    }

    movimentos.push({
      data,
      historico,

      valor:
        Math.abs(valorAssinado),

      tipo:
        valorAssinado < 0
          ? "D"
          : "C",

      saldo
    });
  }

  return [
    {
      json: {
        ok: true,
        conta_validada: true,

        empresa_id:
          contaSelecionada.empresa_id,

        conta_id:
          contaSelecionada.id,

        data_inicio:
          entrada.data_inicio ||
          entrada.body?.data_inicio ||
          contaBanco.data_inicio ||
          null,

        data_fim:
          entrada.data_fim ||
          entrada.body?.data_fim ||
          contaBanco.data_fim ||
          null,

        banco: "SANTANDER",

        conta_selecionada: {
          id: contaSelecionada.id,
          nome: contaSelecionada.nome,
          banco: contaSelecionada.banco,
          agencia: contaSelecionada.agencia,
          conta: contaSelecionada.conta
        },

        movimentos,

        quantidade:
          movimentos.length,

        quantidade_ignoradas:
          partesIgnoradas.length,

        linhas_ignoradas:
          partesIgnoradas,

        teste_primeira_linha:
          partes[0] || null,

        teste_quantidade_partes:
          partes.length
      }
    }
  ];
}

/*
|--------------------------------------------------------------------------
| SEGURANÇA FINAL
|--------------------------------------------------------------------------
*/

return [
  {
    json: {
      ok: false,
      conta_validada: false,
      tipo_erro:
        "PROCESSAMENTO_NAO_IMPLEMENTADO",

      mensagem:
        "O banco foi identificado, mas não existe tratamento disponível.",

      banco:
        bancoArquivo,

      movimentos: [],
      quantidade: 0
    }
  }
];

  /***********************************************************************
 * PARSER COMPLETO DE FATURA SANTANDER
 * NODE: Code - n8n
 *
 * ENTRADAS ACEITAS:
 *   $json.texto_pdf
 *   $json.texto
 *   $json.text
 *   $json.body.texto_pdf
 *   $json.body.texto
 *
 * RESULTADO:
 *   Cabeçalho da fatura
 *   Cartões encontrados
 *   Total da fatura
 *   Total importado
 *   Linhas de compras, parcelas, tarifas e créditos
 *   Pagamentos anteriores separados e fora do total importado
 ***********************************************************************/

const entrada = $input.first()?.json || {};

const textoOriginal = String(
  entrada.texto_pdf ||
  entrada.texto ||
  entrada.text ||
  entrada.body?.texto_pdf ||
  entrada.body?.texto ||
  entrada.body?.text ||
  ""
);

if (!textoOriginal.trim()) {
  return [
    {
      json: {
        ok: false,
        origem: "PDF_N8N",
        banco: "SANTANDER",
        erro: "Texto da fatura não informado",
        linhas: []
      }
    }
  ];
}

/***********************************************************************
 * NORMALIZAÇÃO
 ***********************************************************************/

const texto = textoOriginal
  /*
   * Alguns fluxos entregam as quebras como caracteres reais;
   * outros entregam literalmente "\\r\\n".
   */
  .replace(/\\r\\n|\\n|\\r/g, "\n")
  .replace(/\r/g, "\n")
  .replace(/\u00A0/g, " ")
  .replace(/[ \t]+/g, " ")
  .replace(/\n+/g, "\n")
  .trim();

const textoUmaLinha = texto
  .replace(/\n/g, " ")
  .replace(/\s+/g, " ")
  .trim();

const textoBusca = textoUmaLinha
  .normalize("NFD")
  .replace(/[\u0300-\u036f]/g, "")
  .toUpperCase();

/***********************************************************************
 * FUNÇÕES AUXILIARES
 ***********************************************************************/

function somenteTextoBusca(valor) {
  return String(valor || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toUpperCase();
}

function doisDigitos(valor) {
  return String(valor).padStart(2, "0");
}

function anoCompleto(valor) {
  const ano = Number(valor);

  if (String(valor).length === 4) {
    return ano;
  }

  return ano >= 70 ? 1900 + ano : 2000 + ano;
}

function dataISO(dia, mes, ano) {
  if (!dia || !mes || !ano) {
    return null;
  }

  return `${anoCompleto(ano)}-${doisDigitos(mes)}-${doisDigitos(dia)}`;
}

function dataBrParaISO(valor) {
  const match = String(valor || "").match(
    /(\d{1,2})\/(\d{1,2})\/(\d{2,4})/
  );

  if (!match) {
    return null;
  }

  return dataISO(match[1], match[2], match[3]);
}

function dataSemAnoParaISO(valor, dataFechamento) {
  const match = String(valor || "").match(
    /(\d{1,2})\/(\d{1,2})/
  );

  if (!match) {
    return null;
  }

  const dia = Number(match[1]);
  const mes = Number(match[2]);

  let ano = dataFechamento
    ? Number(dataFechamento.substring(0, 4))
    : new Date().getFullYear();

  const mesFechamento = dataFechamento
    ? Number(dataFechamento.substring(5, 7))
    : 12;

  /*
   * Exemplo:
   * fechamento em janeiro/2027
   * compra em dezembro/2026
   */
  if (mes > mesFechamento + 3) {
    ano -= 1;
  }

  return dataISO(dia, mes, ano);
}

function paraNumero(valor) {
  if (
    valor === null ||
    valor === undefined ||
    valor === ""
  ) {
    return 0;
  }

  let textoValor = String(valor)
    .replace(/R\$/gi, "")
    .replace(/\s/g, "")
    .trim();

  const negativo =
    textoValor.startsWith("-") ||
    textoValor.startsWith("(") ||
    textoValor.endsWith("-");

  textoValor = textoValor
    .replace(/[()\-]/g, "")
    .replace(/\./g, "")
    .replace(",", ".");

  const numero = Number(textoValor);

  if (!Number.isFinite(numero)) {
    return 0;
  }

  return negativo
    ? -Math.abs(numero)
    : numero;
}

function arredondar(valor) {
  return Math.round(
    (Number(valor) + Number.EPSILON) * 100
  ) / 100;
}

function extrairDia(data) {
  if (!data) {
    return null;
  }

  return Number(data.substring(8, 10));
}

function unicos(lista) {
  return [...new Set(lista.filter(Boolean))];
}

function limparEstabelecimento(valor) {
  return String(valor || "")
    .replace(/\s+/g, " ")
    .replace(/^[|:;,.\-]+/, "")
    .replace(/[|:;,.\-]+$/, "")
    .trim();
}

function trechoEntre(textoBase, inicio, finais) {
  const inicioBusca = somenteTextoBusca(inicio);
  const baseBusca = somenteTextoBusca(textoBase);

  const posicaoInicio = baseBusca.indexOf(inicioBusca);

  if (posicaoInicio < 0) {
    return "";
  }

  const inicioConteudo =
    posicaoInicio + inicio.length;

  let posicaoFinal = textoBase.length;

  for (const final of finais) {
    const finalBusca = somenteTextoBusca(final);

    const encontrada = baseBusca.indexOf(
      finalBusca,
      inicioConteudo
    );

    if (
      encontrada >= 0 &&
      encontrada < posicaoFinal
    ) {
      posicaoFinal = encontrada;
    }
  }

  return textoBase
    .substring(inicioConteudo, posicaoFinal)
    .trim();
}

/***********************************************************************
 * BANCO
 ***********************************************************************/

const banco = textoBusca.includes("SANTANDER")
  ? "SANTANDER"
  : null;

/***********************************************************************
 * CARTÕES
 ***********************************************************************/

const cartoesCompletos = [];

const regexCartao =
  /\b(\d{4})\s+X{2,4}\s+X{2,4}\s+(\d{4})\b/gi;

let matchCartao;

while (
  (matchCartao = regexCartao.exec(textoUmaLinha)) !== null
) {
  cartoesCompletos.push({
    inicio: matchCartao[1],
    final: matchCartao[2],
    indice: matchCartao.index
  });
}

const cartoesFinais = unicos(
  cartoesCompletos.map((cartao) => cartao.final)
);

const cartaoFinal =
  cartoesFinais[0] || null;

/***********************************************************************
 * TITULAR
 ***********************************************************************/

let titular = null;

if (cartaoFinal) {
  const regexTitular = new RegExp(
    `([A-ZÀ-Ý][A-ZÀ-Ý .'-]{4,80}?)\\s*-\\s*\\d{4}\\s+X{2,4}\\s+X{2,4}\\s+${cartaoFinal}`,
    "i"
  );

  const matchTitular =
    textoUmaLinha.match(regexTitular);

  if (matchTitular) {
    titular = limparEstabelecimento(
      matchTitular[1]
    ).toUpperCase();
  }
}

if (
  titular &&
  (
    titular.includes("BANCO SANTANDER") ||
    titular.includes("AVENIDA PRESIDENTE") ||
    titular.length > 70
  )
) {
  titular = null;
}

/***********************************************************************
 * VENCIMENTO
 ***********************************************************************/

let vencimento = null;

const regexVencimentoPrincipal =
  /TOTAL\s+A\s+PAGAR[\s\S]{0,250}?VENCIMENTO\s+(\d{1,2}\/\d{1,2}\/\d{2,4})/i;

const matchVencimentoPrincipal =
  textoUmaLinha.match(regexVencimentoPrincipal);

if (matchVencimentoPrincipal) {
  vencimento = dataBrParaISO(
    matchVencimentoPrincipal[1]
  );
}

if (!vencimento) {
  const matchVencimento = textoUmaLinha.match(
    /VENCIMENTO\s+(\d{1,2}\/\d{1,2}\/\d{2,4})/i
  );

  if (matchVencimento) {
    vencimento = dataBrParaISO(
      matchVencimento[1]
    );
  }
}

const vencimentoDia =
  extrairDia(vencimento);

/***********************************************************************
 * FECHAMENTO DA FATURA ATUAL
 ***********************************************************************/

let faturaFechadaEm = null;

const matchPeriodoAtual = textoUmaLinha.match(
  /ESTA\s+FATURA\s+(\d{1,2}\/\d{1,2}\/\d{2,4})\s+A\s+(\d{1,2}\/\d{1,2}\/\d{2,4})/i
);

if (matchPeriodoAtual) {
  faturaFechadaEm = dataBrParaISO(
    matchPeriodoAtual[2]
  );
}

if (!faturaFechadaEm) {
  const matchRealizadosAte = textoUmaLinha.match(
    /COMPRAS\s+E\s+PAGAMENTOS\s+REALIZADOS\s+AT[ÉE]\s+(\d{1,2})\/(\d{1,2})/i
  );

  if (
    matchRealizadosAte &&
