  ) {
    faturaFechadaEm = dataISO(
      matchRealizadosAte[1],
      matchRealizadosAte[2],
      vencimento.substring(0, 4)
    );
  }
}

/***********************************************************************
 * PRÓXIMO FECHAMENTO
 ***********************************************************************/

let fechamento = null;

const matchFaturaAberta = textoUmaLinha.match(
  /FATURA\s+ABERTA\s+(\d{1,2}\/\d{1,2}\/\d{2,4})\s+A\s+(\d{1,2}\/\d{1,2}\/\d{2,4})/i
);

if (matchFaturaAberta) {
  fechamento = dataBrParaISO(
