/***********************************************************************
 * NOME DO CARTÃO
 ***********************************************************************/

let nomeCartao = null;

const matchNomeCartao = textoUmaLinha.match(
  /FATURA\s+DO\s+SEU\s+CART[AÃ]O\s+(.+?)\s+CONTENDO\s+COMPRAS/i
);

if (matchNomeCartao) {
  nomeCartao =
    "Cartão " +
    limparEstabelecimento(
      matchNomeCartao[1]
    ).replace(/\s*\/\s*/g, " / ");
}

/***********************************************************************
 * BANDEIRA
 ***********************************************************************/

let bandeira = null;

if (textoBusca.includes("MASTERCARD")) {
  bandeira = "MASTERCARD";
} else if (textoBusca.includes("VISA")) {
  bandeira = "VISA";
} else if (
  textoBusca.includes("AMERICAN EXPRESS") ||
  textoBusca.includes("AMEX")
) {
  bandeira = "AMERICAN EXPRESS";
} else if (textoBusca.includes("ELO")) {
  bandeira = "ELO";
}

if (
  !bandeira &&
  cartoesCompletos.length > 0
) {
  const primeiroDigito =
    cartoesCompletos[0].inicio.substring(0, 1);

  if (primeiroDigito === "4") {
    bandeira = "VISA";
  } else if (primeiroDigito === "5") {
    bandeira = "MASTERCARD";
  } else if (primeiroDigito === "3") {
    bandeira = "AMERICAN EXPRESS";
  }
}

/***********************************************************************
 * TOTAL DA FATURA
 ***********************************************************************/

let totalFatura = 0;

const matchSaldoFatura = textoUmaLinha.match(
  /SALDO\s+DESTA\s+FATURA\s+([\d.]+,\d{2})/i
);

if (matchSaldoFatura) {
  totalFatura = paraNumero(
    matchSaldoFatura[1]
  );
}

if (!totalFatura) {
  const matchTotalFatura = textoUmaLinha.match(
    /TOTAL\s+DESTA\s+FATURA\s+R?\$?\s*([\d.]+,\d{2})/i
  );

  if (matchTotalFatura) {
    totalFatura = paraNumero(
      matchTotalFatura[1]
    );
  }
}

if (!totalFatura) {
  const matchPagamentoTotal = textoUmaLinha.match(
    /PAGAMENTO\s+TOTAL\s+R?\$?\s*([\d.]+,\d{2})/i
  );

  if (matchPagamentoTotal) {
    totalFatura = paraNumero(
      matchPagamentoTotal[1]
    );
  }
}

/***********************************************************************
 * TOTAIS DO RESUMO
 ***********************************************************************/

let totalDebitosResumo = 0;
let totalCreditosResumo = 0;
let totalPagamentosResumo = 0;

const matchDebitosResumo = textoUmaLinha.match(
  /TOTAL\s+DESPESAS\/D[ÉE]BITOS\s+NO\s+BRASIL\s+([\d.]+,\d{2})/i
);

if (matchDebitosResumo) {
  totalDebitosResumo = paraNumero(
    matchDebitosResumo[1]
  );
}

const matchCreditosResumo = textoUmaLinha.match(
  /TOTAL\s+DE\s+CR[ÉE]DITOS\s+([\d.]+,\d{2})/i
);

if (matchCreditosResumo) {
  totalCreditosResumo = paraNumero(
    matchCreditosResumo[1]
  );
}

const matchPagamentosResumo = textoUmaLinha.match(
  /TOTAL\s+DE\s+PAGAMENTOS\s+([\d.]+,\d{2})/i
);

if (matchPagamentosResumo) {
  totalPagamentosResumo = paraNumero(
    matchPagamentosResumo[1]
  );
}

/***********************************************************************
 * LOCALIZA OS BLOCOS DOS CARTÕES
 ***********************************************************************/

const marcadoresCartao = [];

const regexCabecalhoCartao =
  /(?:DETALHAMENTO\s+DA\s+FATURA\s+)?@?\s*([A-ZÀ-Ý][A-ZÀ-Ý .'-]{2,50}?)\s*-\s*(\d{4})\s+X{2,4}\s+X{2,4}\s+(\d{4})/gi;

let matchCabecalho;

while (
  (matchCabecalho =
    regexCabecalhoCartao.exec(textoUmaLinha)) !== null
) {
  const final = matchCabecalho[3];

  if (!cartoesFinais.includes(final)) {
    continue;
  }

  const trechoApos = textoUmaLinha.substring(
    matchCabecalho.index,
    matchCabecalho.index + 500
  );

  const trechoAposBusca =
    somenteTextoBusca(trechoApos);

  if (
    !trechoAposBusca.includes(
      "PAGAMENTO E DEMAIS CREDITOS"
    ) &&
    !trechoAposBusca.includes(
      "PARCELAMENTOS"
    ) &&
    !trechoAposBusca.includes(
      "DESPESAS"
    )
  ) {
    continue;
  }

  marcadoresCartao.push({
    indice: matchCabecalho.index,
    final,
    nome: limparEstabelecimento(
      matchCabecalho[1]
    )
  });
}

/*
 * Remove cabeçalhos duplicados muito próximos.
 */
const marcadoresUnicos = [];

for (const marcador of marcadoresCartao) {
  const ultimo =
    marcadoresUnicos[
      marcadoresUnicos.length - 1
    ];

  const repetidoProximo =
    ultimo &&
    ultimo.final === marcador.final &&
    Math.abs(
      ultimo.indice - marcador.indice
    ) < 300;

  if (!repetidoProximo) {
    marcadoresUnicos.push(marcador);
  }
}

/***********************************************************************
 * EXTRAÇÃO DAS LINHAS
 ***********************************************************************/

const linhas = [];
const pagamentosAnteriores = [];

function interpretarParcelaLinha(parcela) {
  const match = String(parcela || "").match(
    /^(\d{1,2})\s*\/\s*(\d{1,2})$/
  );

  if (!match) {
    return {
      parcela_texto: null,
      parcela_atual: null,
      parcela_total: null
    };
  }

  return {
    parcela_texto: `${Number(match[1])}/${Number(match[2])}`,
    parcela_atual: Number(match[1]),
    parcela_total: Number(match[2])
  };
}

function adicionarLinha({
  cartao,
  data,
  estabelecimento,
  parcela,
  valor,
  tipo,
  secao
}) {
  const estabelecimentoLimpo =
    limparEstabelecimento(estabelecimento);

  if (
    !estabelecimentoLimpo ||
    !data ||
    !Number.isFinite(valor) ||
    valor === 0
  ) {
    return;
  }

  const estabelecimentoBusca =
    somenteTextoBusca(estabelecimentoLimpo);

  const parcelaLida =
    interpretarParcelaLinha(parcela);

  /*
   * Pagamento da fatura anterior:
   * fica separado e não entra no total da fatura atual.
   */
  if (
    estabelecimentoBusca.includes("PAGAMENTO DE FATURA") ||
    estabelecimentoBusca.includes("PAGTO DE FATURA") ||
    estabelecimentoBusca.includes("PAGAMENTO RECEBIDO")
  ) {
    pagamentosAnteriores.push({
      cartao_final: cartao,
      data,
      estabelecimento: estabelecimentoLimpo,
      parcela: parcelaLida.parcela_texto,
      parcela_atual: parcelaLida.parcela_atual,
      parcela_total: parcelaLida.parcela_total,
      valor: arredondar(valor),
      tipo_linha: "pagamento",
      secao
    });

    return;
  }

  /*
   * Contrato de saída esperado pela UI:
   * compra | parcela | credito | pagamento
   *
   * Tarifa e anuidade entram como compra, pois precisam
   * receber conta contábil na tela.
   */
  let tipoLinha = String(tipo || "")
    .trim()
    .toLowerCase();

  if (valor < 0) {
    tipoLinha = "credito";
  } else if (parcelaLida.parcela_atual && parcelaLida.parcela_total) {
    tipoLinha = "parcela";
  } else {
    tipoLinha = "compra";
  }

  linhas.push({
    cartao_final: cartao,
    data,
    estabelecimento: estabelecimentoLimpo,
    portador: null,
    parcela: parcelaLida.parcela_texto,
    parcela_atual: parcelaLida.parcela_atual,
    parcela_total: parcelaLida.parcela_total,
    valor: arredondar(valor),
    tipo_linha: tipoLinha,
    secao
  });
}

function extrairLinhasSecao({
  conteudo,
  cartao,
  secao,
  tipoPadrao
}) {
  if (!conteudo) {
    return;
  }

  /*
   * A quebra de página do Santander pode aparecer no meio das despesas:
   *
   * 11/07 APPLE COM/BILL 29,90
   * 3/4 Detalhamento da Fatura Despesas ...
   * 13/07 PAULISTA SUPERMERCADOS 19,99
   *
   * O marcador "|" encerra corretamente a linha anterior e inicia
   * uma nova área de lançamentos.
   */
  const trecho = String(conteudo)
    .replace(
      /\s*\d+\s*\/\s*\d+\s+DETALHAMENTO\s+DA\s+FATURA\s+DESPESAS\s+COMPRA\s+DATA\s+DESCRI[CÇ][AÃ]O(?:\s+PARCELA)?\s+R\$\s+US\$\s*/gi,
      " | "
    )
    .replace(
      /DETALHAMENTO\s+DA\s+FATURA\s+DESPESAS\s+COMPRA\s+DATA\s+DESCRI[CÇ][AÃ]O(?:\s+PARCELA)?\s+R\$\s+US\$/gi,
      " | "
    )
    .replace(
      /COMPRA\s+DATA\s+DESCRI[CÇ][AÃ]O\s+PARCELA\s+R\$\s+US\$/gi,
      " "
    )
    .replace(
      /COMPRA\s+DATA\s+DESCRI[CÇ][AÃ]O\s+R\$\s+US\$/gi,
      " "
    )
    .replace(/\s*\|\s*/g, " | ")
    .replace(/\s+/g, " ")
    .trim();

  /*
   * Exemplos:
   * 1 17/06 PRB EMBALAGENS 01/03 260,84
   * 17/06 RETA ALIMENTOS LTDA 259,60
   * 28/05 RAIA4246 -0,02
   *
   * O número isolado antes da data é apenas uma marca visual do PDF.
   */
  const regexLinha =
    /(?:^|\|\s*|\s)(?:\d+\s+)?(\d{2}\/\d{2})\s+(.+?)\s+(?:(\d{2}\/\d{2})\s+)?(-?[\d.]+,\d{2})(?=\s*(?:\||(?:\d+\s+)?\d{2}\/\d{2}\s+|VALOR\s+TOTAL|$))/g;

  let matchLinha;

  while (
    (matchLinha = regexLinha.exec(trecho)) !== null
  ) {
    const data = dataSemAnoParaISO(
      matchLinha[1],
      faturaFechadaEm
    );

    const estabelecimento =
      matchLinha[2];

    const parcela =
      matchLinha[3] || null;

    const valor =
      paraNumero(matchLinha[4]);

    adicionarLinha({
      cartao,
      data,
      estabelecimento,
      parcela,
      valor,
      tipo: tipoPadrao,
      secao
    });
  }
}

/***********************************************************************
 * PROCESSA CADA CARTÃO
 ***********************************************************************/

for (
  let indice = 0;
  indice < marcadoresUnicos.length;
  indice++
) {
  const marcadorAtual =
    marcadoresUnicos[indice];

  const inicio =
    marcadorAtual.indice;

  let fim = textoUmaLinha.length;

  if (
    indice <
    marcadoresUnicos.length - 1
  ) {
    fim =
      marcadoresUnicos[indice + 1].indice;
  } else {
    const posicaoResumo =
      textoBusca.indexOf(
        "RESUMO DA FATURA",
        inicio
      );

    if (posicaoResumo >= 0) {
      fim = posicaoResumo;
    }
  }

  const blocoCartao = textoUmaLinha
    .substring(inicio, fim)
    .trim();

  /*
   * Pagamentos e créditos.
   */
  const blocoCreditos = trechoEntre(
    blocoCartao,
    "Pagamento e Demais Créditos",
    [
      "Parcelamentos",
      "Despesas",
      "VALOR TOTAL"
    ]
  );

  extrairLinhasSecao({
    conteudo: blocoCreditos,
    cartao: marcadorAtual.final,
    secao: "PAGAMENTOS_CREDITOS",
    tipoPadrao: "credito"
  });

  /*
   * Compras parceladas.
   */
  const blocoParcelamentos = trechoEntre(
    blocoCartao,
    "Parcelamentos",
    [
      "Despesas",
      "Pagamento e Demais Créditos",
      "VALOR TOTAL"
    ]
  );

  extrairLinhasSecao({
    conteudo: blocoParcelamentos,
    cartao: marcadorAtual.final,
    secao: "PARCELAMENTOS",
    tipoPadrao: "parcela"
  });

  /*
   * Compras normais.
   */
  const blocoDespesas = trechoEntre(
    blocoCartao,
    "Despesas",
    [
      "Pagamento e Demais Créditos",
      "Parcelamentos",
      "VALOR TOTAL",
      "Resumo da Fatura"
    ]
  );

  extrairLinhasSecao({
    conteudo: blocoDespesas,
    cartao: marcadorAtual.final,
    secao: "DESPESAS",
    tipoPadrao: "compra"
  });
}

/***********************************************************************
 * QUEBRAS DE PÁGINA
 *
 * Já são tratadas dentro de extrairLinhasSecao().
 * Não fazemos uma segunda leitura da continuação porque isso duplicava
 * lançamentos como PAULISTA SUPERMERCADOS.
 ***********************************************************************/

/***********************************************************************
 * PREPARA AS LINHAS
 *
 * Não removemos linhas por data/estabelecimento/valor, porque duas compras
 * legítimas podem ter exatamente os mesmos dados.
 *
 * A duplicidade causada pela quebra de página foi eliminada na origem,
 * removendo a segunda leitura do bloco continuado.
 ***********************************************************************/

const linhasUnicas = linhas.map((linha, index) => ({
  ...linha,
  linha: index + 1
}));

/***********************************************************************
 * ORDENA CARTÕES E DATAS
 ***********************************************************************/

const ordemCartoes = new Map(
  cartoesFinais.map(
    (final, indice) => [
      final,
      indice
    ]
  )
);

linhasUnicas.sort((a, b) => {
  const ordemA =
    ordemCartoes.get(a.cartao_final) ?? 999;

  const ordemB =
    ordemCartoes.get(b.cartao_final) ?? 999;

  if (ordemA !== ordemB) {
    return ordemA - ordemB;
  }

  if (a.data !== b.data) {
    return String(a.data).localeCompare(
      String(b.data)
    );
  }

  return 0;
});

/***********************************************************************
 * TOTAIS IMPORTADOS
 ***********************************************************************/

const totalCompras = arredondar(
  linhasUnicas
    .filter((linha) => linha.valor > 0)
    .reduce(
      (soma, linha) =>
        soma + linha.valor,
      0
    )
);

const totalCreditos = arredondar(
  Math.abs(
    linhasUnicas
      .filter((linha) => linha.valor < 0)
      .reduce(
        (soma, linha) =>
          soma + linha.valor,
        0
      )
  )
);

const totalImportado = arredondar(
  linhasUnicas.reduce(
    (soma, linha) =>
      soma + linha.valor,
    0
  )
);

const diferenca = arredondar(
  totalImportado - totalFatura
);

const conciliado =
  Math.abs(diferenca) <= 0.01;

/***********************************************************************
 * TOTAIS POR CARTÃO
 ***********************************************************************/

const totaisPorCartao =
  cartoesFinais.map((final) => {
    const linhasCartao =
      linhasUnicas.filter(
        (linha) =>
          linha.cartao_final === final
      );

    const compras = arredondar(
      linhasCartao
        .filter(
          (linha) => linha.valor > 0
        )
        .reduce(
          (soma, linha) =>
            soma + linha.valor,
          0
        )
    );

    const creditos = arredondar(
      Math.abs(
        linhasCartao
          .filter(
            (linha) => linha.valor < 0
          )
          .reduce(
            (soma, linha) =>
              soma + linha.valor,
            0
          )
      )
    );

    return {
      cartao_final: final,
      quantidade: linhasCartao.length,
      total_compras: compras,
      total_creditos: creditos,
      total_liquido: arredondar(
        compras - creditos
      )
    };
  });

/***********************************************************************
 * DADOS DO CARTÃO
 ***********************************************************************/

const dadosCartaoPdf = {
  banco,
  finais: cartoesFinais,
  vencimento,
  vencimento_dia: vencimentoDia,
  fechamento,
  fechamento_dia: fechamentoDia,
  nome: nomeCartao,
  bandeira,
  titular
};

/***********************************************************************
 * VALIDAÇÃO FINAL
 ***********************************************************************/

const camposFaltantes = [];

if (!banco) {
  camposFaltantes.push("banco");
}

if (!cartaoFinal) {
  camposFaltantes.push("cartao_final");
}

if (!vencimento) {
  camposFaltantes.push("vencimento");
}

if (!totalFatura) {
  camposFaltantes.push("total_fatura");
}

if (!linhasUnicas.length) {
  camposFaltantes.push("linhas");
}

const ok =
  Boolean(banco) &&
  Boolean(cartaoFinal) &&
  Boolean(vencimento) &&
  totalFatura > 0 &&
  linhasUnicas.length > 0;

/***********************************************************************
 * VALIDAÇÃO PARA A UI
 ***********************************************************************/

const mensagemValidacao = conciliado
  ? `PDF validado: total importado R$ ${totalImportado
      .toFixed(2)
      .replace(".", ",")} igual ao total da fatura.`
  : `Divergência na fatura Santander. Total importado ${totalImportado}, ` +
    `total da fatura ${arredondar(totalFatura)}, diferença ${diferenca}.`;

const validacao = {
  origem: "PDF",
  ok: conciliado,
  bloqueiaSalvar: !conciliado,
  mensagem: mensagemValidacao,
  totalPDF: arredondar(totalFatura),
  totalImportado,
  compras: totalCompras,
  creditosEstornos: totalCreditos,
  pagamentos: arredondar(
    pagamentosAnteriores.reduce(
      (soma, linha) => soma + Math.abs(Number(linha.valor || 0)),
      0
    )
  ),
  diferenca
};

/***********************************************************************
 * RETORNO FINAL
 ***********************************************************************/

const resultado = {
  ok,
  origem: "PDF_N8N",

  banco,

  cartao_final: cartaoFinal,
  cartoes_finais: cartoesFinais,

  vencimento,
  vencimento_dia: vencimentoDia,

  fechamento,
  fechamento_dia: fechamentoDia,

  fatura_fechada_em:
    faturaFechadaEm,

  nome_cartao: nomeCartao,
  bandeira,
  titular,

  dados_cartao_pdf:
    dadosCartaoPdf,

  total_fatura:
    arredondar(totalFatura),

  total_importado:
    totalImportado,

  total_compras:
    totalCompras,

  total_creditos:
    totalCreditos,

  diferenca,
  conciliado,
  mensagem: mensagemValidacao,
  validacao,

  quantidade_registros:
    linhasUnicas.length,

  total_debitos_resumo:
    arredondar(totalDebitosResumo),

  total_creditos_resumo:
    arredondar(totalCreditosResumo),

  total_pagamentos_resumo:
    arredondar(totalPagamentosResumo),

  totais_por_cartao:
    totaisPorCartao,

  pagamentos_anteriores:
    pagamentosAnteriores,

  linhas:
    linhasUnicas
};

if (!ok) {
  resultado.erro =
    "Não foi possível extrair todos os dados essenciais da fatura";

  resultado.campos_faltantes =
    camposFaltantes;
}

return [
  {
    json: resultado
  }
];

   /*
 * ============================================================
 * ENTRADAS
 * ============================================================
 */

// Resultado do PostgreSQL imediatamente anterior ao Code
const contaBanco = $input.first().json;

// Resultado do Extract From PDF
const entrada = $('ExtractBradesco').first().json;

const texto = String(
  entrada.text ||
  entrada.texto_pdf ||
  ""
);

function respostaErro(tipoErro, mensagem, detalhes = [], diagnostico = {}) {
  return [
    {
      json: {
        ok: false,
        conta_validada: false,
        tipo_erro: tipoErro,
        mensagem,
        detalhes: Array.isArray(detalhes) ? detalhes : [detalhes],
        diagnostico,
        movimentos: [],
        quantidade: 0
      }
    }
  ];
}

if (!texto.trim()) {
  return respostaErro(
    "PDF_SEM_TEXTO",
    "O PDF não retornou texto para processamento.",
    [],
    { texto_extraido: false }
  );
}

/*
 * ============================================================
 * CONTA CADASTRADA NO FINANCEFLOW
 * ============================================================
 */

const contaFinanceFlow = {
  id:
    contaBanco.id ||
    contaBanco.conta_id,

  empresa_id:
    contaBanco.empresa_id ||
    entrada.empresa_id ||
    entrada.body?.empresa_id,

  nome:
    contaBanco.nome ||
    contaBanco.conta_nome ||
    "",

  banco:
    contaBanco.banco ||
    "",

  agencia:
    contaBanco.agencia ||
    "",

  conta:
    contaBanco.conta ||
    contaBanco.numero_conta ||
    ""
};

if (!contaFinanceFlow.id) {
  return respostaErro(
    "CONTA_NAO_ENCONTRADA",
    "A conta financeira selecionada não foi encontrada no FinanceFlow."
  );
}

if (!contaFinanceFlow.banco) {
  return respostaErro(
    "BANCO_NAO_CADASTRADO",
    "A conta selecionada não possui banco cadastrado no FinanceFlow."
  );
}

if (!contaFinanceFlow.agencia) {
  return respostaErro(
    "AGENCIA_NAO_CADASTRADA",
    "A conta selecionada não possui agência cadastrada no FinanceFlow."
  );
}

if (!contaFinanceFlow.conta) {
  return respostaErro(
    "CONTA_NAO_CADASTRADA",
    "A conta selecionada não possui número da conta cadastrado no FinanceFlow."
  );
}

/*
 * ============================================================
 * FUNÇÕES AUXILIARES
 * ============================================================
 */

function numeroBR(valor) {
  return (
    Number(
      String(valor || "")
        .replace(/\./g, "")
        .replace(",", ".")
    ) || 0
  );
}

function normalizarTexto(valor) {
  return String(valor || "")
    .replace(/\r/g, "\n")
    .replace(/\u00a0/g, " ")
    .replace(/[ \t]+/g, " ")
    .trim();
}

function somenteNumeros(valor) {
  const numeros = String(valor || "")
    .replace(/\D/g, "");

  return numeros.replace(/^0+/, "") || "0";
}

function normalizarBanco(valor) {
  const banco = String(valor || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toUpperCase()
    .trim();

  if (
    banco.includes("BRADESCO") ||
    banco === "237" ||
    banco.includes("BANCO BRADESCO")
  ) {
    return "BRADESCO";
  }

  return banco;
}

/*
 * ============================================================
 * IDENTIFICA BANCO, AGÊNCIA E CONTA NO PDF
 * ============================================================
 *
 * Exemplo:
 * Agência: 1693 | Conta: 21530-9
 */

const textoParaCabecalho = texto
  .normalize("NFD")
  .replace(/[\u0300-\u036f]/g, "")
  .replace(/\u00a0/g, " ");

// Aceita cabeçalho com ou sem "|" e com quebra de linha entre os campos.
const cabecalhoConta = textoParaCabecalho.match(
  /AGENCIA\s*:?\s*([0-9]+)[\s|;,-]*CONTA\s*:?\s*([0-9.\-]+)/i
);

if (!cabecalhoConta) {
  const linhasCabecalho = texto
    .split(/\r?\n/)
    .map((linha) => linha.trim())
    .filter(Boolean)
    .slice(0, 30);

  return respostaErro(
    "CABECALHO_BRADESCO_NAO_IDENTIFICADO",
    "Não foi possível identificar a agência e a conta no cabeçalho do extrato Bradesco.",
    ["O formato do cabeçalho deste PDF é diferente do formato esperado."],
    {
      texto_extraido: true,
      formato_esperado: "Agência: 1693 | Conta: 21530-9",
      primeiras_linhas_pdf: linhasCabecalho
    }
  );
}

const agenciaArquivo =
  cabecalhoConta[1];

const contaArquivo =
  cabecalhoConta[2];

/*
 * Exemplo:
 * Nome: ANA CRISTINA LANDUCCI
 */

const cabecalhoTitular = texto.match(
  /NOME\s*:\s*(.+?)(?:\n|EXTRATO\s+DE\s*:)/i
);

const titularArquivo =
  cabecalhoTitular
    ? cabecalhoTitular[1].trim()
    : "";

const dadosArquivo = {
  banco: "BRADESCO",
  agencia: agenciaArquivo,
  conta: contaArquivo,
  titular: titularArquivo
};

/*
 * ============================================================
 * VALIDAÇÃO DA CONTA
 * ============================================================
 */

const bancoSistema = normalizarBanco(
  contaFinanceFlow.banco
);

const bancoArquivo = normalizarBanco(
  dadosArquivo.banco
);

const agenciaSistema = somenteNumeros(
  contaFinanceFlow.agencia
);

const agenciaPdf = somenteNumeros(
  dadosArquivo.agencia
);

const contaSistema = somenteNumeros(
  contaFinanceFlow.conta
);

const contaPdf = somenteNumeros(
  dadosArquivo.conta
);

const divergenciasConta = [];

if (
  bancoSistema &&
  bancoSistema !== bancoArquivo
) {
  divergenciasConta.push(
    `Banco selecionado: ${contaFinanceFlow.banco}; banco do arquivo: ${dadosArquivo.banco}`
  );
}

if (
  agenciaSistema &&
  agenciaSistema !== agenciaPdf
) {
  divergenciasConta.push(
    `Agência selecionada: ${contaFinanceFlow.agencia}; agência do arquivo: ${dadosArquivo.agencia}`
  );
}

if (
  contaSistema &&
  contaSistema !== contaPdf
) {
  divergenciasConta.push(
    `Conta selecionada: ${contaFinanceFlow.conta}; conta do arquivo: ${dadosArquivo.conta}`
  );
}

/*
 * Conta incorreta:
 * interrompe o processamento sem gerar erro técnico.
 */

if (divergenciasConta.length > 0) {
  return [
    {
      json: {
        ok: false,
        conta_validada: false,

        tipo_erro:
          "CONTA_BANCARIA_INCORRETA",

        mensagem:
          "O extrato enviado não pertence à conta selecionada. " +
          "Selecione a conta correta e importe novamente.",

        detalhes:
          divergenciasConta,

        conta_selecionada: {
          id:
            contaFinanceFlow.id,

          nome:
            contaFinanceFlow.nome,

          banco:
            contaFinanceFlow.banco,

          agencia:
            contaFinanceFlow.agencia,

          conta:
            contaFinanceFlow.conta
        },

        conta_arquivo: {
          banco:
            dadosArquivo.banco,

          agencia:
            dadosArquivo.agencia,

          conta:
            dadosArquivo.conta,

          titular:
            dadosArquivo.titular ||
            "Não identificado"
        },

        movimentos: [],
        quantidade: 0
      }
    }
  ];
}

/*
 * ============================================================
 * IDENTIFICA LINHAS QUE NÃO SÃO MOVIMENTOS
 * ============================================================
 */

function ehLinhaCabecalho(linha) {
  const txt = String(linha || "")
    .toUpperCase()
    .trim();

  return (
    txt === "BRADESCO CELULAR" ||
    txt.startsWith("DATA:") ||
    txt.startsWith("NOME:") ||
    txt.startsWith("EXTRATO DE:") ||
    txt.startsWith("FOLHA:") ||
    txt.startsWith("DATA HISTÓRICO") ||
    txt.startsWith("DATA HISTORICO") ||
    txt.startsWith("TOTAL ") ||
    txt === "EXTRATO INEXISTENTE"
  );
}

function ehComplementoTecnico(linha) {
  const txt = String(linha || "")
    .toUpperCase()
    .trim();

  return (
    (
      /^AG\d+/i.test(txt) &&
      txt.includes("MAQ")
    ) ||
    txt.startsWith("EXTRATOMES")
  );
}

/*
 * ============================================================
 * PREPARA AS LINHAS
 * ============================================================
 */

const linhas = normalizarTexto(texto)
  .split("\n")
  .map((linha) => linha.trim())
  .filter(Boolean)
  .filter(
    (linha) => !ehLinhaCabecalho(linha)
  );

const registrosBrutos = [];
let registros = [];

let dataAtual = "";
let historicoPartes = [];
let saldoAnterior = null;
let saldoInicial = null;

function registrarRegistro(
  data,
  historico,
  documento,
  valorTexto,
  saldoTexto
) {
  const valor = numeroBR(valorTexto);
  const saldoAbsoluto = numeroBR(saldoTexto);

  registrosBrutos.push({
    data,
    historico: String(historico || "").trim(),
    documento,
    valor,
    saldoAbsoluto
  });

  dataAtual = data;
  historicoPartes = [];
}

/*
 * ============================================================
 * PROCESSA O EXTRATO
 * ============================================================
 */

for (
  let i = 0;
  i < linhas.length;
  i++
) {
  const linha = linhas[i];

  /*
   * Exemplo:
   * 02/04/2026 INSS 0021693 3.497,54 3.502,04
   */

  const linhaCompleta = linha.match(
    /^(\d{2}\/\d{2}\/\d{4})\s+(.+?)\s+(\d+)\s+([\d.]+,\d{2})\s+([\d.]+,\d{2})$/
  );

  if (linhaCompleta) {
    registrarRegistro(
      linhaCompleta[1],
      linhaCompleta[2],
      linhaCompleta[3],
      linhaCompleta[4],
      linhaCompleta[5]
    );

    continue;
  }

  /*
   * Histórico em linha anterior e depois:
   * 06/04/2026 0306761 0,03 3.502,07
   */

  const linhaDataValor = linha.match(
    /^(\d{2}\/\d{2}\/\d{4})\s+(\d+)\s+([\d.]+,\d{2})\s+([\d.]+,\d{2})$/
  );

  if (linhaDataValor) {
    registrarRegistro(
      linhaDataValor[1],
      historicoPartes.filter(Boolean).join(" - ").trim(),
      linhaDataValor[2],
      linhaDataValor[3],
      linhaDataValor[4]
    );

    continue;
  }

  /*
   * Linha contendo somente a data
   */

  const somenteData = linha.match(
    /^(\d{2}\/\d{2}\/\d{4})$/
  );

  if (somenteData) {
    dataAtual =
      somenteData[1];

    historicoPartes =
      [];

    continue;
  }

  /*
   * Mesma data do movimento anterior, com histórico na própria linha:
   * INSS 0021693 5.246,31 5.249,57
   */

  const linhaHistoricoValor = linha.match(
    /^(.+?)\s+(\d+)\s+([\d.]+,\d{2})\s+([\d.]+,\d{2})$/
  );

  if (linhaHistoricoValor && dataAtual) {
    const historico = [
      ...historicoPartes,
      linhaHistoricoValor[1]
    ]
      .filter(Boolean)
      .join(" - ")
      .trim();

    registrarRegistro(
      dataAtual,
      historico,
      linhaHistoricoValor[2],
      linhaHistoricoValor[3],
      linhaHistoricoValor[4]
    );

    continue;
  }

  /*
   * Exemplo:
   * 0306761 0,03 3.502,07
   */

  const linhaValor = linha.match(
    /^(\d+)\s+([\d.]+,\d{2})\s+([\d.]+,\d{2})$/
  );

  if (
    linhaValor &&
    dataAtual
  ) {
    registrarRegistro(
      dataAtual,
      historicoPartes.filter(Boolean).join(" - ").trim(),
      linhaValor[1],
      linhaValor[2],
      linhaValor[3]
    );

    continue;
  }

  /*
   * Complemento do rendimento aparece depois da linha de valor.
   * Anexa ao último rendimento, sem contaminar o próximo movimento.
   */

  if (
    /^POUP\s+FACIL/i.test(linha) &&
    registrosBrutos.length > 0 &&
    /RENDIMENTOS/i.test(
      registrosBrutos[registrosBrutos.length - 1].historico
    )
  ) {
    registrosBrutos[registrosBrutos.length - 1].historico +=
      ` - ${linha}`;

    continue;
  }

  /*
   * Ignora códigos técnicos de ATM.
   */

  if (
    ehComplementoTecnico(linha)
  ) {
    continue;
  }

  /*
   * Guarda as linhas do histórico
   * até encontrar documento, valor e saldo.
   */

  const proximaLinha = linhas[i + 1] || "";

  const proximaLinhaTemValor =
    /^(\d{2}\/\d{2}\/\d{4})\s+(.+?)\s+(\d+)\s+([\d.]+,\d{2})\s+([\d.]+,\d{2})$/.test(proximaLinha) ||
    /^(\d{2}\/\d{2}\/\d{4})\s+(\d+)\s+([\d.]+,\d{2})\s+([\d.]+,\d{2})$/.test(proximaLinha) ||
    /^(.+?)\s+(\d+)\s+([\d.]+,\d{2})\s+([\d.]+,\d{2})$/.test(proximaLinha) ||
    /^(\d+)\s+([\d.]+,\d{2})\s+([\d.]+,\d{2})$/.test(proximaLinha);

  /*
   * No layout do Bradesco, detalhes como DES:, REM:, nomes e
   * observações aparecem depois da linha de valor. Se a próxima
   * linha não contém valor, esta linha complementa o último registro.
   */

  if (
    historicoPartes.length === 0 &&
    !proximaLinhaTemValor &&
    registrosBrutos.length > 0
  ) {
    registrosBrutos[registrosBrutos.length - 1].historico +=
      ` - ${linha}`;

    continue;
  }

  historicoPartes.push(
    linha
  );
}

/*
 * ============================================================
 * RESOLVE O SINAL DOS SALDOS
 * ============================================================
 *
 * O PDF do Bradesco indica saldo negativo somente pela cor vermelha.
 * Na extração do texto, o sinal é perdido. Por isso testamos saldo
 * positivo e negativo e escolhemos a sequência que confere com os
 * totais de crédito e débito impressos no próprio extrato.
 */

const totaisImpressos = [...texto.matchAll(
  /TOTAL\s+([\d.]+,\d{2})\s+([\d.]+,\d{2})\s+([\d.]+,\d{2})/gi
)];

const totalCreditoImpresso = totaisImpressos.reduce(
  (total, match) => total + numeroBR(match[1]),
  0
);

const totalDebitoImpresso = totaisImpressos.reduce(
  (total, match) => total + numeroBR(match[2]),
  0
);

function opcoesSaldo(valorAbsoluto) {
  return valorAbsoluto === 0
    ? [0]
    : [valorAbsoluto, -valorAbsoluto];
}

let caminhos = [];

if (registrosBrutos.length > 0) {
  const primeiro = registrosBrutos[0];

  caminhos = opcoesSaldo(primeiro.saldoAbsoluto).map(
    (saldo) => ({
      saldoInicial: saldo,
      saldoAtual: saldo,
      registros: [],
      totalCreditos: 0,
      totalDebitos: 0
    })
  );

  for (let i = 1; i < registrosBrutos.length; i++) {
    const bruto = registrosBrutos[i];
    const proximos = [];

    for (const caminho of caminhos) {
      for (const saldoAtualCandidato of opcoesSaldo(bruto.saldoAbsoluto)) {
        let tipo = null;

        if (
          Math.abs(
            caminho.saldoAtual + bruto.valor - saldoAtualCandidato
          ) < 0.011
        ) {
          tipo = "C";
        } else if (
          Math.abs(
            caminho.saldoAtual - bruto.valor - saldoAtualCandidato
          ) < 0.011
        ) {
          tipo = "D";
        }

        if (!tipo) continue;

        proximos.push({
          saldoInicial: caminho.saldoInicial,
          saldoAtual: saldoAtualCandidato,
          registros: [
            ...caminho.registros,
            {
              data: bruto.data,
              historico: bruto.historico,
              documento: bruto.documento,
              valor: bruto.valor,
              tipo,
              saldo: saldoAtualCandidato
            }
          ],
          totalCreditos:
            caminho.totalCreditos +
            (tipo === "C" ? bruto.valor : 0),
          totalDebitos:
            caminho.totalDebitos +
            (tipo === "D" ? bruto.valor : 0)
        });
      }
    }

    // Mantém caminhos distintos pelo saldo e pelos totais acumulados.
    const unicos = new Map();

    for (const caminho of proximos) {
      const chave = [
        caminho.saldoAtual.toFixed(2),
        caminho.totalCreditos.toFixed(2),
        caminho.totalDebitos.toFixed(2)
      ].join("|");

      if (!unicos.has(chave)) {
        unicos.set(chave, caminho);
      }
    }

    caminhos = [...unicos.values()];

    if (caminhos.length === 0) {
      break;
    }
  }
}

const caminhoEscolhido = caminhos
  .map((caminho) => ({
    ...caminho,
    diferencaTotais:
      Math.abs(caminho.totalCreditos - totalCreditoImpresso) +
      Math.abs(caminho.totalDebitos - totalDebitoImpresso)
  }))
  .sort((a, b) => a.diferencaTotais - b.diferencaTotais)[0];

if (caminhoEscolhido) {
  registros = caminhoEscolhido.registros;
  saldoInicial = caminhoEscolhido.saldoInicial;
  saldoAnterior = caminhoEscolhido.saldoAtual;
}

/*
 * ============================================================
 * FORMATA OS MOVIMENTOS
 * ============================================================
 */

const movimentos = registros.map(
  (registro) => ({
    data:
      registro.data,

    historico:
      registro.historico,

    valor:
      registro.valor,

    tipo:
      registro.tipo
  })
);

const totalCreditos = registros
  .filter((registro) => registro.tipo === "C")
  .reduce((total, registro) => total + registro.valor, 0);

const totalDebitos = registros
  .filter((registro) => registro.tipo === "D")
  .reduce((total, registro) => total + registro.valor, 0);

const diferencaCreditosImpressos = Number(
  (totalCreditos - totalCreditoImpresso).toFixed(2)
);

const diferencaDebitosImpressos = Number(
  (totalDebitos - totalDebitoImpresso).toFixed(2)
);

const totaisImpressosConferem =
  totaisImpressos.length > 0 &&
  Math.abs(diferencaCreditosImpressos) <= 0.01 &&
  Math.abs(diferencaDebitosImpressos) <= 0.01;

const sequenciaSaldosResolvida =
  Boolean(caminhoEscolhido) &&
  registros.length === Math.max(registrosBrutos.length - 1, 0);

const saldoFinal = saldoAnterior;
const saldoCalculado = saldoInicial === null
  ? null
  : saldoInicial + totalCreditos - totalDebitos;

const diferencaSaldo =
  saldoFinal === null || saldoCalculado === null
    ? null
    : Number((saldoFinal - saldoCalculado).toFixed(2));

const saldoConfere =
  diferencaSaldo === null
    ? false
    : Math.abs(diferencaSaldo) <= 0.01 &&
      sequenciaSaldosResolvida;

/*
 * ============================================================
 * RETORNO FINAL DO N8N
 * ============================================================
 */

return [
  {
    json: {
      ok: true,
      conta_validada: true,

      empresa_id:
        contaFinanceFlow.empresa_id,

