*/

function normalizarTexto(valor) {
  return String(valor || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toUpperCase()
    .replace(/\s+/g, " ")
    .trim();
}

function somenteNumeros(valor) {
  const numeros = String(valor || "")
    .replace(/\D/g, "");

  return numeros.replace(/^0+/, "") || "0";
}

function normalizarBanco(valor) {
  const banco = normalizarTexto(valor);
  const codigo = somenteNumeros(valor);

  if (
    banco.includes("SANTANDER") ||
    codigo === "33"
  ) {
    return "SANTANDER";
  }

  if (
    banco.includes("SICOOB") ||
    codigo === "756"
  ) {
    return "SICOOB";
  }

  if (
    banco.includes("BRADESCO") ||
    codigo === "237"
  ) {
    return "BRADESCO";
  }

  if (
    banco.includes("ITAU") ||
    codigo === "341"
  ) {
    return "ITAU";
  }

  if (
    banco.includes("BANCO DO BRASIL") ||
    codigo === "1"
  ) {
    return "BANCO DO BRASIL";
  }

  if (
    banco.includes("CAIXA") ||
    codigo === "104"
  ) {
    return "CAIXA";
  }

  return banco;
}

function converterValorBR(valor) {
  const textoValor = String(valor || "")
    .trim()
    .replace(/\s/g, "");

  const negativo =
    textoValor.startsWith("-");

  const numero = Number(
    textoValor
      .replace("-", "")
      .replace(/\./g, "")
      .replace(",", ".")
  );

  if (!Number.isFinite(numero)) {
    return 0;
  }

  return negativo
    ? numero * -1
    : numero;
}

function criarDataISO(ano, mes, dia) {
  return (
    `${String(ano).padStart(4, "0")}-` +
    `${String(mes).padStart(2, "0")}-` +
    `${String(dia).padStart(2, "0")}`
  );
}

function dataParaISO(valor) {
  const txt = String(valor || "").trim();

  if (/^\d{4}-\d{2}-\d{2}$/.test(txt)) {
    return txt;
  }

  const match = txt.match(
    /^(\d{2})\/(\d{2})\/(\d{4})$/
  );

  if (!match) {
    return "";
  }

  return criarDataISO(
    match[3],
    match[2],
    match[1]
  );
}

 function limparHistorico(valor) {
  return String(valor || "")
    .replace(/\s+/g, " ")
    .trim();
}
/*
