        },

        movimentos: [],
        quantidade: 0
      }
    }
  ];
}

/*
|--------------------------------------------------------------------------
| PERÍODO DO EXTRATO
|--------------------------------------------------------------------------
|
| Exemplo:
| Períodos: 04/06/2026 a 03/08/2026
