*/

const textoPeriodo = String(texto || "")
  .normalize("NFD")
  .replace(/[\u0300-\u036f]/g, "")
  .replace(/\r/g, " ")
  .replace(/\n/g, " ")
  .replace(/\s+/g, " ")
  .trim();

const periodoMatch = textoPeriodo.match(
  /PERIODOS?\s*:\s*(\d{1,2})\/(\d{1,2})\/(\d{4})\s*(?:A|ATE|-)\s*(\d{1,2})\/(\d{1,2})\/(\d{4})/i
);

let dataInicio =
