    periodoMatch[2],
    periodoMatch[1]
  );

  dataFim = criarDataISO(
    periodoMatch[6],
    periodoMatch[5],
    periodoMatch[4]
  );
}

dataInicio = dataParaISO(dataInicio);
dataFim = dataParaISO(dataFim);

if (!dataInicio || !dataFim) {
