function ignorarLinhaGeral(linha) {
  const txt = normalizarTexto(linha);

  return (
    txt === "DATA HISTORICO DOCUMENTO VALOR (R$) SALDO (R$)" ||
    txt.startsWith("APLICATIVO SANTANDER EMPRESAS") ||
    txt.startsWith("PERIODOS:") ||
    txt.startsWith("SALDO DISPONIVEL PARA USO:") ||
    txt.startsWith("CENTRAL DE ATENDIMENTO") ||
    txt.startsWith("SAC -") ||
    txt.startsWith("OUVIDORIA") ||
    txt.startsWith("SALDO DE CONTAMAX") ||
    txt.startsWith("SALDO DISPONIVEL") ||
    txt.startsWith("POSICAO EM:") ||
    txt.startsWith("ENTENDA A COMPOSICAO") ||
    txt.startsWith("JUROS ACUMULADOS") ||
    txt.startsWith("IOF ACUMULADO") ||
    txt.startsWith("DESBLOQUEIO EM") ||
    /^[0-9]+\/[0-9]+$/.test(txt) ||
    /^[A-J]\s*[-–]/.test(txt)
  );
}

/*
|--------------------------------------------------------------------------
| AGRUPA E FECHA CADA MOVIMENTO ASSIM QUE ENCONTRA VALOR + SALDO
|--------------------------------------------------------------------------
|
| Esse fechamento imediato corrige dois casos do PDF:
|
| 1) 01/07/2026 IOF ... -4,26 717,29
|    A linha seguinte "PERIODO: 01/06..." não pode entrar no movimento.
|
| 2) 05/06/2026 Transferência ... -19.000,00 -18.360,31
|    As linhas de resumo do final do PDF não podem entrar no movimento.
|--------------------------------------------------------------------------
*/

const regexFinalMovimento =
  /(-?\d{1,3}(?:\.\d{3})*,-?\d{2}|-?\d+,\d{2})\s+(-?\d{1,3}(?:\.\d{3})*,-?\d{2}|-?\d+,\d{2})$/i;

const blocos = [];
const linhasSoltas = [];
let blocoAtual = "";

function blocoEstaCompleto(bloco) {
  return (
    /^\d{2}\/\d{2}\/\d{4}\b/.test(bloco) &&
    regexFinalMovimento.test(bloco)
  );
}

for (const linha of linhasOriginais) {
  if (ignorarLinhaGeral(linha)) {
    continue;
  }

  const iniciaMovimento =
    /^\d{2}\/\d{2}\/\d{4}\b/.test(linha);

  if (iniciaMovimento) {
    if (blocoAtual) {
      if (blocoEstaCompleto(blocoAtual)) {
        blocos.push(blocoAtual);
      } else {
        linhasSoltas.push({
          linha: blocoAtual,
          motivo: "BLOCO_INCOMPLETO_ANTES_DE_NOVA_DATA"
        });
      }
    }

    blocoAtual = linha;
  } else if (blocoAtual) {
    /*
    |--------------------------------------------------------------------------
    | Só anexa continuação enquanto o movimento ainda não estiver completo.
    | Depois de valor + saldo, qualquer linha seguinte pertence a rodapé,
    | observação geral ou ao próximo conteúdo do documento.
    |--------------------------------------------------------------------------
    */

    if (blocoEstaCompleto(blocoAtual)) {
      blocos.push(blocoAtual);
      blocoAtual = "";
      linhasSoltas.push({
        linha,
        motivo: "LINHA_FORA_DE_MOVIMENTO"
      });
    } else {
      blocoAtual += ` ${linha}`;
    }
  }
}

if (blocoAtual) {
  if (blocoEstaCompleto(blocoAtual)) {
    blocos.push(blocoAtual);
  } else {
    linhasSoltas.push({
      linha: blocoAtual,
      motivo: "ULTIMO_BLOCO_INCOMPLETO"
    });
  }
}

/*
|--------------------------------------------------------------------------
| EXTRAÇÃO DOS MOVIMENTOS
|--------------------------------------------------------------------------
*/

const movimentosInternos = [];
const ignoradas = [...linhasSoltas];

const regexMovimento =
  /^(\d{2})\/(\d{2})\/(\d{4})\s+(.+?)\s+(-?\d{1,3}(?:\.\d{3})*,-?\d{2}|-?\d+,\d{2})\s+(-?\d{1,3}(?:\.\d{3})*,-?\d{2}|-?\d+,\d{2})$/i;

for (const bloco of blocos) {
  const match = bloco.match(regexMovimento);

  if (!match) {
    ignoradas.push({
      linha: bloco,
      motivo: "FORMATO_NAO_RECONHECIDO"
    });

    continue;
  }

  const data = criarDataISO(
    match[3],
    match[2],
    match[1]
  );

  let parteHistorico = match[4]
    .replace(/\s+/g, " ")
    .trim();

  const valorMovimento =
    converterValorBR(match[5]);

  const saldoAposMovimento =
    converterValorBR(match[6]);


/*
|--------------------------------------------------------------------------
| PRESERVA CPF/CNPJ E REMOVE SOMENTE DOCUMENTO ADICIONAL
|--------------------------------------------------------------------------
|
| Um número:
| Pix Recebido 41129609804
| → mantém o número
|
| Dois números:
| Pix Recebido 69123730625 14315321
| → mantém CPF/CNPJ e remove somente o documento final
|--------------------------------------------------------------------------
*/

let documento = "";

const doisNumerosFinaisMatch =
  parteHistorico.match(
    /^(.*?\s+\d{11,14})\s+(\d{6,10})$/
  );

if (doisNumerosFinaisMatch) {
  parteHistorico =
    doisNumerosFinaisMatch[1].trim();

  documento =
    doisNumerosFinaisMatch[2].trim();
}


  const historico =
    limparHistorico(parteHistorico);

  const natureza_movimento =
  valorMovimento > 0 &&
  normalizarTexto(historico).includes("GETNET")
    ? "pagamento_operadora"
    : null;

  if (
    data < dataInicio ||
    data > dataFim
  ) {
    ignoradas.push({
      linha: bloco,
      motivo: "DATA_FORA_DO_PERIODO"
    });

    continue;
  }

  if (
    !historico ||
    valorMovimento === 0
  ) {
    ignoradas.push({
      linha: bloco,
      motivo: "MOVIMENTO_INVALIDO"
    });

    continue;
  }

  movimentosInternos.push({
    data,
    historico,
    valor: Math.abs(valorMovimento),
    valor_assinado: valorMovimento,
    tipo:
      valorMovimento < 0
        ? "D"
        : "C",
    saldo:
      saldoAposMovimento,

  natureza_financeira:   natureza_movimento
  });
}

/*
|--------------------------------------------------------------------------
| MOVIMENTOS PARA O RETORNO
|--------------------------------------------------------------------------
|
| valor_assinado é usado somente para calcular o saldo inicial.
| O saldo de cada linha permanece no retorno para futura validação na proc.
|--------------------------------------------------------------------------
*/

const movimentos = movimentosInternos.map(
  ({
    valor_assinado,
