}

/*
|--------------------------------------------------------------------------
| TOTAIS E SALDOS PARA DIAGNÓSTICO
|--------------------------------------------------------------------------
|
| O Santander apresenta os movimentos em ordem decrescente:
|
| primeiro movimento = mais recente = saldo final
| último movimento   = mais antigo
|
| saldo inicial = saldo após o movimento mais antigo - valor assinado
|--------------------------------------------------------------------------
*/

const movimentoMaisRecente =
  movimentosInternos[0];

const movimentoMaisAntigo =
  movimentosInternos[
    movimentosInternos.length - 1
  ];

const saldoFinal =
  movimentoMaisRecente.saldo;

const saldoInicial =
  movimentoMaisAntigo.saldo -
  movimentoMaisAntigo.valor_assinado;

const totalCreditos = movimentos
  .filter((movimento) =>
    movimento.tipo === "C"
  )
  .reduce(
    (total, movimento) =>
      total + movimento.valor,
    0
  );

const totalDebitos = movimentos
  .filter((movimento) =>
    movimento.tipo === "D"
  )
  .reduce(
    (total, movimento) =>
      total + movimento.valor,
    0
  );

const saldoCalculado =
  saldoInicial +
  totalCreditos -
  totalDebitos;

const diferencaSaldo =
  saldoCalculado -
  saldoFinal ;

const saldoConfere =
  Math.abs(diferencaSaldo) <= 0.01;

/*
|--------------------------------------------------------------------------
| RETORNO DE SUCESSO
|--------------------------------------------------------------------------
*/

return [
  {
    json: {
      ok: true,
      conta_validada: true,

      empresa_id:
        contaFinanceFlow.empresa_id,

      conta_id:
        contaFinanceFlow.id,

