          ).length,

        quantidade_debitos:
          movimentos.filter(
            (movimento) =>
              movimento.tipo === "D"
          ).length,

        total_creditos:
          Number(totalCreditos.toFixed(2)),

        total_debitos:
          Number(totalDebitos.toFixed(2)),

        saldo_inicial:
          Number(saldoInicial.toFixed(2)),

        saldo_final:
          Number(saldoFinal.toFixed(2)),

        saldo_calculado:
          Number(saldoCalculado.toFixed(2)),

        diferenca_saldo:
          Number(diferencaSaldo.toFixed(2)),

        saldo_confere:
          saldoConfere,

        primeiro_movimento:
          movimentos[0] || null,

        ultimo_movimento:
          movimentos[
            movimentos.length - 1
          ] || null
      }
    }
  }
];

  /*
