/*
|--------------------------------------------------------------------------
| IDENTIFICA COOPERATIVA/AGÊNCIA E CONTA NO PDF
|--------------------------------------------------------------------------
|
| Exemplos possíveis:
|
| COOP.: 1234   CONTA: 12345-6
| COOPERATIVA: 1234 | CONTA: 12345-6
| COOP 1234 CONTA 12345-6
|--------------------------------------------------------------------------
*/

const cooperativaMatch =
  texto.match(
    /COOP(?:ERATIVA)?\.?\s*:?\s*([0-9]+)/i
  );

const contaMatch =
  texto.match(
    /CONTA\.?\s*:?\s*([0-9.\-]+)/i
