*/

const titularMatch =
  texto.match(
    /(?:TITULAR|NOME)\s*:?\s*(.+?)(?:\n|COOP|CONTA|PER[ÍI]ODO)/i
  );

const titularArquivo = titularMatch
  ? titularMatch[1].trim()
  : "";

const dadosArquivo = {
  banco: "SICOOB",
  agencia: cooperativaArquivo,
  conta: contaArquivo,
  titular: titularArquivo
};

/*
|--------------------------------------------------------------------------
| VALIDAÇÃO DA CONTA
|--------------------------------------------------------------------------
*/

const bancoSistema =
  normalizarBanco(contaFinanceFlow.banco);

const bancoArquivo =
  normalizarBanco(dadosArquivo.banco);

const agenciaSistema =
  somenteNumeros(contaFinanceFlow.agencia);

const agenciaPdf =
  somenteNumeros(dadosArquivo.agencia);

const contaSistema =
  somenteNumeros(contaFinanceFlow.conta);

const contaPdf =
  somenteNumeros(dadosArquivo.conta);

const divergenciasConta = [];

/*
 * Banco sempre será comparado.
 */
if (
  bancoSistema &&
  bancoSistema !== bancoArquivo
) {
  divergenciasConta.push(
    `Banco selecionado: ${contaFinanceFlow.banco}; banco do arquivo: ${dadosArquivo.banco}`
  );
}

/*
 * Cooperativa/agência somente será comparada se estiver
 * preenchida nos dois lados.
 */
if (
  contaFinanceFlow.agencia &&
  dadosArquivo.agencia &&
  agenciaSistema !== agenciaPdf
) {
  divergenciasConta.push(
    `Agência/Cooperativa selecionada: ${contaFinanceFlow.agencia}; ` +
    `agência/cooperativa do arquivo: ${dadosArquivo.agencia}`
  );
}

/*
 * Conta sempre será comparada.
 */
if (
  contaSistema &&
  contaPdf &&
  contaSistema !== contaPdf
) {
  divergenciasConta.push(
    `Conta selecionada: ${contaFinanceFlow.conta}; conta do arquivo: ${dadosArquivo.conta}`
  );
}

/*
 * Se estiver diferente, não processa movimentos.
 */
if (divergenciasConta.length > 0) {
  return [
