        quantidade: 0
      }
    }
  ];
}

/*
|--------------------------------------------------------------------------
| PERÍODO DO EXTRATO
|--------------------------------------------------------------------------
|
| Exemplo:
| PERÍODO: 01/07/2026 - 20/07/2026
