}

const periodoInicio = criarDataISO(
  periodoMatch[3],
  periodoMatch[2],
  periodoMatch[1]
);

const periodoFim = criarDataISO(
  periodoMatch[6],
  periodoMatch[5],
  periodoMatch[4]
);

const anoInicio =
  Number(periodoMatch[3]);

const anoFim =
  Number(periodoMatch[6]);

/*
|--------------------------------------------------------------------------
| RESOLVE DD/MM PARA YYYY-MM-DD
|--------------------------------------------------------------------------
*/

function resolverDataISO(dia, mes) {
  const candidatos = [
    ...new Set([anoInicio, anoFim])
  ];

  for (const ano of candidatos) {
    const dataISO = criarDataISO(
      ano,
      mes,
      dia
    );

    if (
      dataISO >= periodoInicio &&
      dataISO <= periodoFim
    ) {
      return dataISO;
    }
  }

  return null;
}

/*
|--------------------------------------------------------------------------
| FUNÇÕES DE SALDO
|--------------------------------------------------------------------------
*/

function valorComSinal(valor, natureza) {
  const numero = converterValorBR(valor);
  const tipo = String(natureza || "")
    .trim()
    .toUpperCase();

  if (tipo === "D") {
    return -Math.abs(numero);
  }

  return Math.abs(numero);
}

function arredondar(valor) {
  return Number(Number(valor || 0).toFixed(2));
}

/*
