/*
|--------------------------------------------------------------------------
| IDENTIFICA O TITULAR PELA LINHA DA CONTA, QUANDO NECESSÁRIO
|--------------------------------------------------------------------------
|
| Exemplo:
| CONTA: 343.324-2 / MASSAS DONA IVONE LTDA
|--------------------------------------------------------------------------
*/

if (!dadosArquivo.titular) {
  const contaTitularMatch = texto.match(
    /(?:^|\n)\s*CONTA\.?\s*:?\s*[0-9.\-]+\s*\/\s*([^\n\r]+)/im
  );

  if (contaTitularMatch) {
    dadosArquivo.titular = String(
      contaTitularMatch[1] || ""
    )
      .replace(/\s+/g, " ")
      .trim();
  }
}

/*
|--------------------------------------------------------------------------
| EXPRESSÃO PADRÃO DAS LINHAS FINANCEIRAS DO SICOOB
|--------------------------------------------------------------------------
|
| Exemplos:
|
| 30/07 SALDO DO DIA 344,76C
| 30/07 CHQ CMP INTEGRADA 315,00D
| 30/06 SALDO ANTERIOR 2.701,40C
|--------------------------------------------------------------------------
*/

const regexLinhaFinanceira =
  /^(\d{2})\/(\d{2})\s+(.+?)\s+([\d.]+,\d{2})([CD*])$/i;

const movimentos = [];
const ignoradas = [];
const saldosDia = [];

let saldoInicialArquivo = null;
let saldoFinalResumo = null;

let quantidadeLinhasFinanceiras = 0;
let quantidadeLinhasReconhecidas = 0;

/*
|--------------------------------------------------------------------------
| SALDO FINAL DO RESUMO
|--------------------------------------------------------------------------
|
| O resumo normalmente contém:
| (+) SALDO EM CONTA: 344,76C
|--------------------------------------------------------------------------
*/

const saldoEmContaMatch = texto.match(
  /\(\+\)\s*SALDO\s+EM\s+CONTA\s*:\s*([\d.]+,\d{2})([CD])/i
);

if (saldoEmContaMatch) {
  saldoFinalResumo = valorComSinal(
    saldoEmContaMatch[1],
    saldoEmContaMatch[2]
  );
}

/*
|--------------------------------------------------------------------------
| EXTRAÇÃO DE MOVIMENTOS E SALDOS DO ARQUIVO
|--------------------------------------------------------------------------
*/
 /*
|--------------------------------------------------------------------------
| AGRUPA LINHA PRINCIPAL E DETALHES DO MOVIMENTO
|--------------------------------------------------------------------------
*/

const blocosFinanceiros = [];
let blocoAtual = null;

for (const linha of linhasTexto) {
  const matchFinanceiro =
    linha.match(regexLinhaFinanceira);

  if (matchFinanceiro) {
    if (blocoAtual) {
      blocosFinanceiros.push(blocoAtual);
    }

    blocoAtual = {
      linhaPrincipal: linha,
      match: matchFinanceiro,
      detalhes: []
    };

    continue;
  }

  /*
   * Linhas abaixo da movimentação pertencem ao mesmo registro
   * até aparecer uma nova linha com data, valor e C/D.
   */
  if (blocoAtual) {
    const detalheNormalizado =
      normalizarTexto(linha);

    const ignorarDetalhe =
      detalheNormalizado ===
        "HISTORICO DE MOVIMENTACAO" ||
      detalheNormalizado ===
        "DATA HISTORICO VALOR" ||
      detalheNormalizado.startsWith(
        "SICOOB"
      ) ||
      detalheNormalizado.startsWith(
        "SISTEMA DE COOPERATIVAS"
      ) ||
      detalheNormalizado.startsWith(
        "PLATAFORMA DE SERVICOS"
      ) ||
      detalheNormalizado.startsWith(
        "EXTRATO CONTA CORRENTE"
      ) ||
      detalheNormalizado.startsWith(
        "COOP.:"
      ) ||
      detalheNormalizado.startsWith(
        "CONTA:"
      ) ||
      detalheNormalizado.startsWith(
        "PERIODO:"
      ) ||
      /^\d+\/\d+$/.test(
        detalheNormalizado
      );

    if (!ignorarDetalhe) {
      blocoAtual.detalhes.push(linha);
    }
  }
}

if (blocoAtual) {
  blocosFinanceiros.push(blocoAtual);
}

/*
|--------------------------------------------------------------------------
| EXTRAÇÃO DOS MOVIMENTOS COM DESCRIÇÃO COMPLETA
|--------------------------------------------------------------------------
*/

for (const bloco of blocosFinanceiros) {
  const match = bloco.match;

  quantidadeLinhasFinanceiras += 1;

  const dia = match[1];
  const mes = match[2];

  const historicoPrincipal =
    String(match[3] || "")
      .replace(/\s+/g, " ")
      .trim();

  const valorTexto = match[4];

  const tipoOriginal =
    String(match[5] || "")
      .trim()
      .toUpperCase();

  const historicoNormalizado =
    normalizarTexto(
      historicoPrincipal
    );

  /*
  |--------------------------------------------------------------------------
  | SALDO ANTERIOR
  |--------------------------------------------------------------------------
  */

  if (
    historicoNormalizado ===
      "SALDO ANTERIOR" ||
    (
      historicoNormalizado.includes(
        "SALDO ANTERIOR"
      ) &&
      !historicoNormalizado.includes(
        "BLOQ"
      )
    )
  ) {
    saldoInicialArquivo =
      valorComSinal(
        valorTexto,
        tipoOriginal
      );

    quantidadeLinhasReconhecidas += 1;

    ignoradas.push({
      linha: bloco.linhaPrincipal,
      motivo: "SALDO_INICIAL_ARQUIVO"
    });

    continue;
  }

  /*
  |--------------------------------------------------------------------------
  | SALDO DO DIA
  |--------------------------------------------------------------------------
  */

  if (
    historicoNormalizado.includes(
      "SALDO DO DIA"
    )
  ) {
    const dataSaldo =
      resolverDataISO(
        dia,
        mes
      );

    if (dataSaldo) {
      saldosDia.push({
        data: dataSaldo,

        saldo: valorComSinal(
          valorTexto,
          tipoOriginal
        ),

        linha:
          bloco.linhaPrincipal
      });
    }

    quantidadeLinhasReconhecidas += 1;

    ignoradas.push({
      linha: bloco.linhaPrincipal,
      motivo: "SALDO_DO_DIA"
    });

    continue;
  }

  /*
  |--------------------------------------------------------------------------
  | OUTROS SALDOS E RESUMOS
  |--------------------------------------------------------------------------
  */

  if (
    historicoNormalizado.includes(
      "SALDO BLOQ"
    ) ||
    historicoNormalizado.includes(
      "SALDO BLOQUEADO"
    ) ||
    historicoNormalizado.includes(
      "SALDO DISPONIVEL"
    ) ||
    historicoNormalizado.includes(
      "SALDO EM CONTA"
    ) ||
    historicoNormalizado.includes(
      "CHEQUE ESPECIAL CONTRATADO"
    ) ||
    historicoNormalizado.includes(
      "JUROS VENCIDOS PROVISIONADOS"
    ) ||
    historicoNormalizado.includes(
      "TARIFAS VENCIDAS PROVISIONADAS"
    ) ||
    historicoNormalizado.includes(
      "PREVISAO IOF"
    ) ||
    historicoNormalizado.includes(
      "PREVISAO JUROS"
    ) ||
    historicoNormalizado.includes(
      "PREVISAO TARIFAS"
    )
  ) {
    quantidadeLinhasReconhecidas += 1;

    ignoradas.push({
      linha: bloco.linhaPrincipal,
      motivo: "SALDO_OU_RESUMO"
    });

    continue;
  }

  const data =
    resolverDataISO(
      dia,
      mes
    );

  const valor =
    converterValorBR(
      valorTexto
    );

  if (!data) {
    quantidadeLinhasReconhecidas += 1;

    ignoradas.push({
      linha: bloco.linhaPrincipal,
      motivo: "DATA_FORA_DO_PERIODO"
    });

    continue;
  }

  if (
    !historicoPrincipal ||
    valor <= 0 ||
    !["C", "D"].includes(
      tipoOriginal
    )
  ) {
    quantidadeLinhasReconhecidas += 1;

    ignoradas.push({
      linha: bloco.linhaPrincipal,
      motivo: "MOVIMENTO_INVALIDO"
    });

    continue;
  }

  /*
  |--------------------------------------------------------------------------
  | MONTA HISTÓRICO COMPLETO
  |--------------------------------------------------------------------------
  |
  | Remove apenas DOC.: Pix porque não acrescenta informação.
  | Mantém nome, CPF/CNPJ mascarado, favorecido e observação.
  |--------------------------------------------------------------------------
  */

  const detalhesUteis =
    bloco.detalhes
      .map((detalhe) =>
        String(detalhe || "")
          .replace(/\s+/g, " ")
          .trim()
      )
      .filter(Boolean)
      .filter((detalhe) => {
        const normalizado =
          normalizarTexto(detalhe);

        return (
          normalizado !== "DOC.: PIX" &&
          normalizado !== "DOC: PIX"
        );
      });

  const historicoCompleto =
    [
      historicoPrincipal,
      ...detalhesUteis
    ]
      .filter(Boolean)
      .join(" - ")
      .replace(/\s+/g, " ")
      .trim();

  quantidadeLinhasReconhecidas += 1;

  movimentos.push({
    data,
    historico:
      historicoCompleto,
    valor,
    tipo: tipoOriginal
  });
}

if (
  quantidadeLinhasFinanceiras !==
  quantidadeLinhasReconhecidas
) {
  return [
    {
      json: {
        ok: false,
        conta_validada: true,
        tipo_erro: "EXTRACAO_INCOMPLETA",

        mensagem:
          "O extrato Sicoob contém linhas financeiras que não foram reconhecidas. A importação foi interrompida.",

        detalhes: [
          `Linhas financeiras encontradas: ${quantidadeLinhasFinanceiras}`,
          `Linhas reconhecidas: ${quantidadeLinhasReconhecidas}`,
          "Nenhum movimento foi enviado para gravação."
        ],

        empresa_id:
          contaFinanceFlow.empresa_id,

        conta_id:
          contaFinanceFlow.id,

        banco: "SICOOB",

        dados_conta_arquivo: {
          banco: dadosArquivo.banco,
          agencia: dadosArquivo.agencia,
          conta: dadosArquivo.conta,
          titular:
            dadosArquivo.titular ||
            "Não identificado"
        },

        movimentos: [],
        quantidade: 0,

        diagnostico: {
          tipo_layout: "SICOOB_SISBR",
          quantidade_linhas:
            linhasTexto.length,
          quantidade_linhas_financeiras:
            quantidadeLinhasFinanceiras,
          quantidade_linhas_reconhecidas:
            quantidadeLinhasReconhecidas,
          saldo_confere: false
        }
      }
    }
  ];
}

/*
|--------------------------------------------------------------------------
| NENHUMA MOVIMENTAÇÃO
|--------------------------------------------------------------------------
*/

if (!movimentos.length) {
  return [
    {
      json: {
        ok: false,
        conta_validada: true,
        tipo_erro: "MOVIMENTOS_NAO_ENCONTRADOS",

        mensagem:
          "Nenhuma movimentação válida foi encontrada no extrato Sicoob.",

        detalhes: [
          `${ignoradas.length} linha(s) foram identificadas e ignoradas.`
        ],

        conta_selecionada: {
          id: contaFinanceFlow.id,
          nome: contaFinanceFlow.nome,
          banco: contaFinanceFlow.banco,
          agencia: contaFinanceFlow.agencia,
          conta: contaFinanceFlow.conta
        },

        conta_arquivo: {
          banco: dadosArquivo.banco,
          agencia: dadosArquivo.agencia,
          conta: dadosArquivo.conta,
          titular:
            dadosArquivo.titular ||
            "Não identificado"
        },

        movimentos: [],
        quantidade: 0,

        quantidade_ignoradas:
          ignoradas.length,

        linhas_ignoradas:
          ignoradas
      }
    }
  ];
}

/*
|--------------------------------------------------------------------------
| TOTAIS DOS MOVIMENTOS EXTRAÍDOS
|--------------------------------------------------------------------------
*/

const quantidadeCreditos =
  movimentos.filter(
    (movimento) =>
      movimento.tipo === "C"
  ).length;

const quantidadeDebitos =
  movimentos.filter(
    (movimento) =>
      movimento.tipo === "D"
  ).length;

const totalCreditos =
  movimentos
    .filter(
      (movimento) =>
        movimento.tipo === "C"
    )
    .reduce(
      (total, movimento) =>
        total + movimento.valor,
      0
    );

const totalDebitos =
  movimentos
    .filter(
      (movimento) =>
        movimento.tipo === "D"
    )
    .reduce(
      (total, movimento) =>
        total + movimento.valor,
      0
    );

/*
|--------------------------------------------------------------------------
| SALDO FINAL DO ARQUIVO
|--------------------------------------------------------------------------
|
| Prioridade:
|
| 1. (+) SALDO EM CONTA do resumo;
| 2. SALDO DO DIA mais recente dentro do período.
|--------------------------------------------------------------------------
*/

const saldosDiaOrdenados =
  [...saldosDia].sort(
    (a, b) =>
      String(b.data).localeCompare(
        String(a.data)
      )
  );

const saldoFinalArquivo =
  saldoFinalResumo !== null
    ? saldoFinalResumo
    : (
        saldosDiaOrdenados[0]?.saldo ??
        null
      );

/*
|--------------------------------------------------------------------------
| SALDOS OBRIGATÓRIOS
|--------------------------------------------------------------------------
*/

if (
  saldoInicialArquivo === null ||
  saldoFinalArquivo === null
) {
  return [
    {
      json: {
        ok: false,
        conta_validada: true,
        tipo_erro:
          "SALDOS_NAO_IDENTIFICADOS",

        mensagem:
          "Importação cancelada. Não foi possível identificar o saldo inicial e o saldo final do extrato Sicoob.",

        detalhes: [
          `Saldo inicial encontrado: ${
            saldoInicialArquivo !== null
              ? "SIM"
              : "NÃO"
          }`,
          `Saldo final encontrado: ${
            saldoFinalArquivo !== null
              ? "SIM"
              : "NÃO"
          }`,
          "Nenhum movimento foi enviado para gravação."
        ],

        empresa_id:
          contaFinanceFlow.empresa_id,

        conta_id:
          contaFinanceFlow.id,

        banco:
          "SICOOB",

        dados_conta_arquivo: {
          banco: dadosArquivo.banco,
          agencia: dadosArquivo.agencia,
          conta: dadosArquivo.conta,
          titular:
            dadosArquivo.titular ||
            "Não identificado"
        },

        data_inicio:
          periodoInicio,

        data_fim:
          periodoFim,

        movimentos: [],
        quantidade: 0,

        diagnostico: {
          tipo_layout:
            "SICOOB_SISBR",

          quantidade_linhas:
            linhasTexto.length,

          quantidade_registros:
            movimentos.length,

          quantidade_creditos:
            quantidadeCreditos,

          quantidade_debitos:
            quantidadeDebitos,

          total_creditos:
            arredondar(totalCreditos),

          total_debitos:
            arredondar(totalDebitos),

          saldo_inicial:
            saldoInicialArquivo === null
              ? null
              : arredondar(
                  saldoInicialArquivo
                ),

          saldo_final:
            saldoFinalArquivo === null
              ? null
              : arredondar(
                  saldoFinalArquivo
                ),

          saldo_calculado:
            null,

          diferenca_saldo:
            null,

          saldo_confere:
            false,

          primeiro_movimento:
            movimentos[0] || null,

          ultimo_movimento:
            movimentos[
              movimentos.length - 1
            ] || null
        }
      }
    }
  ];
}

/*
|--------------------------------------------------------------------------
| CONFERÊNCIA GERAL DO EXTRATO
|--------------------------------------------------------------------------
|
| saldo inicial
| + créditos
| - débitos
| = saldo final
|--------------------------------------------------------------------------
*/

const saldoCalculado =
  saldoInicialArquivo +
  totalCreditos -
  totalDebitos;

const diferencaSaldo =
  arredondar(
    saldoCalculado -
    saldoFinalArquivo
  );

const saldoConfere =
  Math.abs(diferencaSaldo) <= 0.01;

/*
|--------------------------------------------------------------------------
| CONFERÊNCIA DOS SALDOS DIÁRIOS
|--------------------------------------------------------------------------
|
| Essa validação é adicional.
| Para cada dia com "SALDO DO DIA", recalcula o saldo acumulado.
|--------------------------------------------------------------------------
*/

const movimentosPorData = {};

for (const movimento of movimentos) {
  if (!movimentosPorData[movimento.data]) {
    movimentosPorData[movimento.data] = {
      creditos: 0,
      debitos: 0
    };
  }

  if (movimento.tipo === "C") {
    movimentosPorData[
      movimento.data
    ].creditos += movimento.valor;
  } else {
    movimentosPorData[
      movimento.data
    ].debitos += movimento.valor;
  }
}

const datasComMovimento =
  Object.keys(movimentosPorData).sort();

let saldoAcumulado =
  saldoInicialArquivo;

const validacoesDiarias = [];

for (const data of datasComMovimento) {
  const totaisDia =
    movimentosPorData[data];

  saldoAcumulado =
    saldoAcumulado +
    totaisDia.creditos -
    totaisDia.debitos;

  const saldoInformado =
    saldosDia.find(
      (item) =>
        item.data === data
    );

  if (saldoInformado) {
    const diferencaDia =
      arredondar(
        saldoAcumulado -
        saldoInformado.saldo
      );

    validacoesDiarias.push({
      data,
      saldo_calculado:
        arredondar(saldoAcumulado),
      saldo_arquivo:
        arredondar(
          saldoInformado.saldo
        ),
      diferenca:
        diferencaDia,
      confere:
        Math.abs(diferencaDia) <= 0.01
    });
  }
}

const diasComDivergencia =
  validacoesDiarias.filter(
    (item) =>
      item.confere === false
  );

const saldosDiariosConferem =
  diasComDivergencia.length === 0;

/*
|--------------------------------------------------------------------------
| BLOQUEIA ANTES DA GRAVAÇÃO
|--------------------------------------------------------------------------
*/

if (
  !saldoConfere ||
  !saldosDiariosConferem
) {
  return [
    {
      json: {
        ok: false,
        conta_validada: true,
        tipo_erro:
          "EXTRATO_NAO_CONFERE",

        mensagem:
          "Importação cancelada. Os movimentos extraídos não reproduzem os saldos apresentados no extrato Sicoob.",

        detalhes: [
          "O PDF pode possuir uma variação de layout ou uma movimentação ainda não reconhecida pela rotina.",
          `Diferença geral: R$ ${Math.abs(
            diferencaSaldo
          ).toFixed(2)}`,
          `Dias com divergência: ${
            diasComDivergencia.length
          }`,
          "Nenhum movimento foi enviado para gravação."
        ],

        empresa_id:
          contaFinanceFlow.empresa_id,

        conta_id:
          contaFinanceFlow.id,

        finalidade:
          entrada.finalidade ||
          entrada.body?.finalidade ||
          contaBanco.finalidade ||
          entrada.tipo_processamento ||
          "IMPORTACAO",

        banco:
          "SICOOB",

        dados_conta_arquivo: {
          banco: dadosArquivo.banco,
          agencia: dadosArquivo.agencia,
          conta: dadosArquivo.conta,
          titular:
            dadosArquivo.titular ||
            "Não identificado"
        },

        dados_conta_financeflow: {
          id:
            contaFinanceFlow.id,

          nome:
            contaFinanceFlow.nome,

          banco:
            contaFinanceFlow.banco,

          agencia:
            contaFinanceFlow.agencia,

          conta:
            contaFinanceFlow.conta
        },

        data_inicio:
          periodoInicio,

        data_fim:
          periodoFim,

        movimentos: [],
        quantidade: 0,

        quantidade_ignoradas:
          ignoradas.length,

        linhas_ignoradas:
          ignoradas,

        diagnostico: {
          tipo_layout:
            "SICOOB_SISBR",

          quantidade_linhas:
            linhasTexto.length,

          quantidade_linhas_financeiras:
            quantidadeLinhasFinanceiras,

          quantidade_registros:
            movimentos.length,

          quantidade_creditos:
            quantidadeCreditos,

          quantidade_debitos:
            quantidadeDebitos,

          total_creditos:
            arredondar(totalCreditos),

          total_debitos:
            arredondar(totalDebitos),

          saldo_inicial:
            arredondar(
              saldoInicialArquivo
            ),

          saldo_final:
            arredondar(
              saldoFinalArquivo
            ),

          saldo_calculado:
            arredondar(
              saldoCalculado
            ),

          diferenca_saldo:
            diferencaSaldo,

          saldo_confere:
            false,

          quantidade_saldos_dia:
            saldosDia.length,

          quantidade_dias_validados:
            validacoesDiarias.length,

          dias_com_divergencia:
            diasComDivergencia,

          primeiro_movimento:
            movimentos[0] || null,

          ultimo_movimento:
            movimentos[
              movimentos.length - 1
            ] || null
        }
      }
    }
  ];
}

/*
|--------------------------------------------------------------------------
| RETORNO DE SUCESSO
|--------------------------------------------------------------------------
*/

return [
  {
    json: {
      ok: true,
      conta_validada: true,

      empresa_id:
        contaFinanceFlow.empresa_id,

      conta_id:
        contaFinanceFlow.id,

      finalidade:
        entrada.finalidade ||
        entrada.body?.finalidade ||
        contaBanco.finalidade ||
        entrada.tipo_processamento ||
        "IMPORTACAO",

      banco:
        "SICOOB",

      dados_conta_arquivo: {
        banco:
          dadosArquivo.banco,

        agencia:
          dadosArquivo.agencia,

        conta:
          dadosArquivo.conta,

        titular:
          dadosArquivo.titular
      },

      dados_conta_financeflow: {
        id:
          contaFinanceFlow.id,

        nome:
          contaFinanceFlow.nome,

        banco:
          contaFinanceFlow.banco,

        agencia:
          contaFinanceFlow.agencia,

        conta:
          contaFinanceFlow.conta
      },

      data_inicio:
        periodoInicio,

      data_fim:
        periodoFim,

      movimentos,

      quantidade:
        movimentos.length,

      quantidade_ignoradas:
        ignoradas.length,

      linhas_ignoradas:
        ignoradas,

      diagnostico: {
        tipo_layout:
          "SICOOB_SISBR",

        quantidade_linhas:
          linhasTexto.length,

        quantidade_linhas_financeiras:
          quantidadeLinhasFinanceiras,

        quantidade_registros:
          movimentos.length,

        quantidade_creditos:
          quantidadeCreditos,

        quantidade_debitos:
          quantidadeDebitos,

        total_creditos:
          arredondar(totalCreditos),

        total_debitos:
          arredondar(totalDebitos),

        saldo_inicial:
          arredondar(
            saldoInicialArquivo
          ),

        saldo_final:
          arredondar(
            saldoFinalArquivo
          ),

        saldo_calculado:
          arredondar(
            saldoCalculado
          ),

        diferenca_saldo:
          diferencaSaldo,

        saldo_confere:
          true,

        quantidade_saldos_dia:
          saldosDia.length,

        quantidade_dias_validados:
          validacoesDiarias.length,

        dias_com_divergencia:
          [],

        primeiro_movimento:
          movimentos[0] || null,

        ultimo_movimento:
          movimentos[
            movimentos.length - 1
          ] || null
      }
    }
  }
];

parameters.query:
 SELECT
    id,
    empresa_id,
    nome,
    banco,
    agencia,
    conta
FROM public.contas_financeiras
WHERE empresa_id = {{
  Number($('extrato_pdf_bradesco').first().json.body?.empresa_id
