  /*
|--------------------------------------------------------------------------
| ENTRADAS
|--------------------------------------------------------------------------
*/

// PostgreSQL imediatamente anterior ao Code
const contaBanco = $input.first().json;

// Node Extract From PDF
const entrada = $('ExtractXP').first().json;

const texto = String(
  entrada.text ||
  entrada.texto_pdf ||
  ""
);

if (!texto.trim()) {
  throw new Error(
    "O PDF não retornou texto para processamento."
  );
}

/*
|--------------------------------------------------------------------------
| CONTA CADASTRADA NO FINANCEFLOW
|--------------------------------------------------------------------------
*/

const contaFinanceFlow = {
  id:
    contaBanco.id ||
    contaBanco.conta_id,

  empresa_id:
    contaBanco.empresa_id ||
    entrada.empresa_id ||
    entrada.body?.empresa_id,

  nome:
    contaBanco.nome ||
    contaBanco.conta_nome ||
    "",

  banco:
    contaBanco.banco ||
    contaBanco.banco_nome ||
    "",

  agencia:
    contaBanco.agencia ||
    "",

  conta:
    contaBanco.conta ||
    contaBanco.numero_conta ||
    ""
};

if (!contaFinanceFlow.id) {
  throw new Error(
    "A conta financeira selecionada não foi encontrada no FinanceFlow."
  );
}

if (!contaFinanceFlow.banco) {
  throw new Error(
    "A conta selecionada não possui banco cadastrado no FinanceFlow."
  );
}

if (!contaFinanceFlow.conta) {
  throw new Error(
    "A conta selecionada não possui número da conta cadastrado no FinanceFlow."
  );
}

/*
|--------------------------------------------------------------------------
| FUNÇÕES AUXILIARES
|--------------------------------------------------------------------------
*/

function normalizarTexto(valor) {
  return String(valor || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toUpperCase()
    .trim();
}

function somenteNumeros(valor) {
  const numeros = String(valor || "")
    .replace(/\D/g, "");

  return numeros.replace(/^0+/, "") || "0";
}

function normalizarBanco(valor) {
  const banco = normalizarTexto(valor);
  const codigo = somenteNumeros(valor);

  if (
    banco === "XP" ||
    banco.includes("BANCO XP") ||
    banco.includes("CONTA DIGITAL XP") ||
    banco.includes("XP INVESTIMENTOS") ||
    codigo === "348"
  ) {
    return "XP";
  }

  if (
    banco.includes("SICOOB") ||
    codigo === "756"
  ) {
    return "SICOOB";
  }

  if (
    banco.includes("BRADESCO") ||
    codigo === "237"
  ) {
    return "BRADESCO";
  }

  if (
    banco.includes("SANTANDER") ||
    codigo === "33"
  ) {
    return "SANTANDER";
  }

  if (
    banco.includes("ITAU") ||
    codigo === "341"
  ) {
    return "ITAU";
  }

  if (
    banco.includes("BANCO DO BRASIL") ||
    codigo === "1"
  ) {
    return "BANCO DO BRASIL";
  }

  if (
    banco.includes("CAIXA") ||
    codigo === "104"
  ) {
    return "CAIXA";
  }

  return banco;
}

function converterValorBR(valor) {
  const numero = Number(
    String(valor || "")
      .replace(/\./g, "")
      .replace(",", ".")
  );

  return Number.isFinite(numero)
    ? numero
    : 0;
}

function criarDataISO(ano, mes, dia) {
  return (
    `${String(ano).padStart(4, "0")}-` +
    `${String(mes).padStart(2, "0")}-` +
    `${String(dia).padStart(2, "0")}`
  );
}

function converterDataCompletaParaISO(valor) {
  const match = String(valor || "").match(
    /^(\d{2})\/(\d{2})\/(\d{4})$/
  );

  if (!match) return "";

  return criarDataISO(
    match[3],
    match[2],
    match[1]
  );
}

function converterDataCurtaParaISO(valor) {
  const match = String(valor || "").match(
    /^(\d{2})\/(\d{2})\/(\d{2})$/
  );

  if (!match) return "";

  const anoCurto = Number(match[3]);

  const anoCompleto =
    anoCurto >= 70
      ? 1900 + anoCurto
      : 2000 + anoCurto;

  return criarDataISO(
    anoCompleto,
    match[2],
    match[1]
  );
}

/*
|--------------------------------------------------------------------------
| IDENTIFICA SE O ARQUIVO É XP
|--------------------------------------------------------------------------
*/

const textoNormalizado =
  normalizarTexto(texto);

const arquivoEhXP =
  textoNormalizado.includes("BANCO XP S.A") ||
  textoNormalizado.includes("CONTA DIGITAL XP") ||
  textoNormalizado.includes("XP | EXTRATO");

if (!arquivoEhXP) {
  return [
    {
      json: {
        ok: false,
        conta_validada: false,

        tipo_erro:
          "BANCO_DO_ARQUIVO_INCORRETO",

        mensagem:
          "O arquivo enviado não foi identificado como um extrato da XP.",

        detalhes: [
          `Banco selecionado no FinanceFlow: ${
            contaFinanceFlow.banco ||
            "não informado"
          }`,
          "Banco do arquivo: não identificado como Banco XP"
        ],

        conta_selecionada: {
          id: contaFinanceFlow.id,
          nome: contaFinanceFlow.nome,
          banco: contaFinanceFlow.banco,
          agencia: contaFinanceFlow.agencia,
          conta: contaFinanceFlow.conta
        },

        conta_arquivo: {
          banco: "NÃO IDENTIFICADO",
          agencia: "",
          conta: "",
          titular: ""
        },

        movimentos: [],
        quantidade: 0
      }
    }
  ];
}

/*
|--------------------------------------------------------------------------
| IDENTIFICA AGÊNCIA E CONTA NO PDF
|--------------------------------------------------------------------------
|
| Exemplo:
| Banco XP S.A | Agência: 0001 | Conta: 443378
|--------------------------------------------------------------------------
*/

const cabecalhoConta = texto.match(
  /BANCO\s+XP\s+S\.?A\.?\s*\|\s*AG[EÊ]NCIA\s*:\s*([0-9]+)\s*\|\s*CONTA\s*:\s*([0-9.\-]+)/i
);

if (!cabecalhoConta) {
  return [
    {
      json: {
        ok: false,
        conta_validada: false,

        tipo_erro:
          "CONTA_NAO_IDENTIFICADA_NO_ARQUIVO",

        mensagem:
          "Não foi possível identificar a agência e a conta no extrato da XP.",

        detalhes: [
          "O PDF foi identificado como XP, mas o cabeçalho bancário não foi reconhecido."
        ],

        conta_selecionada: {
          id: contaFinanceFlow.id,
          nome: contaFinanceFlow.nome,
          banco: contaFinanceFlow.banco,
          agencia: contaFinanceFlow.agencia,
          conta: contaFinanceFlow.conta
        },

        conta_arquivo: {
          banco: "XP",
          agencia: "",
          conta: "",
          titular: ""
        },

        movimentos: [],
        quantidade: 0
      }
    }
  ];
}

const agenciaArquivo =
  cabecalhoConta[1].trim();

const contaArquivo =
  cabecalhoConta[2].trim();

/*
|--------------------------------------------------------------------------
| IDENTIFICA TITULAR
|--------------------------------------------------------------------------
|
| Exemplo:
| LUIS GUSTAVO LANDUCCI Banco XP S.A
|--------------------------------------------------------------------------
*/

const titularMatch = texto.match(
  /(?:DATA\s+DA\s+CONSULTA:[^\n]*\n)?(.+?)\s+BANCO\s+XP\s+S\.?A/i
);

const titularArquivo =
  titularMatch
    ? titularMatch[1]
        .replace(/\s+/g, " ")
        .trim()
    : "";

const dadosArquivo = {
  banco: "XP",
  agencia: agenciaArquivo,
  conta: contaArquivo,
  titular: titularArquivo
};

/*
|--------------------------------------------------------------------------
| VALIDA BANCO, AGÊNCIA E CONTA
|--------------------------------------------------------------------------
*/

const bancoSistema =
  normalizarBanco(contaFinanceFlow.banco);

const bancoArquivo =
  normalizarBanco(dadosArquivo.banco);

const agenciaSistema =
  somenteNumeros(contaFinanceFlow.agencia);

const agenciaPdf =
  somenteNumeros(dadosArquivo.agencia);

const contaSistema =
  somenteNumeros(contaFinanceFlow.conta);

const contaPdf =
  somenteNumeros(dadosArquivo.conta);

const divergenciasConta = [];

if (
  bancoSistema &&
  bancoSistema !== bancoArquivo
) {
  divergenciasConta.push(
    `Banco selecionado: ${contaFinanceFlow.banco}; banco do arquivo: Banco XP`
  );
}

if (
  contaFinanceFlow.agencia &&
  dadosArquivo.agencia &&
  agenciaSistema !== agenciaPdf
) {
  divergenciasConta.push(
    `Agência selecionada: ${contaFinanceFlow.agencia}; agência do arquivo: ${dadosArquivo.agencia}`
  );
}

if (
  contaSistema &&
  contaPdf &&
  contaSistema !== contaPdf
) {
  divergenciasConta.push(
    `Conta selecionada: ${contaFinanceFlow.conta}; conta do arquivo: ${dadosArquivo.conta}`
  );
}

if (divergenciasConta.length > 0) {
  return [
    {
      json: {
        ok: false,
        conta_validada: false,

        tipo_erro:
          "CONTA_BANCARIA_INCORRETA",

        mensagem:
          "O extrato enviado não pertence à conta selecionada. " +
          "Selecione a conta correta e importe novamente.",

        detalhes:
          divergenciasConta,

        conta_selecionada: {
          id: contaFinanceFlow.id,
          nome: contaFinanceFlow.nome,
          banco: contaFinanceFlow.banco,
          agencia: contaFinanceFlow.agencia,
          conta: contaFinanceFlow.conta
        },

        conta_arquivo: {
          banco: dadosArquivo.banco,
          agencia: dadosArquivo.agencia,
          conta: dadosArquivo.conta,

          titular:
            dadosArquivo.titular ||
            "Não identificado"
        },

        movimentos: [],
        quantidade: 0
      }
    }
  ];
}

/*
|--------------------------------------------------------------------------
| IDENTIFICA PERÍODO
|--------------------------------------------------------------------------
|
| Exemplo:
| De: 01/08/2025 Até: 30/10/2025
|--------------------------------------------------------------------------
*/

const periodoMatch = texto.match(
  /DE\s*:\s*(\d{2}\/\d{2}\/\d{4})\s+AT[EÉ]\s*:\s*(\d{2}\/\d{2}\/\d{4})/i
);

if (!periodoMatch) {
  return [
    {
      json: {
        ok: false,
        conta_validada: true,

        tipo_erro:
          "PERIODO_NAO_IDENTIFICADO",

        mensagem:
          "Não foi possível identificar o período do extrato da XP.",

        detalhes: [
          "A conta bancária foi validada, mas as datas inicial e final não foram reconhecidas."
        ],

        conta_selecionada: {
          id: contaFinanceFlow.id,
          nome: contaFinanceFlow.nome,
          banco: contaFinanceFlow.banco,
          agencia: contaFinanceFlow.agencia,
          conta: contaFinanceFlow.conta
        },

        conta_arquivo: {
          banco: dadosArquivo.banco,
          agencia: dadosArquivo.agencia,
          conta: dadosArquivo.conta,

          titular:
            dadosArquivo.titular ||
            "Não identificado"
        },

        movimentos: [],
        quantidade: 0
      }
    }
  ];
}

const periodoInicio =
  converterDataCompletaParaISO(
    periodoMatch[1]
  );

const periodoFim =
  converterDataCompletaParaISO(
    periodoMatch[2]
  );

/*
|--------------------------------------------------------------------------
| RECORTA SOMENTE A ÁREA DE MOVIMENTOS
|--------------------------------------------------------------------------
|
| Começa depois de:
| Data Descrição Valor Saldo
|
| Termina antes de:
| Extrato simples para conferência
|--------------------------------------------------------------------------
*/

const inicioTabela =
  texto.search(
    /DATA\s+DESCRI[CÇ][AÃ]O\s+VALOR\s+SALDO/i
  );

let textoMovimentos =
  inicioTabela >= 0
    ? texto.substring(inicioTabela)
    : texto;

textoMovimentos = textoMovimentos
  .replace(/[−–—]/g, "-");

textoMovimentos = textoMovimentos.replace(
  /EXTRATO\s+SIMPLES\s+PARA\s+CONFER[EÊ]NCIA[\s\S]*$/i,
  ""
);

textoMovimentos = textoMovimentos.replace(
  /DATA\s+DESCRI[CÇ][AÃ]O\s+VALOR\s+SALDO/gi,
  "\n"
);

/*
|--------------------------------------------------------------------------
| NORMALIZA QUEBRAS DAS DESCRIÇÕES
|--------------------------------------------------------------------------
|
| Mantém as quebras que iniciam uma nova movimentação.
| As demais são transformadas em espaço.
|--------------------------------------------------------------------------
*/

const textoPreparado = textoMovimentos
  .replace(/\r/g, "\n")
  .replace(/\u00a0/g, " ")
  .replace(
    /\n(?!(?:\d{2}\/\d{2}\/\d{2})\s+[ÀA]S\s+\d{2}:\d{2}:\d{2})/gi,
    " "
  )
  .replace(/[ \t]+/g, " ")
  .replace(/\n+/g, "\n")
  .trim();

const quantidadeMovimentosAparentes = (
  textoPreparado.match(
    /\d{2}\/\d{2}\/\d{2}\s+[ÀA]S\s+\d{2}:\d{2}:\d{2}/gi
  ) || []
).length;

/*
|--------------------------------------------------------------------------
| EXTRAÇÃO DAS MOVIMENTAÇÕES
|--------------------------------------------------------------------------
|
| Exemplo:
|
| 28/10/25 às 13:09:33 POSTO ... -R$ 9,00 R$ 1,31
|
| Grupo 1 = data
| Grupo 2 = horário
| Grupo 3 = descrição
| Grupo 4 = sinal do movimento
| Grupo 5 = valor do movimento
| Grupo 6 = saldo, usado somente para diagnóstico
|--------------------------------------------------------------------------
*/

 const regexMovimento =
  /(\d{2}\/\d{2}\/\d{2})\s+[ÀA]S\s+(\d{2}:\d{2}:\d{2})\s+([\s\S]*?)\s+(-?)R\$\s*([\d.]+,\d{2})\s+(-?)R\$\s*([\d.]+,\d{2})(?=\s*(?:\d{2}\/\d{2}\/\d{2}\s+[ÀA]S\s+\d{2}:\d{2}:\d{2}|$))/gi;

const movimentos = [];
const ignoradas = [];

let match;

while (
  (match = regexMovimento.exec(textoPreparado)) !== null
) {
  const dataOriginal =
    match[1];

  const horario =
    match[2];

  const historico = String(match[3] || "")
    .replace(/\s+/g, " ")
    .trim();

  const negativo =
    match[4] === "-";

  const valor =
    converterValorBR(match[5]);

  const saldoNegativo =
    match[6] === "-";

  const saldoAbsoluto =
    converterValorBR(match[7]);

  const saldo =
    saldoNegativo
      ? -saldoAbsoluto
      : saldoAbsoluto;

  const data =
    converterDataCurtaParaISO(
      dataOriginal
    );

  if (
    !data ||
    data < periodoInicio ||
    data > periodoFim
  ) {
    ignoradas.push({
      data: dataOriginal,
      historico,
      valor,
      motivo:
        "DATA_FORA_DO_PERIODO"
    });

    continue;
  }

  if (
    !historico ||
    valor <= 0
  ) {
    ignoradas.push({
      data: dataOriginal,
      historico,
      valor,
      motivo:
        "MOVIMENTO_INVALIDO"
    });

    continue;
  }

  movimentos.push({
    data,
    historico,
    valor,

    tipo:
      negativo
        ? "D"
        : "C",

    horario,
    saldo
  });
}

/*
|--------------------------------------------------------------------------
| CONFERE SE TODAS AS LINHAS APARENTES FORAM EXTRAÍDAS
|--------------------------------------------------------------------------
*/

if (
  quantidadeMovimentosAparentes > 0 &&
  movimentos.length + ignoradas.length !== quantidadeMovimentosAparentes
) {
  return [
    {
      json: {
        ok: false,
        conta_validada: true,
        tipo_erro: "EXTRACAO_INCOMPLETA",

        mensagem:
          "O PDF possui movimentações que não foram reconhecidas. " +
          "A importação foi interrompida para evitar valores incorretos.",

        detalhes: [
          `Movimentações aparentes no PDF: ${quantidadeMovimentosAparentes}`,
          `Movimentações extraídas: ${movimentos.length}`,
          `Movimentações ignoradas: ${ignoradas.length}`
        ],

        conta_selecionada: {
          id: contaFinanceFlow.id,
          nome: contaFinanceFlow.nome,
          banco: contaFinanceFlow.banco,
          agencia: contaFinanceFlow.agencia,
          conta: contaFinanceFlow.conta
        },

        conta_arquivo: {
          banco: dadosArquivo.banco,
          agencia: dadosArquivo.agencia,
          conta: dadosArquivo.conta,
          titular:
            dadosArquivo.titular ||
            "Não identificado"
        },

        movimentos: [],
        quantidade: 0,

        diagnostico: {
          quantidade_aparente:
            quantidadeMovimentosAparentes,

          quantidade_extraida:
            movimentos.length,

          quantidade_ignorada:
            ignoradas.length
        }
      }
    }
  ];
}

/*
|--------------------------------------------------------------------------
| NENHUMA MOVIMENTAÇÃO
|--------------------------------------------------------------------------
*/

if (!movimentos.length) {
  return [
    {
      json: {
        ok: false,
        conta_validada: true,

        tipo_erro:
          "MOVIMENTOS_NAO_ENCONTRADOS",

        mensagem:
          "Nenhuma movimentação válida foi encontrada no extrato da XP.",

        detalhes: [
          "O banco e a conta foram validados, mas as linhas da tabela não foram reconhecidas."
        ],

        conta_selecionada: {
          id: contaFinanceFlow.id,
          nome: contaFinanceFlow.nome,
          banco: contaFinanceFlow.banco,
          agencia: contaFinanceFlow.agencia,
          conta: contaFinanceFlow.conta
        },

        conta_arquivo: {
          banco: dadosArquivo.banco,
          agencia: dadosArquivo.agencia,
          conta: dadosArquivo.conta,

          titular:
            dadosArquivo.titular ||
            "Não identificado"
        },

        movimentos: [],
        quantidade: 0,

        quantidade_ignoradas:
          ignoradas.length,

        linhas_ignoradas:
          ignoradas,

        diagnostico: {
          tamanho_texto:
            texto.length,

          tamanho_area_movimentos:
            textoPreparado.length,

          amostra:
            textoPreparado.substring(
              0,
              1000
            )
        }
      }
    }
  ];
}

/*
|--------------------------------------------------------------------------
| RETORNO DE SUCESSO
|--------------------------------------------------------------------------
*/

return [
  {
    json: {
      ok: true,
      conta_validada: true,

      empresa_id:
        contaFinanceFlow.empresa_id,

      conta_id:
        contaFinanceFlow.id,

      finalidade:
        entrada.finalidade ||
        entrada.body?.finalidade ||
        contaBanco.finalidade ||
        entrada.tipo_processamento ||
        "IMPORTACAO",

      banco: "XP",

      dados_conta_arquivo: {
        banco:
          dadosArquivo.banco,

        agencia:
          dadosArquivo.agencia,

        conta:
          dadosArquivo.conta,

        titular:
          dadosArquivo.titular
      },

      dados_conta_financeflow: {
        id:
          contaFinanceFlow.id,

        nome:
          contaFinanceFlow.nome,

        banco:
          contaFinanceFlow.banco,

        agencia:
          contaFinanceFlow.agencia,

        conta:
          contaFinanceFlow.conta
      },

      data_inicio:
        periodoInicio,

      data_fim:
        periodoFim,

      movimentos:
        movimentos.map((movimento) => ({
          data:
            movimento.data,

          horario:
            movimento.horario,

          historico:
            movimento.historico,

          valor:
            movimento.valor,

          tipo:
            movimento.tipo,

          saldo:
            movimento.saldo
        })),

      quantidade:
        movimentos.length,

      quantidade_ignoradas:
        ignoradas.length,

      linhas_ignoradas:
        ignoradas,

      diagnostico: {
        quantidade_registros:
          movimentos.length,

        primeiro_movimento:
          movimentos[0] || null,

        ultimo_movimento:
          movimentos[
            movimentos.length - 1
          ] || null
      }
    }
  }
];

