parameters.jsCode:
 /*
|--------------------------------------------------------------------------
| ENTRADAS
|--------------------------------------------------------------------------
*/

// PostgreSQL imediatamente anterior ao Code.
const contaBanco = $input.first()?.json || {};

// Node que extrai o texto do PDF Consumer.
const entrada = $("ExtractConsumer").first()?.json || {};

const texto = String(
  entrada.text ||
  entrada.texto_pdf ||
  entrada.data?.text ||
  entrada.data?.texto_pdf ||
  ""
);

const empresa_id =
  contaBanco.empresa_id ||
  entrada.empresa_id ||
  entrada.body?.empresa_id ||
  null;

const conta_id =
  contaBanco.id ||
  contaBanco.conta_id ||
  entrada.conta_id ||
  entrada.body?.conta_id ||
  null;

/*
|--------------------------------------------------------------------------
| FUNÇÕES AUXILIARES
|--------------------------------------------------------------------------
*/

function normalizarTexto(valor) {
  return String(valor || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function converterValorBR(valor) {
  const txt = String(valor || "")
    .trim()
    .replace(/\s/g, "")
    .replace(/\./g, "")
    .replace(",", ".");

  const numero = Number(txt);
  return Number.isFinite(numero) ? numero : 0;
}

function dataISO(dataBR) {
  const partes = String(dataBR || "").split("/");

  if (partes.length !== 3) return null;

  let [dia, mes, ano] = partes;

  if (ano.length === 2) {
    ano = `20${ano}`;
  }

  return (
    `${ano.padStart(4, "0")}-` +
    `${mes.padStart(2, "0")}-` +
    `${dia.padStart(2, "0")}`
  );
}

function normalizarFormaPagamento(formaPagamento) {
  const forma = normalizarTexto(formaPagamento).toUpperCase();

  if (
    forma.includes("CARTAO") &&
    forma.includes("CREDITO")
  ) {
    return "cartao_credito";
  }

  if (
    forma.includes("CARTAO") &&
    forma.includes("DEBITO")
  ) {
    return "cartao_debito";
  }

  if (forma.includes("CARTAO")) {
    return "cartao";
  }

  if (forma.includes("DINHEIRO")) {
    return "dinheiro";
  }

  if (forma.includes("PIX")) {
    return "pix";
  }

  return normalizarTexto(
    formaPagamento
  ).toLowerCase();
}

/*
|--------------------------------------------------------------------------
| DESCRIÇÃO DA FORMA NO HISTÓRICO
|--------------------------------------------------------------------------
*/

function descricaoFormaHistorico(formaPagamento) {
  const forma =
    normalizarFormaPagamento(
      formaPagamento
    );

  if (forma === "cartao_credito") {
    return "CARTAO CREDITO";
  }

  if (forma === "cartao_debito") {
    return "CARTAO DEBITO";
  }

  if (forma === "cartao") {
    return "CARTAO";
  }

  if (forma === "dinheiro") {
    return "DINHEIRO";
  }

  if (forma === "pix") {
    return "PIX";
  }

  return normalizarTexto(
    formaPagamento
  ).toUpperCase();
}

function ehFormaCartao(formaPagamento) {
  return normalizarTexto(
    formaPagamento
  )
    .toUpperCase()
    .includes("CARTAO");
}

function identificarEvento(
  descricao,
  formaPagamento
) {
  const desc =
    normalizarTexto(
      descricao
    ).toUpperCase();

  const forma =
    normalizarFormaPagamento(
      formaPagamento
    );

  if (
    desc.includes(
      "SALDO INICIAL"
    )
  ) {
    return "SALDO_INICIAL";
  }

  if (
    desc.includes(
      "SANGRIA"
    )
  ) {
    return "SANGRIA";
  }

  if (
    desc.includes(
      "RECEBIMENTO - FIADO"
    )
  ) {
    return "RECEBIMENTO_FIADO";
  }

  if (
    desc.includes(
      "ENTRADA - ACRESCIMO"
    )
  ) {
    return "ACRESCIMO_CAIXA";
  }

  if (
    desc.includes(
      "SAIDA - DESPESA"
    )
  ) {
    return "DESPESA_CAIXA";
  }

  const ehPedido =
    desc.includes("PEDIDO Nº") ||
    desc.includes("PEDIDO N°") ||
    desc.includes("PEDIDO N");

  if (
    ehPedido &&
    forma === "cartao_credito"
  ) {
    return "VENDA_CARTAO_CREDITO";
  }

  if (
    ehPedido &&
    forma === "cartao_debito"
  ) {
    return "VENDA_CARTAO_DEBITO";
  }

  if (
    ehPedido &&
    forma.startsWith("cartao")
  ) {
    return "VENDA_CARTAO";
  }

  if (ehPedido) {
    return "VENDA_DINHEIRO";
  }

  if (
    forma.startsWith("cartao")
  ) {
    return "RECEBIVEL_CARTAO";
  }

  return "MOVIMENTO_CAIXA";
}

function naturezaDoMovimento(
  eventoCodigo,
  formaPagamento
) {
  if (
    ehFormaCartao(
      formaPagamento
    ) ||
    String(
      eventoCodigo || ""
    ).startsWith(
      "VENDA_CARTAO"
    ) ||
    eventoCodigo ===
      "RECEBIVEL_CARTAO"
  ) {
    return "RECEBIVEL";
  }

  return "CAIXA";
}

/*
|--------------------------------------------------------------------------
| VALIDAÇÕES BÁSICAS
|--------------------------------------------------------------------------
*/

if (!texto.trim()) {
  return [
    {
      json: {
        ok: false,
        conta_validada: false,
        tipo_erro:
          "PDF_SEM_TEXTO",
        mensagem:
          "O PDF Consumer não retornou texto para processamento.",
        destino:
          "CONCILIACAO_FINANCEIRA",
      },
    },
  ];
}

if (!conta_id) {
  return [
    {
      json: {
        ok: false,
        conta_validada: false,
        tipo_erro:
          "CONTA_NAO_ENCONTRADA",
        mensagem:
          "A conta financeira selecionada não foi encontrada. Selecione uma conta Consumer vinculada ao banco 000.",
        destino:
          "CONCILIACAO_FINANCEIRA",
      },
    },
  ];
}

/*
|--------------------------------------------------------------------------
| VALIDAÇÃO DO BANCO 000
|--------------------------------------------------------------------------
*/

const codigoBanco =
  String(
    contaBanco.banco ??
    contaBanco.nro_banco ??
    contaBanco.codigo_banco ??
    contaBanco.banco_codigo ??
    ""
  ).trim();

const bancoEhConsumer =
  codigoBanco === "000";

if (!bancoEhConsumer) {
  return [
    {
      json: {
        ok: false,
        conta_validada: false,
        tipo_erro:
          "CONTA_NAO_E_CONSUMER",

        mensagem:
          "Este arquivo é um relatório do Consumer. Selecione uma conta financeira vinculada ao banco 000.",

        detalhes: [
          `Conta selecionada: ${
            contaBanco.nome ||
            contaBanco.conta_nome ||
            conta_id
          }`,

          `Banco selecionado: ${
            codigoBanco ||
            "não informado"
          }`,

          "Banco exigido: 000 - Caixa/Consumer da Empresa",
        ],

        conta_selecionada: {
          id: conta_id,

          nome:
            contaBanco.nome ||
            contaBanco.conta_nome ||
            "",

          banco:
            codigoBanco,

          agencia:
            contaBanco.agencia ||
            "",

          conta:
            contaBanco.conta ||
            contaBanco.numero_conta ||
            "",
        },

        destino:
          "CONCILIACAO_FINANCEIRA",
      },
    },
  ];
}

/*
|--------------------------------------------------------------------------
| PARSER DO PDF CONSUMER
|--------------------------------------------------------------------------
|
| Pode vir:
|
| - somente DINHEIRO
| - somente CARTÃO
| - DINHEIRO + CARTÃO
|
| Classificação feita linha a linha.
|--------------------------------------------------------------------------
*/

const linhasTexto =
  texto
    .replace(/\r/g, "")
    .split("\n")
    .map(
      (linha) =>
        linha.trim()
    )
    .filter(Boolean);

const movimentos = [];

let movimentoAtual = null;

let totalRelatorioEntrada =
  null;

let totalRelatorioSaida =
  null;

/*
|--------------------------------------------------------------------------
| REGEX
|--------------------------------------------------------------------------
|
| Exemplos:
|
| 01/08/26 22:24:30 Pedido nº 45409 (Mesa 15) 224,40 Cartão de Débito
| 03/06/26 19:38:19 Pedido nº 44328 (Mesa 2) 63,80 Dinheiro
| 14/06/26 14:36:26 Saída - Despesa 140,00 Dinheiro
|--------------------------------------------------------------------------
*/

 const regexMovimento =
  /^(\d{2}\/\d{2}\/\d{2,4})\s+(\d{2}:\d{2}:\d{1,2})\s+(.+?)\s+([\d.]+,\d{2})\s+(DINHEIRO|PIX|CARTAO.*|OUTRO.*)$/i;

const regexTotais =
  /^([\d.]+,\d{2})\s+([\d.]+,\d{2})$/;

/*
|--------------------------------------------------------------------------
| LEITURA DAS LINHAS
|--------------------------------------------------------------------------
*/

for (
  const linhaOriginal
  of linhasTexto
) {
  const linha =
    normalizarTexto(
      linhaOriginal
    );

  if (!linha) {
    continue;
  }

  /*
  |--------------------------------------------------------------------------
  | TOTAL DO RODAPÉ
  |--------------------------------------------------------------------------
  |
  | Exemplo:
  |
  | 5.326,82 0,00
  |--------------------------------------------------------------------------
  */

  const matchTotais =
    linha.match(
      regexTotais
    );

  if (matchTotais) {
    totalRelatorioEntrada =
      converterValorBR(
        matchTotais[1]
      );

    totalRelatorioSaida =
      converterValorBR(
        matchTotais[2]
      );

    continue;
  }

  /*
  |--------------------------------------------------------------------------
  | IGNORA CABEÇALHO
  |--------------------------------------------------------------------------
  */

  if (
    /^DATA\s*\/\s*HORA/i.test(
      linha
    ) ||
    /^DESCRICAO/i.test(
      linha
    ) ||
    /^ENTRADA\s+SAIDA/i.test(
      linha
    ) ||
    /^FORMA\s+PAGTO/i.test(
      linha
    )
  ) {
    continue;
  }

  const match =
    linha.match(
      regexMovimento
    );

  /*
  |--------------------------------------------------------------------------
  | MOVIMENTO
  |--------------------------------------------------------------------------
  */

  if (match) {
    const [
      ,
      data,
      hora,
      descricao,
      valorTexto,
      formaPagamentoTexto,
    ] = match;

    const formaPagamento =
      normalizarFormaPagamento(
        formaPagamentoTexto
      );

    /*
    |--------------------------------------------------------------------------
    | NOVO:
    | COLOCA A FORMA NO HISTÓRICO
    |--------------------------------------------------------------------------
    */

    const formaHistorico =
      descricaoFormaHistorico(
        formaPagamentoTexto
      );

    const historicoBase =
      [
        descricao.trim(),
        formaHistorico,
      ]
        .filter(Boolean)
        .join(" - ");

    /*
    |--------------------------------------------------------------------------
    | EVENTO
    |--------------------------------------------------------------------------
    */

    const evento_codigo =
      identificarEvento(
        descricao,
        formaPagamentoTexto
      );

    const natureza_financeira =
      naturezaDoMovimento(
        evento_codigo,
        formaPagamentoTexto
      );

    const valorNumero =
      converterValorBR(
        valorTexto
      );

    const ehSaida =
      evento_codigo ===
        "SANGRIA" ||
      evento_codigo ===
        "DESPESA_CAIXA" ||
      normalizarTexto(
        descricao
      )
        .toUpperCase()
        .startsWith(
          "SAIDA"
        );

    const valorFinal =
      ehSaida
        ? -Math.abs(
            valorNumero
          )
        : Math.abs(
            valorNumero
          );

    /*
    |--------------------------------------------------------------------------
    | OBJETO DO MOVIMENTO
    |--------------------------------------------------------------------------
    */

    movimentoAtual = {
      id_origem:
        null,

      empresa_id,

      conta_id,

      data:
        dataISO(data),

      data_mov:
        dataISO(data),

      data_movimento:
        dataISO(data),

      hora,

      /*
      |--------------------------------------------------------------------------
      | EXEMPLOS:
      |
      | Pedido nº 45412 (Delivery) - CARTAO CREDITO
      | Pedido nº 45413 (Delivery) - CARTAO DEBITO
      | Pedido nº 44328 (Mesa 2) - DINHEIRO
      |--------------------------------------------------------------------------
      */

      historico:
        historicoBase,

      descricao:
        historicoBase,

      complemento:
        "",

      tipo:
        ehSaida
          ? "saida"
          : "entrada",

      valor:
        valorFinal,

      forma:
        formaPagamento,

      forma_pagamento:
        formaPagamento,

      natureza_financeira,

      evento_codigo,

      classificacao:
        natureza_financeira ===
        "RECEBIVEL"
          ? "receita"
          : ehSaida
            ? "despesa"
            : "receita",

      origem:
        natureza_financeira ===
        "RECEBIVEL"
          ? "CONSUMER_CARTOES"
          : "CONSUMER_CAIXA",

      arquivo_tipo:
        "PDF_CONSUMER",
    };

    movimentos.push(
      movimentoAtual
    );

    continue;
  }

  /*
  |--------------------------------------------------------------------------
  | COMPLEMENTO DA LINHA ANTERIOR
  |--------------------------------------------------------------------------
  */

  if (movimentoAtual) {
    movimentoAtual.complemento =
      [
        movimentoAtual.complemento,
        linha,
      ]
        .filter(Boolean)
        .join(" ");

    movimentoAtual.descricao =
      [
        movimentoAtual.descricao,
        linha,
      ]
        .filter(Boolean)
        .join(" - ");

    movimentoAtual.historico =
      movimentoAtual.descricao;
  }
}

/*
|--------------------------------------------------------------------------
| VALIDAÇÃO DO PARSER
|--------------------------------------------------------------------------
*/

if (
  movimentos.length === 0
) {
  return [
    {
      json: {
        ok: false,

        conta_validada:
          true,

        tipo_erro:
          "NENHUM_MOVIMENTO_IDENTIFICADO",

        mensagem:
          "Nenhum movimento válido foi identificado no relatório Consumer.",

        conta_selecionada: {
          id:
            conta_id,

          nome:
            contaBanco.nome ||
            contaBanco.conta_nome ||
            "",

          banco:
            codigoBanco,

          agencia:
            contaBanco.agencia ||
            "",

          conta:
            contaBanco.conta ||
            "",
        },

        destino:
          "CONCILIACAO_FINANCEIRA",
      },
    },
  ];
}

/*
|--------------------------------------------------------------------------
| IDENTIFICA O CONTEÚDO DO ARQUIVO
|--------------------------------------------------------------------------
*/

const possuiCartao =
  movimentos.some(
    (item) =>
      item.natureza_financeira ===
      "RECEBIVEL"
  );

const possuiCaixa =
  movimentos.some(
    (item) =>
      item.natureza_financeira ===
        "CAIXA" &&
      item.evento_codigo !==
        "SALDO_INICIAL"
  );

const tipo_layout =
  possuiCartao &&
  possuiCaixa
    ? "CONSUMER_MISTO"
    : possuiCartao
      ? "CONSUMER_CARTOES"
      : "CONSUMER_CAIXA";

const origemArquivo =
  tipo_layout ===
  "CONSUMER_CARTOES"
    ? "CONSUMER_CARTOES"
    : tipo_layout ===
      "CONSUMER_MISTO"
      ? "CONSUMER_MISTO"
      : "CONSUMER_CAIXA";

/*
|--------------------------------------------------------------------------
| SALDO INICIAL DO CAIXA
|--------------------------------------------------------------------------
|
| Cartão NÃO altera o saldo físico.
|--------------------------------------------------------------------------
*/

const linhaSaldoInicial =
  movimentos.find(
    (item) =>
      item.evento_codigo ===
      "SALDO_INICIAL"
  );

const saldo_inicial =
  linhaSaldoInicial
    ? Math.abs(
        Number(
          linhaSaldoInicial.valor ||
          0
        )
      )
    : 0;

/*
|--------------------------------------------------------------------------
| REMOVE SALDO INICIAL
|--------------------------------------------------------------------------
*/

const itens =
  movimentos.filter(
    (item) =>
      item.evento_codigo !==
      "SALDO_INICIAL"
  );

/*
|--------------------------------------------------------------------------
| SEPARA CAIXA E RECEBÍVEIS
|--------------------------------------------------------------------------
*/

const itensCaixa =
  itens.filter(
    (item) =>
      item.natureza_financeira ===
      "CAIXA"
  );

const itensRecebiveis =
  itens.filter(
    (item) =>
      item.natureza_financeira ===
      "RECEBIVEL"
  );

/*
|--------------------------------------------------------------------------
| TOTAIS GERAIS
|--------------------------------------------------------------------------
*/

const entradasGerais =
  itens.reduce(
    (total, item) => {
      const valor =
        Number(
          item.valor || 0
        );

      return (
        total +
        (
          valor > 0
            ? valor
            : 0
        )
      );
    },
    0
  );

const saidasGerais =
  itens.reduce(
    (total, item) => {
      const valor =
        Number(
          item.valor || 0
        );

      return (
        total +
        (
          valor < 0
            ? Math.abs(
                valor
              )
            : 0
        )
      );
    },
    0
  );

/*
|--------------------------------------------------------------------------
| TOTAIS DO CAIXA
|--------------------------------------------------------------------------
*/

const entradasCaixa =
  itensCaixa.reduce(
    (total, item) => {
      const valor =
        Number(
          item.valor || 0
        );

      return (
        total +
        (
          valor > 0
            ? valor
            : 0
        )
      );
    },
    0
  );

const saidasCaixa =
  itensCaixa.reduce(
    (total, item) => {
      const valor =
        Number(
          item.valor || 0
        );

      return (
        total +
        (
          valor < 0
            ? Math.abs(
                valor
              )
            : 0
        )
      );
    },
    0
  );

/*
|--------------------------------------------------------------------------
| TOTAIS RECEBÍVEIS
|--------------------------------------------------------------------------
*/

const totalRecebiveis =
  itensRecebiveis.reduce(
    (total, item) =>
      total +
      Math.abs(
        Number(
          item.valor || 0
        )
      ),
    0
  );

const totalCartaoCredito =
  itensRecebiveis
    .filter(
      (item) =>
        item.forma_pagamento ===
        "cartao_credito"
    )
    .reduce(
      (total, item) =>
        total +
        Math.abs(
          Number(
            item.valor || 0
          )
        ),
      0
    );

const totalCartaoDebito =
  itensRecebiveis
    .filter(
      (item) =>
        item.forma_pagamento ===
        "cartao_debito"
    )
    .reduce(
      (total, item) =>
        total +
        Math.abs(
          Number(
            item.valor || 0
          )
        ),
      0
    );

/*
|--------------------------------------------------------------------------
| SALDO LINHA A LINHA
|--------------------------------------------------------------------------
|
| Somente CAIXA altera saldo.
|--------------------------------------------------------------------------
*/

let saldoAcumulado =
  saldo_inicial;

const itensComSaldo =
  itens.map(
    (item, indice) => {

      let saldoLinha =
        null;

      if (
        item.natureza_financeira ===
        "CAIXA"
      ) {
        saldoAcumulado +=
          Number(
            item.valor || 0
          );

        saldoLinha =
          Number(
            saldoAcumulado.toFixed(
              2
            )
          );
      }

      const ehRecebivel =
        item.natureza_financeira ===
        "RECEBIVEL";

      return {
        ...item,

        sequencia:
          indice + 1,

        saldo:
          saldoLinha,

        /*
        |--------------------------------------------------------------------------
        | NÃO EXECUTA NADA AQUI
        |--------------------------------------------------------------------------
        */

        contabilizar:
          false,

        gerar_transacao:
          !ehRecebivel,

        gerar_conta_receber:
          ehRecebivel,

        salvar_em:
          ehRecebivel
            ? "CONTAS_A_RECEBER"
            : "TRANSACOES",

        necessita_destino:
          item.evento_codigo ===
          "SANGRIA",

        observacao_sistema:
          item.evento_codigo ===
          "SANGRIA"
            ? "Selecionar a conta bancária de destino antes de processar."
            : ehRecebivel
              ? "Venda em cartão: gerar conta a receber. Não gerar transação financeira na venda."
              : null,
      };
    }
  );

/*
|--------------------------------------------------------------------------
| PERÍODO
|--------------------------------------------------------------------------
*/

const datasValidas =
  itensComSaldo
    .map(
      (item) =>
        item.data_movimento ||
        item.data
    )
    .filter(Boolean)
    .sort();

const data_inicio =
  datasValidas.length > 0
    ? datasValidas[0]
    : null;

const data_fim =
  datasValidas.length > 0
    ? datasValidas[
        datasValidas.length -
          1
      ]
    : null;

/*
|--------------------------------------------------------------------------
| DIAGNÓSTICO
|--------------------------------------------------------------------------
*/

const saldoAplicavel =
  possuiCaixa;

const saldo_calculado =
  saldoAplicavel
    ? Number(
        (
          Number(
            saldo_inicial || 0
          ) +
          Number(
            entradasCaixa || 0
          ) -
          Number(
            saidasCaixa || 0
          )
        ).toFixed(2)
      )
    : 0;

const saldo_final =
  saldoAplicavel
    ? saldo_calculado
    : 0;

const possuiTotaisRodape =
  Number.isFinite(
    totalRelatorioEntrada
  ) &&
  Number.isFinite(
    totalRelatorioSaida
  );

const diferencaEntrada =
  possuiTotaisRodape
    ? Number(
        (
          entradasGerais -
          totalRelatorioEntrada
        ).toFixed(2)
      )
    : 0;

const diferencaSaida =
  possuiTotaisRodape
    ? Number(
        (
          saidasGerais -
          totalRelatorioSaida
        ).toFixed(2)
      )
    : 0;

const diferencaTotais =
  Number(
    (
      Math.abs(
        diferencaEntrada
      ) +
      Math.abs(
        diferencaSaida
      )
    ).toFixed(2)
  );

const totaisConferem =
  !possuiTotaisRodape ||
  diferencaTotais <=
    0.01;

/*
|--------------------------------------------------------------------------
| CONTRATO PADRÃO DA TELA
|--------------------------------------------------------------------------
*/

const saldo_confere =
  totaisConferem;

const diferenca_saldo =
  diferencaTotais;

const criterioValidacao =
  tipo_layout ===
  "CONSUMER_CARTOES"
    ? possuiTotaisRodape
      ? "TOTAL_RECEBIVEIS_VS_TOTAL_RELATORIO"
      : "TOTALIZACAO_RECEBIVEIS"

    : tipo_layout ===
      "CONSUMER_MISTO"

      ? possuiTotaisRodape
        ? "SALDO_CAIXA_E_TOTALIZACAO_RECEBIVEIS"
        : "SALDO_CAIXA_E_RECEBIVEIS"

      : possuiTotaisRodape
        ? "TOTALIZACAO_CAIXA_VS_TOTAL_RELATORIO"
        : "TOTALIZACAO_INTERNA_CAIXA";

/*
|--------------------------------------------------------------------------
| PRIMEIRO MOVIMENTO
|--------------------------------------------------------------------------
*/

const primeiroMovimento =
  itensComSaldo.length > 0
    ? {
        data:
          itensComSaldo[0]
            .data_movimento ||
          itensComSaldo[0]
            .data,

        historico:
          itensComSaldo[0]
            .historico ||
          itensComSaldo[0]
            .descricao,

        valor:
          Number(
            itensComSaldo[0]
              .valor || 0
          ),

