// ================================================================
// HELPERS
// ================================================================

function texto(v) {
  if (v === null || v === undefined) return "";
  return String(v).trim();
}

function numero(v) {
  if (v === null || v === undefined || v === "") return 0;

  if (typeof v === "number") {
    return Number(v.toFixed(2));
  }

  let s = String(v)
    .trim()
    .replace(/\s/g, "")
    .replace(/R\$/gi, "");

  if (s.includes(",") && s.includes(".")) {
    s = s.replace(/\./g, "").replace(",", ".");
  } else if (s.includes(",")) {
    s = s.replace(",", ".");
  }

  const n = Number(s);

  return Number.isFinite(n)
    ? Number(n.toFixed(2))
    : 0;
}

function pad2(n) {
  return String(n).padStart(2, "0");
}

function dataISO(v) {
  if (!v) return null;

  const s = String(v).trim();

  // Excel serial
  if (/^\d{5}$/.test(s)) {
    const serial = Number(s);

    const utcDays = Math.floor(serial - 25569);
    const utcValue = utcDays * 86400;
    const d = new Date(utcValue * 1000);

    return [
      d.getUTCFullYear(),
      pad2(d.getUTCMonth() + 1),
      pad2(d.getUTCDate())
    ].join("-");
  }

  // dd/mm/yyyy
  let m = s.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);

  if (m) {
    return `${m[3]}-${m[2]}-${m[1]}`;
  }

  // yyyy-mm-dd
  m = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);

  if (m) {
    return s;
  }

  return null;
}

function dataHoraISO(v) {
  if (!v) return null;

  const s = String(v).trim();

  const m = s.match(
    /^(\d{2})\/(\d{2})\/(\d{4})\s+(\d{2}):(\d{2})(?::(\d{2}))?$/
  );

  if (!m) return null;

  return (
    `${m[3]}-${m[2]}-${m[1]}` +
    `T${m[4]}:${m[5]}:${m[6] || "00"}`
  );
}

function normalizarForma(v) {
  const s = texto(v)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");

  if (s.includes("debito")) return "cartao_debito";
  if (s.includes("credito")) return "cartao_credito";
  if (s.includes("pix")) return "pix";

  return s.replace(/\s+/g, "_") || null;
}

function soma(lista, campo) {
  return Number(
    lista.reduce(
      (acc, x) => acc + Number(x[campo] || 0),
      0
    ).toFixed(2)
  );
}

