    if (!cnpj) {
      const m = linha.match(/CNPJ:\s*([^\t]+)/i);

      if (m) {
        cnpj = m[1].trim();
      }
    }

    if (!dataInicioArquivo || !dataFimArquivo) {
      const m = linha.match(
        /Periodo:\s*(\d{2}\/\d{2}\/\d{4})\s+a\s+(\d{2}\/\d{2}\/\d{4})/i
      );

      if (m) {
        dataInicioArquivo = dataISO(m[1]);
        dataFimArquivo = dataISO(m[2]);
