  }
}

// ================================================================
// PARSER DE UMA ABA TABULADA
// ================================================================

function parseTabelaAba(linhasAba, primeiraColunaEsperada) {

  let cabecalho = null;
  let indiceCabecalho = -1;

  for (let i = 0; i < linhasAba.length; i++) {

    const colunas = linhasAba[i].split("\t");

    if (
      colunas.length > 1 &&
      texto(colunas[0]) === primeiraColunaEsperada
    ) {
      cabecalho = colunas.map(c => texto(c));
      indiceCabecalho = i;
      break;
    }
  }

  if (!cabecalho) {
    return [];
  }

  const registros = [];

  for (
    let i = indiceCabecalho + 1;
    i < linhasAba.length;
    i++
  ) {

    const linha = linhasAba[i];

    if (!texto(linha)) {
      continue;
    }

    if (
      linha.includes(
        "Não foram encontrados dados para o filtro solicitado."
      )
    ) {
      continue;
    }

    const valores = linha.split("\t");

    if (!texto(valores[0])) {
      continue;
    }

    const obj = {};

    for (
      let c = 0;
      c < cabecalho.length;
      c++
    ) {
      obj[cabecalho[c]] =
        valores[c] !== undefined
          ? valores[c]
          : "";
    }

    registros.push(obj);
  }

  return registros;
}

