    status:
      status || null,

    parcelas:
      Number(
        texto(r["PARCELAS"]) || 1
      ),

    autorizacao:
      autorizacao || null,

    comprovante_venda:
      cv || null,

    terminal:
      terminal || null,

    meio_captura:
      texto(
        r["MEIO DE CAPTURA"]
      ) || null,

    valor_bruto:
      bruto,

    valor_taxa:
      taxa,

    valor_liquido:
      liquido,

    chave_registro:
      chaveRegistro,

    conciliado:
      false,

    dados_origem:
      r
  });
}

// --------------------------------------------------------------
// PIX
// --------------------------------------------------------------

for (
  let idx = 0;
  idx < registrosPix.length;
  idx++
) {

  const r = registrosPix[idx];

  estabelecimento =
    estabelecimento ||
    texto(
      r["ESTABELECIMENTO COMERCIAL"]
    ) ||
    null;

  const dataHora =
    dataHoraISO(
      r["DATA/HORA DA VENDA"]
    );

  const bruto =
    numero(
      r["VALOR DA VENDA"]
    );

  const taxa =
    Math.abs(
      numero(
        r["VALOR TAXA"]
      )
    );

  const liquido =
    Number(
      (bruto - taxa).toFixed(2)
    );

  if (!dataHora || bruto === 0) {

    ignoradas.push({
      aba: "PIX",
      linha: idx + 1,
      motivo: "SEM_DATA_OU_VALOR",
      dados: r
    });

    continue;
  }

  const idTransacao =
    texto(
      r["ID/TRANSAÇÃO (ID)"]
    );

  const cv =
    texto(
      r["NÚMERO DO COMPROVANTE DE VENDAS (CV)"]
    );

  const chaveRegistro =
    idTransacao
      ? `GETNET|PIX|${idTransacao}`
      : [
          "GETNET",
          "PIX",
          estabelecimento || "",
          dataHora,
          cv,
          bruto.toFixed(2)
        ].join("|");

  movimentos.push({

    sequencia:
      movimentos.length + 1,

    empresa_id:
      empresaId,

    conta_id:
      contaId,

    operadora:
      "GETNET",

    tipo_movimento:
      "PIX",

    data_movimento:
      dataHora.substring(0, 10),

    data_hora_movimento:
      dataHora,

    data_prevista_pagamento:
      dataHora.substring(0, 10),

    estabelecimento,

    cnpj:
      texto(
        r["CPF / CNPJ"]
      ) || null,

    razao_social:
      texto(
        r["RAZÃO SOCIAL"]
      ) || razaoSocial,

    bandeira:
      null,

    modalidade:
      "PIX",

    forma_pagamento:
      "pix",

    status:
      texto(
        r["STATUS"]
      ) || null,

    parcelas:
      1,

    autorizacao:
      null,

    comprovante_venda:
      cv || null,

    transacao_origem:
      idTransacao || null,

    terminal:
      texto(
        r["NÚMERO DO TERMINAL"]
      ) || null,

    meio_captura:
      texto(
        r["MEIO DE CAPTURA"]
      ) || null,

    instituicao_bancaria:
      texto(
        r["INSTITUIÇÃO BANCÁRIA"]
      ) || null,

    valor_bruto:
      bruto,

    valor_taxa:
      taxa,

    valor_liquido:
      liquido,

    chave_registro:
      chaveRegistro,

    conciliado:
      false,

    dados_origem:
      r
  });
}

// ================================================================
// ORDENA
// ================================================================

movimentos.sort(
  (a, b) =>
    String(a.data_hora_movimento)
      .localeCompare(
        String(b.data_hora_movimento)
      )
);

movimentos.forEach(
  (m, idx) =>
    m.sequencia = idx + 1
);

// ================================================================
// DIAGNÓSTICO
// ================================================================

const cartoes =
  movimentos.filter(
    m =>
      m.tipo_movimento === "CARTAO"
  );

const pix =
  movimentos.filter(
    m =>
      m.tipo_movimento === "PIX"
  );

const credito =
  cartoes.filter(
    m =>
      m.forma_pagamento ===
      "cartao_credito"
  );

const debito =
  cartoes.filter(
    m =>
      m.forma_pagamento ===
      "cartao_debito"
  );

const aprovados =
  cartoes.filter(
    m =>
      String(m.status || "")
        .toUpperCase() ===
      "APROVADA"
  );

const negados =
  cartoes.filter(
    m =>
      String(m.status || "")
        .toUpperCase() ===
      "NEGADA"
  );

const pixPagos =
  pix.filter(
    m =>
      String(m.status || "")
        .toUpperCase() ===
      "PAGA"
  );

const pixNaoPagos =
  pix.filter(
    m =>
      String(m.status || "")
        .toUpperCase() !==
      "PAGA"
  );

const totalBruto =
  soma(
    movimentos,
    "valor_bruto"
  );

const totalTaxas =
  soma(
    movimentos,
    "valor_taxa"
  );

const totalLiquido =
  soma(
    movimentos,
    "valor_liquido"
  );

const chaves =
  movimentos.map(
    m =>
      m.chave_registro
  );

const duplicadas =
  chaves.filter(
    (chave, pos) =>
      chaves.indexOf(chave) !== pos
  );

const diagnostico = {

  arquivo_valido:
    movimentos.length > 0,

  operadora:
    "GETNET",

  empresa_id:
    empresaId,

  conta_id:
    contaId,

  razao_social:
    razaoSocial,

  cnpj,

  estabelecimento,

  data_inicio:
    dataInicioArquivo,

  data_fim:
    dataFimArquivo,

  abas_encontradas:
    Object.keys(abas),

  quantidade_linhas_texto:
    linhas.length,

  quantidade_cartoes_lidos:
    registrosCartao.length,

  quantidade_pix_lidos:
    registrosPix.length,

  quantidade_movimentos:
    movimentos.length,

  quantidade_ignoradas:
    ignoradas.length,

  quantidade_cartoes:
    cartoes.length,

  quantidade_credito:
    credito.length,

  quantidade_debito:
    debito.length,

  quantidade_cartoes_aprovados:
    aprovados.length,

  quantidade_cartoes_negados:
    negados.length,

  quantidade_pix:
    pix.length,

  quantidade_pix_pagos:
    pixPagos.length,

  quantidade_pix_nao_pagos:
    pixNaoPagos.length,

  total_bruto:
    totalBruto,

  total_taxas:
    totalTaxas,

  total_liquido:
    totalLiquido,

  total_credito_bruto:
    soma(
      credito,
      "valor_bruto"
    ),

  total_credito_taxas:
    soma(
      credito,
      "valor_taxa"
    ),

  total_credito_liquido:
    soma(
      credito,
      "valor_liquido"
    ),

  total_debito_bruto:
    soma(
      debito,
      "valor_bruto"
    ),

  total_debito_taxas:
    soma(
      debito,
      "valor_taxa"
    ),

  total_debito_liquido:
    soma(
      debito,
      "valor_liquido"
    ),

  total_pix_bruto:
    soma(
      pix,
      "valor_bruto"
    ),

  total_pix_taxas:
    soma(
      pix,
      "valor_taxa"
    ),

  total_pix_liquido:
    soma(
      pix,
      "valor_liquido"
    ),

  chaves_duplicadas:
    [...new Set(duplicadas)],

  quantidade_chaves_duplicadas:
    [...new Set(duplicadas)].length,

  confere_calculo:
    Math.abs(
      Number(
        (
          totalBruto -
          totalTaxas -
          totalLiquido
        ).toFixed(2)
      )
    ) <= 0.01,

  diferenca_calculo:
    Number(
      (
        totalBruto -
        totalTaxas -
        totalLiquido
      ).toFixed(2)
    ),

  linhas_ignoradas:
    ignoradas
};

// ================================================================
// RETORNO
// ================================================================

return [
  {
    json: {

      ok:
        diagnostico.arquivo_valido &&
        diagnostico
          .quantidade_chaves_duplicadas === 0,

      origem:
        "GETNET_TXT",

      tipo_importacao:
        "OPERADORA",

      mensagem:
        movimentos.length > 0
          ? "Arquivo Getnet processado com sucesso."
          : "Nenhum movimento Getnet válido encontrado.",

      diagnostico,

      movimentos
    }
  }
];

