parameters.jsCode:
 /*
|--------------------------------------------------------------------------
| ENTRADAS
|--------------------------------------------------------------------------
*/

// PostgreSQL imediatamente anterior ao Code
const contaBanco = $input.first().json;

// Node que extraiu o texto do PDF Santander
const entrada = $('ExtractSantander').first().json;

const texto = String(
  entrada.text ||
  entrada.texto_pdf ||
  entrada.data?.text ||
  entrada.data?.texto_pdf ||
  ""
);

if (!texto.trim()) {
  throw new Error(
    "O PDF não retornou texto para processamento."
  );
}


/*
|--------------------------------------------------------------------------
| CONTA CADASTRADA NO FINANCEFLOW
|--------------------------------------------------------------------------
*/

const contaFinanceFlow = {
  id:
    contaBanco.id ||
    contaBanco.conta_id,

  empresa_id:
    contaBanco.empresa_id ||
    entrada.empresa_id ||
    entrada.body?.empresa_id,

  nome:
    contaBanco.nome ||
    contaBanco.conta_nome ||
    "",

  banco:
    contaBanco.banco ||
    contaBanco.banco_nome ||
    "",

  agencia:
    contaBanco.agencia ||
    "",

  conta:
    contaBanco.conta ||
    contaBanco.numero_conta ||
    ""
};


if (!contaFinanceFlow.id) {
  throw new Error(
    "A conta financeira selecionada não foi encontrada no FinanceFlow."
  );
}

if (!contaFinanceFlow.banco) {
  throw new Error(
    "A conta selecionada não possui banco cadastrado no FinanceFlow."
  );
}

if (!contaFinanceFlow.agencia) {
  throw new Error(
    "A conta selecionada não possui agência cadastrada no FinanceFlow."
  );
}

if (!contaFinanceFlow.conta) {
  throw new Error(
    "A conta selecionada não possui número da conta cadastrada no FinanceFlow."
  );
}


/*
|--------------------------------------------------------------------------
| FUNÇÕES AUXILIARES
|--------------------------------------------------------------------------
*/

function normalizarTexto(valor) {
  return String(valor || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toUpperCase()
    .replace(/\s+/g, " ")
    .trim();
}


function somenteNumeros(valor) {
  const numeros = String(valor || "")
    .replace(/\D/g, "");

  return numeros.replace(/^0+/, "") || "0";
}


function normalizarBanco(valor) {
  const banco = normalizarTexto(valor);
  const codigo = somenteNumeros(valor);

  if (
    banco.includes("SANTANDER") ||
    codigo === "33"
  ) {
    return "SANTANDER";
  }

  return banco;
}


function converterValorBR(valor) {
  const textoValor = String(valor || "")
    .trim()
    .replace(/\s/g, "");

  const negativo =
    textoValor.startsWith("-");

  const numero = Number(
    textoValor
      .replace("-", "")
      .replace(/\./g, "")
      .replace(",", ".")
  );

  if (!Number.isFinite(numero)) {
    return 0;
  }

  return negativo
    ? numero * -1
    : numero;
}


function criarDataISO(ano, mes, dia) {
  return (
    `${String(ano).padStart(4, "0")}-` +
    `${String(mes).padStart(2, "0")}-` +
    `${String(dia).padStart(2, "0")}`
  );
}


function limparHistorico(valor) {
  return String(valor || "")
    .replace(/\s+/g, " ")
    .trim();
}


/*
|--------------------------------------------------------------------------
| IDENTIFICA O LAYOUT SANTANDER INTERNET BANKING
|--------------------------------------------------------------------------
*/

const textoNormalizado =
  normalizarTexto(texto);

const arquivoEhSantanderInternetBanking =
  textoNormalizado.includes("INTERNET BANKING") &&
  textoNormalizado.includes("EXTRATO DE CONTA CORRENTE") &&
  textoNormalizado.includes("AGENCIA E CONTA");


if (!arquivoEhSantanderInternetBanking) {
  return [
    {
      json: {
        ok: false,
        conta_validada: false,

        tipo_erro:
          "LAYOUT_SANTANDER_NAO_RECONHECIDO",

        mensagem:
          "O arquivo não foi identificado como extrato Santander Internet Banking.",

        detalhes: [
          "Este parser trata o layout Santander Internet Banking."
        ],

        conta_selecionada: {
          id: contaFinanceFlow.id,
          nome: contaFinanceFlow.nome,
          banco: contaFinanceFlow.banco,
          agencia: contaFinanceFlow.agencia,
          conta: contaFinanceFlow.conta
        },

        movimentos: [],
        quantidade: 0
      }
    }
  ];
}


/*
|--------------------------------------------------------------------------
| IDENTIFICA TITULAR, AGÊNCIA E CONTA
|--------------------------------------------------------------------------
|
| Exemplo:
|
| RINALDO VIANNA PIEDADE Agência e Conta: 0180 / 01019078-7
|--------------------------------------------------------------------------
*/

const cabecalhoContaMatch = texto.match(
  /(?:^|\n)\s*(.+?)\s+AG[EÊ]NCIA\s+E\s+CONTA\s*:\s*([0-9]+)\s*\/\s*([0-9.\-]+)/im
);


const titularArquivo =
  cabecalhoContaMatch
    ? cabecalhoContaMatch[1]
        .replace(/\s+/g, " ")
        .trim()
    : "";


const agenciaArquivo =
  cabecalhoContaMatch
    ? cabecalhoContaMatch[2].trim()
    : "";


const contaArquivo =
  cabecalhoContaMatch
    ? cabecalhoContaMatch[3].trim()
    : "";


const dadosArquivo = {
  banco: "SANTANDER",
  agencia: agenciaArquivo,
  conta: contaArquivo,
  titular: titularArquivo
};


/*
|--------------------------------------------------------------------------
| CONTA NÃO IDENTIFICADA
|--------------------------------------------------------------------------
*/

if (!contaArquivo) {
  return [
    {
      json: {
        ok: false,
        conta_validada: false,

        tipo_erro:
          "CONTA_NAO_IDENTIFICADA_NO_ARQUIVO",

        mensagem:
          "Não foi possível identificar o número da conta no extrato Santander.",

        detalhes: [
          "O PDF foi identificado como Santander, mas agência/conta não foram encontradas no cabeçalho."
        ],

        conta_selecionada: {
          id: contaFinanceFlow.id,
          nome: contaFinanceFlow.nome,
          banco: contaFinanceFlow.banco,
          agencia: contaFinanceFlow.agencia,
          conta: contaFinanceFlow.conta
        },

        conta_arquivo: {
          banco: "SANTANDER",
          agencia: agenciaArquivo,
          conta: "",
          titular:
            titularArquivo ||
            "Não identificado"
        },

        movimentos: [],
        quantidade: 0
      }
    }
  ];
}


/*
|--------------------------------------------------------------------------
| COMPARA BANCO, AGÊNCIA E CONTA
|--------------------------------------------------------------------------
*/

const bancoSistema =
  normalizarBanco(contaFinanceFlow.banco);

const bancoArquivo =
  normalizarBanco(dadosArquivo.banco);

const agenciaSistema =
  somenteNumeros(contaFinanceFlow.agencia);

const agenciaPdf =
  somenteNumeros(dadosArquivo.agencia);

const contaSistema =
  somenteNumeros(contaFinanceFlow.conta);

const contaPdf =
  somenteNumeros(dadosArquivo.conta);


const divergenciasConta = [];


if (
  bancoSistema &&
  bancoSistema !== bancoArquivo
) {
  divergenciasConta.push(
    `Banco selecionado: ${contaFinanceFlow.banco}; banco do arquivo: ${dadosArquivo.banco}`
  );
}


if (
  agenciaSistema &&
  agenciaPdf &&
  agenciaSistema !== agenciaPdf
) {
  divergenciasConta.push(
    `Agência selecionada: ${contaFinanceFlow.agencia}; agência do arquivo: ${dadosArquivo.agencia}`
  );
}


if (
  contaSistema &&
  contaPdf &&
  contaSistema !== contaPdf
) {
  divergenciasConta.push(
    `Conta selecionada: ${contaFinanceFlow.conta}; conta do arquivo: ${dadosArquivo.conta}`
  );
}


if (divergenciasConta.length > 0) {

  return [
    {
      json: {
        ok: false,
        conta_validada: false,

        tipo_erro:
          "CONTA_BANCARIA_INCORRETA",

        mensagem:
          "O extrato enviado não pertence à conta selecionada. " +
          "Selecione a conta correta e importe novamente.",

        detalhes:
          divergenciasConta,

        conta_selecionada: {
          id: contaFinanceFlow.id,
          nome: contaFinanceFlow.nome,
          banco: contaFinanceFlow.banco,
          agencia: contaFinanceFlow.agencia,
          conta: contaFinanceFlow.conta
        },

        conta_arquivo: {
          banco: dadosArquivo.banco,
          agencia: dadosArquivo.agencia,
          conta: dadosArquivo.conta,
          titular:
            dadosArquivo.titular ||
            "Não identificado"
        },

        movimentos: [],
        quantidade: 0
      }
    }
  ];
}


/*
|--------------------------------------------------------------------------
| PERÍODO DO EXTRATO
|--------------------------------------------------------------------------
|
| Exemplo:
|
| Período: 01/07/2026 a 31/07/2026
|--------------------------------------------------------------------------
*/

const textoPeriodo = String(texto || "")
  .normalize("NFD")
  .replace(/[\u0300-\u036f]/g, "")
  .replace(/\r/g, " ")
  .replace(/\n/g, " ")
  .replace(/\s+/g, " ")
  .trim();


const periodoMatch = textoPeriodo.match(
  /PERIODO\s*:\s*(\d{1,2})\/(\d{1,2})\/(\d{4})\s*(?:A|ATE|-)\s*(\d{1,2})\/(\d{1,2})\/(\d{4})/i
);


let dataInicio = "";
let dataFim = "";


if (periodoMatch) {

  dataInicio = criarDataISO(
    periodoMatch[3],
    periodoMatch[2],
    periodoMatch[1]
  );

  dataFim = criarDataISO(
    periodoMatch[6],
    periodoMatch[5],
    periodoMatch[4]
  );
}


if (!dataInicio || !dataFim) {

  return [
    {
      json: {
        ok: false,
        conta_validada: true,

        tipo_erro:
          "PERIODO_NAO_IDENTIFICADO",

        mensagem:
          "Não foi possível identificar o período do extrato Santander.",

        detalhes: [
          "A conta foi validada, mas o período do extrato não foi localizado."
        ],

        conta_selecionada: {
          id: contaFinanceFlow.id,
          nome: contaFinanceFlow.nome,
          banco: contaFinanceFlow.banco,
          agencia: contaFinanceFlow.agencia,
          conta: contaFinanceFlow.conta
        },

        conta_arquivo: {
          banco: dadosArquivo.banco,
          agencia: dadosArquivo.agencia,
          conta: dadosArquivo.conta,
          titular:
            dadosArquivo.titular ||
            "Não identificado"
        },

        movimentos: [],
        quantidade: 0
      }
    }
  ];
}


/*
|--------------------------------------------------------------------------
| PREPARA AS LINHAS DO PDF
|--------------------------------------------------------------------------
*/

const linhasOriginais = texto
  .replace(/\r/g, "")
  .split("\n")
  .map((linha) =>
    linha
      .replace(/\u00A0/g, " ")
      .replace(/\s+/g, " ")
      .trim()
  )
  .filter(Boolean);


/*
|--------------------------------------------------------------------------
| LINHAS QUE NÃO SÃO MOVIMENTAÇÃO
|--------------------------------------------------------------------------
*/

function ignorarLinhaGeral(linha) {

  const txt =
    normalizarTexto(linha);

  return (

    txt === "INTERNET BANKING" ||

    txt === "EXTRATO DE CONTA CORRENTE" ||

    txt.startsWith("DATA DESCRICAO") ||

    txt.startsWith("PERIODO:") ||

    txt.startsWith("SALDO ANTERIOR") ||

    txt === "DATA" ||

    txt === "SALDO (R$)" ||

    txt.startsWith("SALDO DE CONTA CORRENTE") ||

    txt.startsWith("SALDO BLOQUEADO") ||

    txt.startsWith("PROVISAO DE ENCARGOS") ||

    txt.startsWith("JUROS ACUMULADOS") ||

    txt.startsWith("IOF ACUMULADOS") ||

    txt.startsWith("SEGURO DO LIMITE") ||

    txt.startsWith("SALDO DISPONIVEL") ||

    txt.startsWith("LIMITE DA CONTA") ||

    txt.startsWith("SALDO EM CONTA + LIMITE") ||

    txt.startsWith("JUROS CALCULADOS") ||

    txt.startsWith("SALDO DE CONTA EM") ||

    txt.startsWith("ULTIMO MOVIMENTO") ||

    txt.startsWith("DATA PARA DEBITO") ||

    txt.startsWith("CENTRAL DE ATENDIMENTO") ||

    txt.startsWith("CAPITAIS E REGIOES") ||

    txt.startsWith("DEMAIS LOCALIDADES") ||

    txt.startsWith("PESSOAS COM DEFICIENCIA") ||

    txt.startsWith("TODAS AS REGIOES") ||

    txt.startsWith("SE NAO FICAR SATISFEITO") ||

    txt.startsWith("DISPONIVEL DAS") ||

    /^[0-9]+\/[0-9]+$/.test(txt)
  );
}


/*
|--------------------------------------------------------------------------
| VALOR BRASILEIRO
|--------------------------------------------------------------------------
*/

const padraoValor =
  "-?\\d{1,3}(?:\\.\\d{3})*,-?\\d{2}|-?\\d+,\\d{2}";


/*
|--------------------------------------------------------------------------
| MOVIMENTO COMPLETO
|--------------------------------------------------------------------------
|
| Todo movimento termina em:
|
| VALOR    SALDO
|
| Exemplo:
|
| PIX ENVIADO ... 000000 -40,00 -21.030,39
|
|--------------------------------------------------------------------------
*/

const regexFinalMovimento = new RegExp(
  `(${padraoValor})\\s+(${padraoValor})$`,
  "i"
);


function blocoEstaCompleto(bloco) {

  return (
    /^\d{2}\/\d{2}\/\d{4}\s+.+/.test(bloco) &&
    regexFinalMovimento.test(bloco)
  );
}


/*
|--------------------------------------------------------------------------
| AGRUPA MOVIMENTOS QUE QUEBRARAM EM MAIS DE UMA LINHA
|--------------------------------------------------------------------------
*/

const blocos = [];
const linhasSoltas = [];

let blocoAtual = "";


for (const linha of linhasOriginais) {

  if (ignorarLinhaGeral(linha)) {
    continue;
  }


  /*
  |--------------------------------------------------------------------------
  | Só consideramos início de movimento se existir:
  |
  | DATA + ALGUM CONTEÚDO
  |
  | Isso evita interpretar a data isolada do "Saldo anterior"
  | ou das telas de resumo como movimento.
  |--------------------------------------------------------------------------
  */

  const iniciaMovimento =
    /^\d{2}\/\d{2}\/\d{4}\s+.+/.test(linha);


  if (iniciaMovimento) {

    if (blocoAtual) {

      if (blocoEstaCompleto(blocoAtual)) {

        blocos.push(blocoAtual);

      } else {

        linhasSoltas.push({
          linha: blocoAtual,
          motivo:
            "BLOCO_INCOMPLETO_ANTES_DE_NOVA_DATA"
        });
      }
    }

    blocoAtual = linha;

  } else if (blocoAtual) {

    /*
    |--------------------------------------------------------------------------
    | Se o movimento já terminou com VALOR + SALDO,
    | não anexamos mais nenhuma linha.
    |--------------------------------------------------------------------------
    */

    if (blocoEstaCompleto(blocoAtual)) {

      blocos.push(blocoAtual);

      blocoAtual = "";

    } else {

      blocoAtual += ` ${linha}`;
    }
  }
}


/*
|--------------------------------------------------------------------------
| ÚLTIMO BLOCO
|--------------------------------------------------------------------------
*/

if (blocoAtual) {

  if (blocoEstaCompleto(blocoAtual)) {

    blocos.push(blocoAtual);

  } else {

    linhasSoltas.push({
      linha: blocoAtual,
      motivo:
        "ULTIMO_BLOCO_INCOMPLETO"
    });
  }
}


/*
|--------------------------------------------------------------------------
| EXTRAÇÃO DOS MOVIMENTOS
|--------------------------------------------------------------------------
*/

const movimentosInternos = [];

const ignoradas =
  [...linhasSoltas];


const regexMovimento = new RegExp(
  `^(\\d{2})\\/(\\d{2})\\/(\\d{4})\\s+(.+?)\\s+(${padraoValor})\\s+(${padraoValor})$`,
  "i"
);


for (const bloco of blocos) {

  const match =
    bloco.match(regexMovimento);


  if (!match) {

    ignoradas.push({
      linha: bloco,
      motivo:
        "FORMATO_NAO_RECONHECIDO"
    });

    continue;
  }


  const data =
    criarDataISO(
      match[3],
      match[2],
      match[1]
    );


  let parteHistorico =
    match[4]
      .replace(/\s+/g, " ")
      .trim();


  const valorMovimento =
    converterValorBR(
      match[5]
    );


  const saldoAposMovimento =
    converterValorBR(
      match[6]
    );


  /*
  |--------------------------------------------------------------------------
  | REMOVE DOCUMENTO FINAL
  |--------------------------------------------------------------------------
  |
  | Exemplos:
  |
  | PIX ENVIADO Fulano 000000
  | PAGAMENTO ... 000000
  | TRANSFERENCIA ... 251732
  |
  | O documento não precisa fazer parte do histórico.
  |--------------------------------------------------------------------------
  */

  let documento = "";


  const documentoMatch =
    parteHistorico.match(
      /^(.*?)\s+(\d{6,12})$/
    );


  if (documentoMatch) {

    parteHistorico =
      documentoMatch[1].trim();

    documento =
      documentoMatch[2].trim();
  }


  const historico =
    limparHistorico(
      parteHistorico
    );


  /*
  |--------------------------------------------------------------------------
  | NATUREZA FINANCEIRA
  |--------------------------------------------------------------------------
  |
  | Mantemos a mesma lógica do Santander PJ:
  | crédito GETNET = pagamento_operadora
  |--------------------------------------------------------------------------
  */

  const natureza_movimento =
    valorMovimento > 0 &&
    normalizarTexto(historico).includes("GETNET")
      ? "pagamento_operadora"
      : null;


  /*
  |--------------------------------------------------------------------------
  | VALIDA PERÍODO
  |--------------------------------------------------------------------------
  */

  if (
    data < dataInicio ||
    data > dataFim
  ) {

    ignoradas.push({
      linha: bloco,
      motivo:
        "DATA_FORA_DO_PERIODO"
    });

    continue;
  }


  /*
  |--------------------------------------------------------------------------
  | MOVIMENTO INVÁLIDO
  |--------------------------------------------------------------------------
  */

  if (
    !historico ||
    valorMovimento === 0
  ) {

    ignoradas.push({
      linha: bloco,
      motivo:
        "MOVIMENTO_INVALIDO"
    });

    continue;
  }


  movimentosInternos.push({

    data,

    historico,

    documento,

    valor:
      Math.abs(valorMovimento),

    valor_assinado:
      valorMovimento,

    tipo:
      valorMovimento < 0
        ? "D"
        : "C",

    saldo:
      saldoAposMovimento,

    natureza_financeira:
      natureza_movimento
  });
}


/*
|--------------------------------------------------------------------------
| RETORNO SEM VALOR_ASSINADO
|--------------------------------------------------------------------------
*/

const movimentos =
  movimentosInternos.map(
    ({
      valor_assinado,
      ...movimento
    }) => movimento
  );


/*
|--------------------------------------------------------------------------
| NENHUM MOVIMENTO
|--------------------------------------------------------------------------
*/

if (!movimentos.length) {

  return [
    {
      json: {

        ok: false,

        conta_validada: true,

        tipo_erro:
          "MOVIMENTOS_NAO_ENCONTRADOS",

        mensagem:
          "Nenhuma movimentação válida foi encontrada no extrato Santander.",

        detalhes: [
          "O banco e a conta foram validados, mas o formato das movimentações não foi reconhecido."
        ],

        conta_selecionada: {
          id: contaFinanceFlow.id,
          nome: contaFinanceFlow.nome,
          banco: contaFinanceFlow.banco,
          agencia: contaFinanceFlow.agencia,
          conta: contaFinanceFlow.conta
        },

        conta_arquivo: {
          banco: dadosArquivo.banco,
          agencia: dadosArquivo.agencia,
          conta: dadosArquivo.conta,
          titular:
            dadosArquivo.titular ||
            "Não identificado"
        },

        movimentos: [],

        quantidade: 0,

        quantidade_ignoradas:
          ignoradas.length,

        linhas_ignoradas:
          ignoradas
      }
    }
  ];
}


/*
|--------------------------------------------------------------------------
| TOTAIS E SALDOS
|--------------------------------------------------------------------------
|
| O arquivo vem em ordem decrescente:
|
| primeiro movimento = mais recente
| último movimento   = mais antigo
|
|--------------------------------------------------------------------------
*/

const movimentoMaisRecente =
  movimentosInternos[0];


const movimentoMaisAntigo =
  movimentosInternos[
    movimentosInternos.length - 1
  ];


/*
|--------------------------------------------------------------------------
| SALDO FINAL
|--------------------------------------------------------------------------
*/

const saldoFinal =
  movimentoMaisRecente.saldo;


/*
|--------------------------------------------------------------------------
| SALDO INICIAL
|--------------------------------------------------------------------------
|
| Exemplo do arquivo:
|
| movimento mais antigo:
| +4.000,00
|
| saldo depois dele:
| -16.538,45
|
| saldo anterior:
|
| -16.538,45 - 4.000,00
| =
| -20.538,45
|--------------------------------------------------------------------------
*/

const saldoInicial =
  movimentoMaisAntigo.saldo -
  movimentoMaisAntigo.valor_assinado;


/*
|--------------------------------------------------------------------------
| TOTAIS
|--------------------------------------------------------------------------
*/

const totalCreditos =
  movimentos
    .filter(
      movimento =>
        movimento.tipo === "C"
    )
    .reduce(
      (total, movimento) =>
        total + movimento.valor,
      0
    );


const totalDebitos =
  movimentos
    .filter(
      movimento =>
        movimento.tipo === "D"
    )
    .reduce(
      (total, movimento) =>
        total + movimento.valor,
      0
    );


const saldoCalculado =
  saldoInicial +
  totalCreditos -
  totalDebitos;


const diferencaSaldo =
  saldoCalculado -
  saldoFinal;


const saldoConfere =
  Math.abs(diferencaSaldo) <= 0.01;


/*
|--------------------------------------------------------------------------
| RETORNO FINAL
|--------------------------------------------------------------------------
*/

return [
  {
    json: {

      ok: true,

      conta_validada: true,

      empresa_id:
        contaFinanceFlow.empresa_id,

      conta_id:
        contaFinanceFlow.id,

      finalidade:
        entrada.finalidade ||
        entrada.body?.finalidade ||
        contaBanco.finalidade ||
        "IMPORTACAO",

      banco:
        "SANTANDER",


      dados_conta_arquivo: {

        banco:
          dadosArquivo.banco,

        agencia:
          dadosArquivo.agencia,

        conta:
          dadosArquivo.conta,

        titular:
          dadosArquivo.titular
      },


      dados_conta_financeflow: {

        id:
          contaFinanceFlow.id,

        nome:
          contaFinanceFlow.nome,

        banco:
          contaFinanceFlow.banco,

        agencia:
          contaFinanceFlow.agencia,

        conta:
          contaFinanceFlow.conta
      },


      data_inicio:
        dataInicio,

      data_fim:
        dataFim,


      movimentos,


      quantidade:
        movimentos.length,


      quantidade_ignoradas:
        ignoradas.length,


      linhas_ignoradas:
        ignoradas,


      diagnostico: {

        tipo_layout:
          "SANTANDER_INTERNET_BANKING",

        quantidade_linhas:
          linhasOriginais.length,

        quantidade_blocos:
          blocos.length,

        quantidade_creditos:
          movimentos.filter(
            movimento =>
              movimento.tipo === "C"
          ).length,

        quantidade_debitos:
          movimentos.filter(
            movimento =>
              movimento.tipo === "D"
          ).length,

        total_creditos:
          Number(
            totalCreditos.toFixed(2)
          ),

        total_debitos:
          Number(
            totalDebitos.toFixed(2)
          ),

        saldo_inicial:
          Number(
            saldoInicial.toFixed(2)
          ),

        saldo_final:
          Number(
            saldoFinal.toFixed(2)
          ),

        saldo_calculado:
          Number(
            saldoCalculado.toFixed(2)
          ),

        diferenca_saldo:
          Number(
            diferencaSaldo.toFixed(2)
          ),

        saldo_confere:
          saldoConfere,

        primeiro_movimento:
          movimentos[0] || null,

        ultimo_movimento:
          movimentos[
            movimentos.length - 1
          ] || null
      }
    }
  }
];

 /*
|--------------------------------------------------------------------------
| ENTRADAS
|--------------------------------------------------------------------------
*/

// PostgreSQL imediatamente anterior ao Code
const contaBanco = $input.first().json;

// Mesmo padrão do seu fluxo atual
const entrada = $('EditHistorico').first().json;

const texto = String(
  entrada.texto_pdf ||
  entrada.text ||
  ""
);

if (!texto.trim()) {
  throw new Error(
    "O PDF não retornou texto para processamento."
  );
}


/*
|--------------------------------------------------------------------------
| FUNÇÕES AUXILIARES
|--------------------------------------------------------------------------
*/

function normalizarTexto(valor) {
  return String(valor || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toUpperCase()
    .replace(/\s+/g, " ")
    .trim();
}


function somenteNumeros(valor) {
  return String(valor || "")
    .replace(/\D/g, "")
    .replace(/^0+/, "");
}


function converterValorBR(valor) {
  const textoValor = String(valor || "")
    .replace(/\s/g, "")
    .trim();

  const numero = Number(
    textoValor
      .replace(/\./g, "")
      .replace(",", ".")
  );

  return Number.isFinite(numero)
    ? numero
    : 0;
}


/*
|--------------------------------------------------------------------------
| DADOS DA CONTA SELECIONADA
|--------------------------------------------------------------------------
*/

const contaSelecionada = {

  id:
    contaBanco.id ||
    contaBanco.conta_id ||
    entrada.conta_id ||
    null,

  empresa_id:
    contaBanco.empresa_id ||
    entrada.empresa_id ||
    entrada.body?.empresa_id ||
    null,

  nome:
    contaBanco.nome ||
    contaBanco.conta_nome ||
    "",

  banco:
    contaBanco.banco ||
    contaBanco.banco_nome ||
    "",

  agencia:
    contaBanco.agencia ||
    "",

  conta:
    contaBanco.conta ||
    contaBanco.numero_conta ||
    ""
};


if (!contaSelecionada.id) {
  throw new Error(
    "A conta financeira selecionada não foi encontrada."
  );
}


if (!contaSelecionada.banco) {
  throw new Error(
    "A conta selecionada não possui banco cadastrado."
  );
}


/*
|--------------------------------------------------------------------------
| NORMALIZA TEXTO
|--------------------------------------------------------------------------
|
| Esse Santander PF vem praticamente todo achatado.
|--------------------------------------------------------------------------
*/

const textoLimpo = texto
  .replace(/\r/g, " ")
  .replace(/\n/g, " ")
  .replace(/\u00A0/g, " ")
  .replace(/\s+/g, " ")
  .trim();


const textoNormalizado =
  normalizarTexto(textoLimpo);


/*
|--------------------------------------------------------------------------
| VALIDA LAYOUT SANTANDER PF
|--------------------------------------------------------------------------
*/

const ehSantanderPF =
  textoNormalizado.includes(
    "INTERNET BANKING"
  ) &&
  textoNormalizado.includes(
    "EXTRATO DE CONTA CORRENTE"
  ) &&
  textoNormalizado.includes(
    "AGENCIA E CONTA"
  );


if (!ehSantanderPF) {

  return [
    {
      json: {

        ok: false,

        conta_validada: false,

        tipo_erro:
          "BANCO_DO_ARQUIVO_NAO_IDENTIFICADO",

        mensagem:
          "Não foi possível identificar o arquivo como Santander PF.",

        conta_selecionada: {

          id:
            contaSelecionada.id,

          nome:
            contaSelecionada.nome,

          banco:
            contaSelecionada.banco,

          agencia:
            contaSelecionada.agencia,

          conta:
            contaSelecionada.conta
        },

        conta_arquivo: {
          banco:
            "NÃO IDENTIFICADO"
        },

        movimentos: [],

        quantidade: 0
      }
    }
  ];
}


/*
|--------------------------------------------------------------------------
| QUEBRA EM PARTES
|--------------------------------------------------------------------------
|
| Mesmo conceito usado no Santander atual:
|
| cada DD/MM/AAAA inicia uma nova parte.
|--------------------------------------------------------------------------
*/

const partes = textoLimpo
  .split(
    /(?=\d{2}\/\d{2}\/\d{4}\s+)/
  )
  .map(item =>
    String(item || "")
      .replace(/\s+/g, " ")
      .trim()
  )
  .filter(Boolean);


/*
|--------------------------------------------------------------------------
| REGEX MOVIMENTO
|--------------------------------------------------------------------------
|
| Exemplos:
|
| 29/07/2026 PAGAMENTO ... 000000 -148,52 -21.868,31
|
| 28/07/2026 PIX RECEBIDO ... 000000 4.000,00 -20.990,39
|--------------------------------------------------------------------------
*/

const regexSantander =
  /^(\d{2}\/\d{2}\/\d{4})\s+(.+?)\s+(-?\d{1,3}(?:\.\d{3})*,-?\d{2}|-?\d+,\d{2})\s+(-?\d{1,3}(?:\.\d{3})*,-?\d{2}|-?\d+,\d{2})(?:\s|$)/;


const movimentos = [];
const partesIgnoradas = [];


/*
|--------------------------------------------------------------------------
| PROCESSA PARTES
|--------------------------------------------------------------------------
*/

for (const parte of partes) {

  const match =
    parte.match(regexSantander);


  /*
  |--------------------------------------------------------------------------
  | PARTE NÃO É MOVIMENTO
  |--------------------------------------------------------------------------
  */

  if (!match) {

    partesIgnoradas.push({

      linha:
        parte,

      motivo:
        "FORMATO_NAO_RECONHECIDO"
    });

    continue;
  }


  /*
  |--------------------------------------------------------------------------
  | DATA
  |--------------------------------------------------------------------------
  |
  | Mantemos exatamente o formato do parser atual:
  |
  | DD/MM/YYYY
  |--------------------------------------------------------------------------
  */

  const data =
    match[1];


  /*
  |--------------------------------------------------------------------------
  | HISTÓRICO
  |--------------------------------------------------------------------------
  */

  let historico = String(
    match[2] || ""
  )
    .replace(/\s+/g, " ")
    .trim();


  /*
  |--------------------------------------------------------------------------
  | VALOR / SALDO
  |--------------------------------------------------------------------------
  */

  const valorAssinado =
    converterValorBR(
      match[3]
    );


  const saldo =
    converterValorBR(
      match[4]
    );


  const historicoNormalizado =
    normalizarTexto(
      historico
    );


  /*
  |--------------------------------------------------------------------------
  | IGNORA PARTES QUE NÃO SÃO LANÇAMENTO
  |--------------------------------------------------------------------------
  |
  | Por causa do split por data também aparecem:
  |
  | Período
  | Saldo anterior
  | Saldo de conta em
  | Último movimento
  |--------------------------------------------------------------------------
  */

  if (
    historicoNormalizado.includes(
      "DATA DESCRICAO DOCTO"
    ) ||

    historicoNormalizado.includes(
      "SALDO ANTERIOR"
    ) ||

    historicoNormalizado.includes(
      "SALDO DE CONTA CORRENTE"
    ) ||

    historicoNormalizado.includes(
      "SALDO BLOQUEADO"
    ) ||

    historicoNormalizado.includes(
      "SALDO DISPONIVEL"
    ) ||

    historicoNormalizado.includes(
      "ULTIMO MOVIMENTO"
    ) ||

    historicoNormalizado.includes(
      "CENTRAL DE ATENDIMENTO"
    )
  ) {

    partesIgnoradas.push({

      linha:
        parte,

      motivo:
        "FORMATO_NAO_RECONHECIDO"
    });

    continue;
  }


  /*
  |--------------------------------------------------------------------------
  | REMOVE DOCUMENTO DO FINAL DO HISTÓRICO
  |--------------------------------------------------------------------------
  |
  | Exemplo:
  |
  | PIX ENVIADO Leandro Sabino da Silva 000000
  |
  | vira:
  |
  | PIX ENVIADO Leandro Sabino da Silva
  |--------------------------------------------------------------------------
  */

  const documentoFinal =
    historico.match(
      /^(.*?)\s+\d{6,12}$/
    );


  if (documentoFinal) {

    historico =
      documentoFinal[1]
        .replace(/\s+/g, " ")
        .trim();
  }


  /*
  |--------------------------------------------------------------------------
  | VALIDA MOVIMENTO
  |--------------------------------------------------------------------------
  */

  if (
    !data ||
    !historico ||
    valorAssinado === 0
  ) {

    partesIgnoradas.push({

      linha:
        parte,

      motivo:
        "MOVIMENTO_INVALIDO"
    });

    continue;
  }


  /*
  |--------------------------------------------------------------------------
  | MOVIMENTO
  |--------------------------------------------------------------------------
  |
  | EXATAMENTE O MESMO CONTRATO DO CÓDIGO EXISTENTE
  |--------------------------------------------------------------------------
  */

  movimentos.push({

    data,

    historico,

    valor:
      Math.abs(
        valorAssinado
      ),

    tipo:
      valorAssinado < 0
        ? "D"
        : "C",

    saldo
  });
}


/*
|--------------------------------------------------------------------------
| RETORNO
|--------------------------------------------------------------------------
|
| MESMA ESTRUTURA DO SEU CÓDIGO ATUAL
|--------------------------------------------------------------------------
*/

return [
  {
    json: {

      ok: true,

      conta_validada: true,

      empresa_id:
        contaSelecionada.empresa_id,

      conta_id:
        contaSelecionada.id,

      data_inicio:
        entrada.data_inicio ||
        entrada.body?.data_inicio ||
        contaBanco.data_inicio ||
        null,

      data_fim:
        entrada.data_fim ||
        entrada.body?.data_fim ||
        contaBanco.data_fim ||
        null,

      banco:
        "SANTANDER",

      conta_selecionada: {

        id:
          contaSelecionada.id,

        nome:
          contaSelecionada.nome,

        banco:
          contaSelecionada.banco,

        agencia:
          contaSelecionada.agencia,

        conta:
          contaSelecionada.conta
      },

      movimentos,

      quantidade:
        movimentos.length,

      quantidade_ignoradas:
        partesIgnoradas.length,

      linhas_ignoradas:
        partesIgnoradas,

      teste_primeira_linha:
        partes[0] ||
        null,

      teste_quantidade_partes:
        partes.length
    }
  }
];

   /*
