/*
 * ============================================================
 * FUNÇÕES AUXILIARES
 * ============================================================
 */

function numeroBR(valor) {
  return (
    Number(
      String(valor || "")
        .replace(/\./g, "")
        .replace(",", ".")
    ) || 0
  );
}

function normalizarTexto(valor) {
  return String(valor || "")
    .replace(/\r/g, "\n")
    .replace(/\u00a0/g, " ")
    .replace(/[ \t]+/g, " ")
    .trim();
}

function somenteNumeros(valor) {
  const numeros = String(valor || "")
    .replace(/\D/g, "");

  return numeros.replace(/^0+/, "") || "0";
}

function normalizarBanco(valor) {
  const banco = String(valor || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toUpperCase()
    .trim();

  if (
    banco.includes("BRADESCO") ||
    banco === "237" ||
    banco.includes("BANCO BRADESCO")
  ) {
    return "BRADESCO";
  }

  return banco;
}

/*
 * ============================================================
 * IDENTIFICA BANCO, AGÊNCIA E CONTA NO PDF
 * ============================================================
 *
 * Exemplo:
 * Agência: 1693 | Conta: 21530-9
 */

const textoParaCabecalho = texto
  .normalize("NFD")
  .replace(/[\u0300-\u036f]/g, "")
  .replace(/\u00a0/g, " ");

// Aceita cabeçalho com ou sem "|" e com quebra de linha entre os campos.
const cabecalhoConta = textoParaCabecalho.match(
  /AGENCIA\s*:?\s*([0-9]+)[\s|;,-]*CONTA\s*:?\s*([0-9.\-]+)/i
);

if (!cabecalhoConta) {
  const linhasCabecalho = texto
    .split(/\r?\n/)
    .map((linha) => linha.trim())
    .filter(Boolean)
    .slice(0, 30);

  return respostaErro(
    "CABECALHO_BRADESCO_NAO_IDENTIFICADO",
    "Não foi possível identificar a agência e a conta no cabeçalho do extrato Bradesco.",
    ["O formato do cabeçalho deste PDF é diferente do formato esperado."],
    {
      texto_extraido: true,
      formato_esperado: "Agência: 1693 | Conta: 21530-9",
      primeiras_linhas_pdf: linhasCabecalho
    }
  );
}

const agenciaArquivo =
  cabecalhoConta[1];

const contaArquivo =
  cabecalhoConta[2];

/*
 * Exemplo:
 * Nome: ANA CRISTINA LANDUCCI
 */

const cabecalhoTitular = texto.match(
  /NOME\s*:\s*(.+?)(?:\n|EXTRATO\s+DE\s*:)/i
);

const titularArquivo =
  cabecalhoTitular
    ? cabecalhoTitular[1].trim()
    : "";

const dadosArquivo = {
  banco: "BRADESCO",
  agencia: agenciaArquivo,
  conta: contaArquivo,
  titular: titularArquivo
};

/*
 * ============================================================
 * VALIDAÇÃO DA CONTA
 * ============================================================
 */

const bancoSistema = normalizarBanco(
  contaFinanceFlow.banco
);

const bancoArquivo = normalizarBanco(
  dadosArquivo.banco
);

const agenciaSistema = somenteNumeros(
  contaFinanceFlow.agencia
);

const agenciaPdf = somenteNumeros(
  dadosArquivo.agencia
);

const contaSistema = somenteNumeros(
  contaFinanceFlow.conta
);

const contaPdf = somenteNumeros(
  dadosArquivo.conta
);

const divergenciasConta = [];

if (
  bancoSistema &&
  bancoSistema !== bancoArquivo
) {
  divergenciasConta.push(
    `Banco selecionado: ${contaFinanceFlow.banco}; banco do arquivo: ${dadosArquivo.banco}`
  );
}

if (
  agenciaSistema &&
  agenciaSistema !== agenciaPdf
) {
  divergenciasConta.push(
    `Agência selecionada: ${contaFinanceFlow.agencia}; agência do arquivo: ${dadosArquivo.agencia}`
  );
}

if (
  contaSistema &&
  contaSistema !== contaPdf
) {
  divergenciasConta.push(
    `Conta selecionada: ${contaFinanceFlow.conta}; conta do arquivo: ${dadosArquivo.conta}`
  );
}

/*
 * Conta incorreta:
 * interrompe o processamento sem gerar erro técnico.
 */

if (divergenciasConta.length > 0) {
  return [
    {
      json: {
        ok: false,
        conta_validada: false,

        tipo_erro:
          "CONTA_BANCARIA_INCORRETA",

        mensagem:
          "O extrato enviado não pertence à conta selecionada. " +
          "Selecione a conta correta e importe novamente.",

        detalhes:
          divergenciasConta,

        conta_selecionada: {
          id:
            contaFinanceFlow.id,

          nome:
            contaFinanceFlow.nome,

          banco:
            contaFinanceFlow.banco,

          agencia:
            contaFinanceFlow.agencia,

          conta:
            contaFinanceFlow.conta
        },

        conta_arquivo: {
          banco:
            dadosArquivo.banco,

          agencia:
            dadosArquivo.agencia,

          conta:
            dadosArquivo.conta,

          titular:
            dadosArquivo.titular ||
            "Não identificado"
        },

        movimentos: [],
        quantidade: 0
      }
    }
  ];
}

/*
 * ============================================================
 * IDENTIFICA LINHAS QUE NÃO SÃO MOVIMENTOS
 * ============================================================
 */

function ehLinhaCabecalho(linha) {
  const txt = String(linha || "")
    .toUpperCase()
    .trim();

  return (
    txt === "BRADESCO CELULAR" ||
    txt.startsWith("DATA:") ||
    txt.startsWith("NOME:") ||
    txt.startsWith("EXTRATO DE:") ||
    txt.startsWith("FOLHA:") ||
    txt.startsWith("DATA HISTÓRICO") ||
    txt.startsWith("DATA HISTORICO") ||
    txt.startsWith("TOTAL ") ||
    txt === "EXTRATO INEXISTENTE"
  );
}

function ehComplementoTecnico(linha) {
  const txt = String(linha || "")
    .toUpperCase()
    .trim();

  return (
    (
      /^AG\d+/i.test(txt) &&
      txt.includes("MAQ")
    ) ||
    txt.startsWith("EXTRATOMES")
  );
}

/*
 * ============================================================
 * PREPARA AS LINHAS
 * ============================================================
 */

const linhas = normalizarTexto(texto)
  .split("\n")
  .map((linha) => linha.trim())
  .filter(Boolean)
  .filter(
    (linha) => !ehLinhaCabecalho(linha)
  );

const registros = [];

let dataAtual = "";
let historicoPartes = [];
let saldoAnterior = null;
let saldoInicial = null;

function registrarRegistro(
  data,
  historico,
  documento,
  valorTexto,
  saldoTexto
) {
  const valor = numeroBR(valorTexto);
  const saldoAtual = numeroBR(saldoTexto);

  if (saldoInicial === null) {
    saldoInicial = saldoAtual;
  }

  let tipo = null;

  if (saldoAnterior !== null) {
    const saldoSeCredito = saldoAnterior + valor;
    const saldoSeDebito = saldoAnterior - valor;

    if (Math.abs(saldoSeCredito - saldoAtual) < 0.02) {
      tipo = "C";
    } else if (Math.abs(saldoSeDebito - saldoAtual) < 0.02) {
      tipo = "D";
    }
  }

  if (tipo && String(historico || "").trim()) {
    registros.push({
      data,
      historico: String(historico).trim(),
      documento,
      valor,
      tipo,
      saldo: saldoAtual
    });
  }

  saldoAnterior = saldoAtual;
  dataAtual = data;
  historicoPartes = [];
}

/*
 * ============================================================
 * PROCESSA O EXTRATO
 * ============================================================
 */

for (
  let i = 0;
  i < linhas.length;
  i++
) {
  const linha = linhas[i];

  /*
   * Exemplo:
   * 02/04/2026 INSS 0021693 3.497,54 3.502,04
   */

  const linhaCompleta = linha.match(
    /^(\d{2}\/\d{2}\/\d{4})\s+(.+?)\s+(\d+)\s+([\d.]+,\d{2})\s+([\d.]+,\d{2})$/
  );

  if (linhaCompleta) {
    registrarRegistro(
      linhaCompleta[1],
      linhaCompleta[2],
      linhaCompleta[3],
      linhaCompleta[4],
      linhaCompleta[5]
    );

    continue;
  }

  /*
   * Histórico em linha anterior e depois:
   * 06/04/2026 0306761 0,03 3.502,07
   */

  const linhaDataValor = linha.match(
    /^(\d{2}\/\d{2}\/\d{4})\s+(\d+)\s+([\d.]+,\d{2})\s+([\d.]+,\d{2})$/
  );

  if (linhaDataValor) {
    registrarRegistro(
      linhaDataValor[1],
      historicoPartes.filter(Boolean).join(" - ").trim(),
      linhaDataValor[2],
      linhaDataValor[3],
      linhaDataValor[4]
    );

    continue;
  }

  /*
   * Linha contendo somente a data
   */

  const somenteData = linha.match(
    /^(\d{2}\/\d{2}\/\d{4})$/
  );

  if (somenteData) {
    dataAtual =
      somenteData[1];

    historicoPartes =
      [];

    continue;
  }

  /*
   * Mesma data do movimento anterior, com histórico na própria linha:
   * INSS 0021693 5.246,31 5.249,57
   */

  const linhaHistoricoValor = linha.match(
    /^(.+?)\s+(\d+)\s+([\d.]+,\d{2})\s+([\d.]+,\d{2})$/
  );

  if (linhaHistoricoValor && dataAtual) {
    const historico = [
      ...historicoPartes,
      linhaHistoricoValor[1]
    ]
      .filter(Boolean)
      .join(" - ")
      .trim();

    registrarRegistro(
      dataAtual,
      historico,
      linhaHistoricoValor[2],
      linhaHistoricoValor[3],
      linhaHistoricoValor[4]
    );

    continue;
  }

  /*
   * Exemplo:
   * 0306761 0,03 3.502,07
   */

  const linhaValor = linha.match(
    /^(\d+)\s+([\d.]+,\d{2})\s+([\d.]+,\d{2})$/
  );

  if (
    linhaValor &&
    dataAtual
  ) {
    registrarRegistro(
      dataAtual,
      historicoPartes.filter(Boolean).join(" - ").trim(),
      linhaValor[1],
      linhaValor[2],
      linhaValor[3]
    );

    continue;
  }

  /*
   * Complemento do rendimento aparece depois da linha de valor.
   * Anexa ao último rendimento, sem contaminar o próximo movimento.
   */

  if (
    /^POUP\s+FACIL/i.test(linha) &&
    registros.length > 0 &&
    /RENDIMENTOS/i.test(
      registros[registros.length - 1].historico
    )
  ) {
    registros[registros.length - 1].historico +=
      ` - ${linha}`;

    continue;
  }

  /*
   * Ignora códigos técnicos de ATM.
   */

  if (
    ehComplementoTecnico(linha)
  ) {
    continue;
  }

  /*
   * Guarda as linhas do histórico
   * até encontrar documento, valor e saldo.
   */

  historicoPartes.push(
    linha
  );
}

/*
 * ============================================================
 * FORMATA OS MOVIMENTOS
 * ============================================================
 */

const movimentos = registros.map(
  (registro) => ({
    data:
      registro.data,

    historico:
      registro.historico,

    valor:
      registro.valor,

    tipo:
      registro.tipo
  })
);

const totalCreditos = registros
  .filter((registro) => registro.tipo === "C")
  .reduce((total, registro) => total + registro.valor, 0);

const totalDebitos = registros
  .filter((registro) => registro.tipo === "D")
  .reduce((total, registro) => total + registro.valor, 0);

const saldoFinal = saldoAnterior;
const saldoCalculado = saldoInicial === null
  ? null
  : saldoInicial + totalCreditos - totalDebitos;

const diferencaSaldo =
  saldoFinal === null || saldoCalculado === null
    ? null
    : Number((saldoFinal - saldoCalculado).toFixed(2));

const saldoConfere =
  diferencaSaldo === null
    ? false
    : Math.abs(diferencaSaldo) <= 0.02;

/*
 * ============================================================
 * RETORNO FINAL DO N8N
 * ============================================================
 */

return [
  {
    json: {
      ok: true,
      conta_validada: true,

      empresa_id:
        contaFinanceFlow.empresa_id,

      conta_id:
        contaFinanceFlow.id,

      finalidade:
        entrada.finalidade ||
        entrada.body?.finalidade ||
        contaBanco.finalidade ||
        "",

      banco:
        "BRADESCO",

      dados_conta_arquivo: {
        banco:
          dadosArquivo.banco,

        agencia:
          dadosArquivo.agencia,

        conta:
          dadosArquivo.conta,

        titular:
          dadosArquivo.titular
      },

      dados_conta_financeflow: {
        id:
          contaFinanceFlow.id,

        nome:
          contaFinanceFlow.nome,

        banco:
          contaFinanceFlow.banco,

        agencia:
          contaFinanceFlow.agencia,

        conta:
          contaFinanceFlow.conta
      },

      movimentos,

      quantidade:
        movimentos.length,

      diagnostico: {
        conta_validada: true,

        quantidade_linhas:
          linhas.length,

        quantidade_registros:
          registros.length,

        creditos:
          registros.filter((registro) => registro.tipo === "C").length,

        debitos:
          registros.filter((registro) => registro.tipo === "D").length,

        total_creditos:
          Number(totalCreditos.toFixed(2)),

        total_debitos:
          Number(totalDebitos.toFixed(2)),

        saldo_inicial:
          saldoInicial,

        saldo_final:
          saldoFinal,

        saldo_calculado:
          saldoCalculado === null
            ? null
            : Number(saldoCalculado.toFixed(2)),

        diferenca_saldo:
          diferencaSaldo,

        saldo_confere:
          saldoConfere,

        primeiro_movimento:
          movimentos[0] || null,

        ultimo_movimento:
          movimentos[
            movimentos.length - 1
          ] || null
      }
    }
  }
];

 /*
|-----------------------------------------------------------------------------
| IMPORTAÇÃO DE EXTRATO - BANCO DO BRASIL
| Layouts validados: "Extrato de Conta Corrente" e "Extrato de Conta Salário"
| Também aceita variações de cabeçalho PF/PJ que mantenham os campos
| Cliente, Período, Agência, Conta, Lançamentos, Histórico e Valor.
|-----------------------------------------------------------------------------
*/

/*
|-----------------------------------------------------------------------------
| ENTRADAS
|-----------------------------------------------------------------------------
*/

// PostgreSQL imediatamente anterior ao Code.
const contaBanco = $input.first().json;

// Troque "ExtractBB" somente se o seu nó de extração tiver outro nome.
const entrada = $('ExtractBB').first().json;

const texto = String(
  entrada.text ||
  entrada.texto_pdf ||
  entrada.data?.text ||
  entrada.data?.texto_pdf ||
  ""
);

if (!texto.trim()) {
  throw new Error("O PDF não retornou texto para processamento.");
}


/*
|-----------------------------------------------------------------------------
| CONTA CADASTRADA NO FINANCEFLOW
|-----------------------------------------------------------------------------
*/

const contaFinanceFlow = {
  id: contaBanco.id || contaBanco.conta_id,
  empresa_id:
    contaBanco.empresa_id ||
    entrada.empresa_id ||
    entrada.body?.empresa_id,
  nome: contaBanco.nome || contaBanco.conta_nome || "",
  banco: contaBanco.banco || contaBanco.banco_nome || "",
  agencia: contaBanco.agencia || "",
  conta: contaBanco.conta || contaBanco.numero_conta || ""
};

if (!contaFinanceFlow.id) {
  throw new Error("A conta financeira selecionada não foi encontrada no FinanceFlow.");
}

if (!contaFinanceFlow.banco) {
  throw new Error("A conta selecionada não possui banco cadastrado no FinanceFlow.");
}

if (!contaFinanceFlow.agencia) {
  throw new Error("A conta selecionada não possui agência cadastrada no FinanceFlow.");
}

if (!contaFinanceFlow.conta) {
  throw new Error("A conta selecionada não possui número da conta cadastrada no FinanceFlow.");
}


/*
|-----------------------------------------------------------------------------
| FUNÇÕES AUXILIARES
|-----------------------------------------------------------------------------
*/

function normalizarTexto(valor) {
  return String(valor || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toUpperCase()
    .replace(/\s+/g, " ")
    .trim();
}

function somenteNumeros(valor) {
  const numeros = String(valor || "").replace(/\D/g, "");
  return numeros.replace(/^0+/, "") || "0";
}

function numeroPrincipalBB(valor) {
  const original = String(valor || "").trim();
  const antesDoDigito = original.split("-")[0];
  return somenteNumeros(antesDoDigito);
}

/*
| Aceita, por exemplo:
| agência do sistema 419 ou 4197 para PDF 419-7;
| conta do sistema 36835 ou 368350 para PDF 36835-0.
*/
function numerosBancariosEquivalentes(valorSistema, valorPdf) {
  const sistemaCompleto = somenteNumeros(valorSistema);
  const pdfCompleto = somenteNumeros(valorPdf);
  const sistemaPrincipal = numeroPrincipalBB(valorSistema);
  const pdfPrincipal = numeroPrincipalBB(valorPdf);

  return (
    sistemaCompleto === pdfCompleto ||
    sistemaCompleto === pdfPrincipal ||
    sistemaPrincipal === pdfCompleto ||
    sistemaPrincipal === pdfPrincipal
  );
}

function normalizarBanco(valor) {
  const banco = normalizarTexto(valor);
  const codigo = somenteNumeros(valor);

  if (
    banco.includes("BANCO DO BRASIL") ||
    banco === "BB" ||
    codigo === "1"
  ) {
    return "BANCO DO BRASIL";
  }

  return banco;
}

function converterValorBR(valor) {
  const textoValor = String(valor || "")
    .replace(/\s/g, "")
    .replace(/R\$/gi, "")
    .trim();

  const numero = Number(
    textoValor
      .replace(/\./g, "")
      .replace(",", ".")
  );

  return Number.isFinite(numero) ? numero : 0;
}

function valorComSinal(valor, sinal) {
  const numero = Math.abs(converterValorBR(valor));
  return sinal === "-" ? numero * -1 : numero;
}

function criarDataISO(ano, mes, dia) {
  return (
    `${String(ano).padStart(4, "0")}-` +
    `${String(mes).padStart(2, "0")}-` +
    `${String(dia).padStart(2, "0")}`
  );
}

function dataBrParaISO(dataBr) {
  const match = String(dataBr || "").match(
    /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/
  );

  return match
    ? criarDataISO(match[3], match[2], match[1])
    : "";
}

function limparHistorico(valor) {
  return String(valor || "")
    .replace(/\s+/g, " ")
    .trim();
}

function retornoErro(tipoErro, mensagem, detalhes, contaValidada, dadosArquivo = null) {
  return [
    {
      json: {
        ok: false,
        conta_validada: contaValidada,
        tipo_erro: tipoErro,
        mensagem,
        detalhes,
        conta_selecionada: {
          id: contaFinanceFlow.id,
          nome: contaFinanceFlow.nome,
          banco: contaFinanceFlow.banco,
          agencia: contaFinanceFlow.agencia,
          conta: contaFinanceFlow.conta
        },
        ...(dadosArquivo
          ? {
              conta_arquivo: {
                banco: dadosArquivo.banco,
                agencia: dadosArquivo.agencia,
                conta: dadosArquivo.conta,
                titular: dadosArquivo.titular || "Não identificado"
              }
            }
          : {}),
        movimentos: [],
        quantidade: 0
      }
    }
  ];
}


/*
|-----------------------------------------------------------------------------
| IDENTIFICA O LAYOUT BANCO DO BRASIL
|-----------------------------------------------------------------------------
*/

const textoNormalizado = normalizarTexto(texto);

const tituloEhContaCorrente =
  textoNormalizado.includes("EXTRATO DE CONTA CORRENTE");

const tituloEhContaSalario =
  textoNormalizado.includes("EXTRATO DE CONTA SALARIO");

const arquivoEhBancoDoBrasil =
  (tituloEhContaCorrente || tituloEhContaSalario) &&
  textoNormalizado.includes("AGENCIA") &&
  textoNormalizado.includes("CONTA") &&
  textoNormalizado.includes("LOTE") &&
  textoNormalizado.includes("DOCUMENTO") &&
  textoNormalizado.includes("HISTORICO") &&
  (
    tituloEhContaSalario ||
    textoNormalizado.includes("BANCO DO BRASIL") ||
    textoNormalizado.includes("APLICACOES FINANCEIRAS") ||
    textoNormalizado.includes("BB RENDE FACIL") ||
    textoNormalizado.includes("BB CDB")
  );

if (!arquivoEhBancoDoBrasil) {
  return retornoErro(
    "LAYOUT_BANCO_DO_BRASIL_NAO_RECONHECIDO",
    "O arquivo não foi identificado como extrato de conta corrente ou conta salário do Banco do Brasil.",
    [
      "Este parser trata os layouts Banco do Brasil de conta corrente e conta salário que contêm cabeçalho, agência, conta e lançamentos."
    ],
    false
  );
}


/*
|-----------------------------------------------------------------------------
| TITULAR, AGÊNCIA E CONTA
|-----------------------------------------------------------------------------
*/

const titularMatch = texto.match(/CLIENTE\s*:\s*([^\r\n]+)/i);
const agenciaMatch = texto.match(/AG[EÊ]NCIA\s*:\s*([0-9.]+(?:\s*-\s*[0-9A-Z])?)/i);
const contaMatch = texto.match(/CONTA\s*:\s*([0-9.]+(?:\s*-\s*[0-9A-Z])?)/i);

const titularArquivo = titularMatch
  ? titularMatch[1].replace(/\s+/g, " ").trim()
  : "";

const agenciaArquivo = agenciaMatch
  ? agenciaMatch[1].replace(/\s+/g, "")
  : "";

const contaArquivo = contaMatch
  ? contaMatch[1].replace(/\s+/g, "")
  : "";

const dadosArquivo = {
  banco: "BANCO DO BRASIL",
  agencia: agenciaArquivo,
  conta: contaArquivo,
  titular: titularArquivo
};

if (!agenciaArquivo || !contaArquivo) {
  return retornoErro(
    "CONTA_NAO_IDENTIFICADA_NO_ARQUIVO",
    "Não foi possível identificar agência e conta no extrato do Banco do Brasil.",
    [
      "O PDF foi identificado como Banco do Brasil, mas agência/conta não foram encontradas no cabeçalho."
    ],
    false,
    dadosArquivo
  );
}


/*
|-----------------------------------------------------------------------------
| COMPARA BANCO, AGÊNCIA E CONTA
|-----------------------------------------------------------------------------
*/

const bancoSistema = normalizarBanco(contaFinanceFlow.banco);
const bancoArquivo = normalizarBanco(dadosArquivo.banco);
const divergenciasConta = [];

if (bancoSistema && bancoSistema !== bancoArquivo) {
  divergenciasConta.push(
    `Banco selecionado: ${contaFinanceFlow.banco}; banco do arquivo: ${dadosArquivo.banco}`
  );
}

if (!numerosBancariosEquivalentes(contaFinanceFlow.agencia, dadosArquivo.agencia)) {
  divergenciasConta.push(
    `Agência selecionada: ${contaFinanceFlow.agencia}; agência do arquivo: ${dadosArquivo.agencia}`
  );
}

if (!numerosBancariosEquivalentes(contaFinanceFlow.conta, dadosArquivo.conta)) {
  divergenciasConta.push(
    `Conta selecionada: ${contaFinanceFlow.conta}; conta do arquivo: ${dadosArquivo.conta}`
  );
}

if (divergenciasConta.length > 0) {
  return retornoErro(
    "CONTA_BANCARIA_INCORRETA",
    "O extrato enviado não pertence à conta selecionada. Selecione a conta correta e importe novamente.",
    divergenciasConta,
    false,
    dadosArquivo
  );
}


/*
|-----------------------------------------------------------------------------
| PERÍODO DO EXTRATO
| Aceita:
| Período: 01 a 31/07/2026
| Período: 01/07/2026 a 31/07/2026
|-----------------------------------------------------------------------------
*/

const textoPeriodo = normalizarTexto(texto);
let dataInicio = "";
let dataFim = "";

const periodoCompletoMatch = textoPeriodo.match(
  /PERIODO\s*:\s*(\d{1,2})\/(\d{1,2})\/(\d{4})\s*(?:A|ATE|-)\s*(\d{1,2})\/(\d{1,2})\/(\d{4})/i
);

const periodoCurtoMatch = textoPeriodo.match(
  /PERIODO\s*:\s*(\d{1,2})\s*(?:A|ATE|-)\s*(\d{1,2})\/(\d{1,2})\/(\d{4})/i
);

if (periodoCompletoMatch) {
  dataInicio = criarDataISO(
    periodoCompletoMatch[3],
    periodoCompletoMatch[2],
    periodoCompletoMatch[1]
  );
  dataFim = criarDataISO(
    periodoCompletoMatch[6],
    periodoCompletoMatch[5],
    periodoCompletoMatch[4]
  );
} else if (periodoCurtoMatch) {
  dataInicio = criarDataISO(
    periodoCurtoMatch[4],
    periodoCurtoMatch[3],
    periodoCurtoMatch[1]
  );
  dataFim = criarDataISO(
    periodoCurtoMatch[4],
    periodoCurtoMatch[3],
    periodoCurtoMatch[2]
  );
}

if (!dataInicio || !dataFim) {
  return retornoErro(
    "PERIODO_NAO_IDENTIFICADO",
    "Não foi possível identificar o período do extrato do Banco do Brasil.",
    ["A conta foi validada, mas o período do extrato não foi localizado."],
    true,
    dadosArquivo
  );
}


/*
|-----------------------------------------------------------------------------
| PREPARA SOMENTE A SEÇÃO DE LANÇAMENTOS
|-----------------------------------------------------------------------------
*/

const todasAsLinhas = texto
  .replace(/\r/g, "")
  .split("\n")
  .map(linha =>
    linha
      .replace(/\u00A0/g, " ")
      .replace(/\s+/g, " ")
      .trim()
  )
  .filter(Boolean);

const linhasLancamentos = [];
let dentroDosLancamentos = false;

for (const linha of todasAsLinhas) {
  const normalizada = normalizarTexto(linha);

  if (normalizada === "LANCAMENTOS") {
    dentroDosLancamentos = true;
    continue;
  }

  if (normalizada.startsWith("APLICACOES FINANCEIRAS")) {
    break;
  }

  if (dentroDosLancamentos) {
    if (
      normalizada.startsWith("DIA LOTE DOCUMENTO HISTORICO VALOR") ||
      normalizada === "DIA" ||
      normalizada === "LOTE" ||
      normalizada === "DOCUMENTO" ||
      normalizada === "HISTORICO" ||
      normalizada === "VALOR"
    ) {
      continue;
    }

    linhasLancamentos.push(linha);
  }
}

// Compatibilidade com extrações que não preservam o título "Lançamentos".
if (!linhasLancamentos.length) {
  for (const linha of todasAsLinhas) {
    if (normalizarTexto(linha).startsWith("APLICACOES FINANCEIRAS")) {
      break;
    }
    linhasLancamentos.push(linha);
  }
}


/*
|-----------------------------------------------------------------------------
| AGRUPA LINHAS QUE PERTENCEM AO MESMO LANÇAMENTO
|-----------------------------------------------------------------------------
*/

const blocos = [];
let blocoAtual = null;

for (const linha of linhasLancamentos) {
  const inicioMatch = linha.match(/^(\d{1,2}\/\d{1,2}\/\d{4})\s+(.+)$/);

  if (inicioMatch) {
    if (blocoAtual) {
      blocos.push(blocoAtual);
    }

    blocoAtual = {
      data_br: inicioMatch[1],
      primeira_linha: inicioMatch[2],
      continuacoes: []
    };
  } else if (blocoAtual) {
    blocoAtual.continuacoes.push(linha);
  }
}

if (blocoAtual) {
  blocos.push(blocoAtual);
}


/*
|-----------------------------------------------------------------------------
| EXTRAÇÃO DOS MOVIMENTOS E SALDOS
|-----------------------------------------------------------------------------
*/

const regexValorFinal = /(\d{1,3}(?:\.\d{3})*,\d{2}|\d+,\d{2})\s*\(([+-])\)\s*$/;
const regexValorInicial = /^(\d{1,3}(?:\.\d{3})*,\d{2}|\d+,\d{2})\s*\(([+-])\)\s*(.*)$/;
const movimentosInternos = [];
const ignoradas = [];

let saldoInicialArquivo = null;
let saldoFinalArquivo = null;
let ordemArquivo = 0;

for (const bloco of blocos) {
  ordemArquivo += 1;

  const data = dataBrParaISO(bloco.data_br);
  const valorFinalMatch = bloco.primeira_linha.match(regexValorFinal);
  const valorInicialMatch = bloco.primeira_linha.match(regexValorInicial);

  if (!valorFinalMatch && !valorInicialMatch) {
    ignoradas.push({
      linha: `${bloco.data_br} ${bloco.primeira_linha} ${bloco.continuacoes.join(" ")}`.trim(),
      motivo: "VALOR_NAO_IDENTIFICADO"
    });
    continue;
  }

  const valorMatch = valorFinalMatch || valorInicialMatch;
  const valorAssinado = valorComSinal(valorMatch[1], valorMatch[2]);

  // Alguns extratores mantêm o valor no fim da linha; outros devolvem
  // DATA + VALOR + LOTE + DOCUMENTO + HISTÓRICO, especialmente em conta salário.
  let corpo = valorFinalMatch
    ? bloco.primeira_linha.slice(0, valorFinalMatch.index).trim()
    : valorInicialMatch[3].trim();
  const continuacao = limparHistorico(bloco.continuacoes.join(" "));
  const corpoNormalizado = normalizarTexto(`${corpo} ${continuacao}`);
  const corpoCompacto = corpoNormalizado.replace(/\s/g, "");

  const ehSaldoAnterior = corpoNormalizado.includes("SALDO ANTERIOR");
  const ehSaldoDoDia = corpoNormalizado.includes("SALDO DO DIA");
  const ehSaldoFinal = corpoCompacto === "SALDO";

  if (ehSaldoAnterior) {
    saldoInicialArquivo = valorAssinado;
    continue;
  }

  if (ehSaldoDoDia) {
    saldoFinalArquivo = valorAssinado;
    continue;
  }

  if (ehSaldoFinal) {
    saldoFinalArquivo = valorAssinado;
    continue;
  }

  if (data < dataInicio || data > dataFim) {
    ignoradas.push({
      linha: `${bloco.data_br} ${bloco.primeira_linha} ${continuacao}`.trim(),
      motivo: "DATA_FORA_DO_PERIODO"
    });
    continue;
  }

  // Remove lote e documento numéricos que aparecem antes do histórico.
  const partes = corpo.split(/\s+/).filter(Boolean);
  const identificadores = [];

  while (partes.length && /^\d+$/.test(partes[0]) && identificadores.length < 2) {
    identificadores.push(partes.shift());
  }

  const documento = identificadores.length
    ? identificadores[identificadores.length - 1]
    : "";

  const historico = limparHistorico(`${partes.join(" ")} ${continuacao}`);

  if (!historico || valorAssinado === 0) {
    ignoradas.push({
      linha: `${bloco.data_br} ${bloco.primeira_linha} ${continuacao}`.trim(),
      motivo: "MOVIMENTO_INVALIDO"
    });
    continue;
  }

  movimentosInternos.push({
    data,
    historico,
    documento,
    valor: Math.abs(valorAssinado),
    valor_assinado: valorAssinado,
    tipo: valorAssinado < 0 ? "D" : "C",
    saldo: null,
    natureza_financeira: null,
    ordem_arquivo: ordemArquivo
  });
}

if (!movimentosInternos.length) {
  return [
    {
      json: {
        ok: false,
        conta_validada: true,
        tipo_erro: "MOVIMENTOS_NAO_ENCONTRADOS",
        mensagem: "Nenhuma movimentação válida foi encontrada no extrato do Banco do Brasil.",
        detalhes: [
          "O banco e a conta foram validados, mas o formato das movimentações não foi reconhecido."
        ],
        conta_selecionada: {
          id: contaFinanceFlow.id,
          nome: contaFinanceFlow.nome,
          banco: contaFinanceFlow.banco,
          agencia: contaFinanceFlow.agencia,
          conta: contaFinanceFlow.conta
        },
        conta_arquivo: dadosArquivo,
        movimentos: [],
        quantidade: 0,
        quantidade_ignoradas: ignoradas.length,
        linhas_ignoradas: ignoradas
      }
    }
  ];
}


/*
|-----------------------------------------------------------------------------
| ORDENA CRONOLOGICAMENTE E CALCULA SALDO APÓS CADA MOVIMENTO
|-----------------------------------------------------------------------------
*/

movimentosInternos.sort((a, b) => {
  const porData = a.data.localeCompare(b.data);
  return porData !== 0 ? porData : a.ordem_arquivo - b.ordem_arquivo;
});

const totalCreditos = movimentosInternos
  .filter(movimento => movimento.tipo === "C")
  .reduce((total, movimento) => total + movimento.valor, 0);

const totalDebitos = movimentosInternos
  .filter(movimento => movimento.tipo === "D")
  .reduce((total, movimento) => total + movimento.valor, 0);

if (saldoInicialArquivo === null && saldoFinalArquivo !== null) {
  saldoInicialArquivo = saldoFinalArquivo - totalCreditos + totalDebitos;
}

let saldoEmAndamento = saldoInicialArquivo;

for (const movimento of movimentosInternos) {
  if (saldoEmAndamento !== null) {
    saldoEmAndamento += movimento.valor_assinado;
    movimento.saldo = Number(saldoEmAndamento.toFixed(2));
  }
}

const saldoInicial = saldoInicialArquivo;
const saldoCalculado = saldoInicial !== null
  ? saldoInicial + totalCreditos - totalDebitos
  : null;

const saldoFinal = saldoFinalArquivo !== null
  ? saldoFinalArquivo
  : saldoCalculado;

const diferencaSaldo =
  saldoCalculado !== null && saldoFinal !== null
    ? saldoCalculado - saldoFinal
    : null;

const saldoConfere =
  diferencaSaldo !== null
    ? Math.abs(diferencaSaldo) <= 0.01
    : false;

const movimentos = movimentosInternos.map(
  ({ valor_assinado, ordem_arquivo, ...movimento }) => movimento
);


/*
|-----------------------------------------------------------------------------
| RETORNO FINAL
|-----------------------------------------------------------------------------
*/

return [
  {
    json: {
      ok: true,
      conta_validada: true,
      empresa_id: contaFinanceFlow.empresa_id,
      conta_id: contaFinanceFlow.id,
      finalidade:
        entrada.finalidade ||
        entrada.body?.finalidade ||
        contaBanco.finalidade ||
        "IMPORTACAO",
      banco: "BANCO DO BRASIL",
      dados_conta_arquivo: dadosArquivo,
      dados_conta_financeflow: {
        id: contaFinanceFlow.id,
        nome: contaFinanceFlow.nome,
        banco: contaFinanceFlow.banco,
        agencia: contaFinanceFlow.agencia,
        conta: contaFinanceFlow.conta
      },
      data_inicio: dataInicio,
      data_fim: dataFim,
      movimentos,
      quantidade: movimentos.length,
      quantidade_ignoradas: ignoradas.length,
      linhas_ignoradas: ignoradas,
      diagnostico: {
        tipo_layout: tituloEhContaSalario
          ? "BANCO_DO_BRASIL_CONTA_SALARIO"
          : "BANCO_DO_BRASIL_CONTA_CORRENTE",
        quantidade_linhas: todasAsLinhas.length,
        quantidade_blocos: blocos.length,
        quantidade_creditos: movimentos.filter(movimento => movimento.tipo === "C").length,
        quantidade_debitos: movimentos.filter(movimento => movimento.tipo === "D").length,
        total_creditos: Number(totalCreditos.toFixed(2)),
        total_debitos: Number(totalDebitos.toFixed(2)),
        saldo_inicial: saldoInicial !== null ? Number(saldoInicial.toFixed(2)) : null,
        saldo_final: saldoFinal !== null ? Number(saldoFinal.toFixed(2)) : null,
        saldo_calculado: saldoCalculado !== null ? Number(saldoCalculado.toFixed(2)) : null,
        diferenca_saldo: diferencaSaldo !== null ? Number(diferencaSaldo.toFixed(2)) : null,
        saldo_confere: saldoConfere,
        primeiro_movimento: movimentos[0] || null,
        ultimo_movimento: movimentos[movimentos.length - 1] || null
      }
    }
  }
];

parameters.query:
 SELECT
    id,
    empresa_id,
    nome,
    banco,
    agencia,
    conta
FROM public.contas_financeiras
WHERE empresa_id = {{
  Number($('extrato_pdf_bb').first().json.body?.empresa_id
      || $('extrato_pdf_bb').first().json.empresa_id)
}}
AND id = {{
  Number($('extrato_pdf_bb').first().json.body?.conta_id
      || $('extrato_pdf_bb').first().json.conta_id)
}}
LIMIT 1;
